"ratedAt": "2020-02-24",
"review": "Still in the style of Peter Handke, his text strips away time and space, and the hero wanders recklessly through different spaces - Wings of Desire does the same. Within the framework of such a plot, Handke presents the precise metaphor of the goalkeeper, with the hero's own identity as a goalkeeper intertextualised with his own experiences; and behind the seemingly erratic actions of the hero as he roams are the consequences of a lack of communication and distorted judgement. The subtitle's introduction sums it up well: an immobilised state of preoccupation with too many possible situations - This is exactly the point. People are inexplicably estranged from each other, and this estrangement cannot be separated from the context of the times. After reading and marvelling at Handke's extremely strong literary skills, it's no surprise that he was able to win the Nobel Prize. (Machine translation from my Chinese review)",
