"review": "Haneke's own \"funny games\" don't interest me, but the story itself is something to think about, where violence is never an end in itself (as Haneke almost never turns his camera on it), but rather arises out of the manipulation of one party by the other. In this environment, violence actually takes on legitimacy, and it doesn't surprise us that either party commits it; we actually expect it and empower ourselves to transgress the boundaries. We actually construct a story line for the story that doesn't exist, which is scarier than the story itself. (Machine translation from my Chinese review)",
