"ratedAt": "2022-01-17",
"review": "It may be difficult to understand this film without understanding the importance of football to Italy and Maradona to Naples. On Fabietto is the scrutinising gaze cast by Sorrentino 40 years later, and because of this his character traits are out of place, as he seems to witness the inevitable decline of the city, despite the fact that they welcomed Maradona and despite the fact that they won the Serie A title. Maradona is the god of the city and the symbol of the brief revelry of the people of Naples. So looking back at the whole film, it's not only a coming-of-age story mixed with many emotions and memories, it's also Sorrentino's elegy to his hometown. When decline inevitably comes, when Maradona will one day leave, the Neapolitans choose to revel -- It is a total tragedy. (Machine translation from my Chinese review)",
