"review": "剧作野心极大，试图以成都为空间展开三代人的家族故事，以此折射女性困境，但接近3小时的时长却仍然没能使文本齐整顺畅，有太多细节一笔带过，情节丰满而台词干瘪，有时候明明话没说完，就切到下一段落。导演用了很多间离的手法将影像以切片式的片段呈现，这无疑使得现实的肌理更为丰富自然。对于具体事件的处理不同于《石门》的悲剧性批判与讽刺，在成都这一城市空间中展开的情节有了《好东西》那样的细腻纹理，反映城乡对立和女性困境切身可感，或许欠缺的只是更精炼、更流畅的情节处理，以及不必强扭主题和结局的优化选择。",
