window.LB_REVIEWS = {
"1925|西行": "千牛进城名场面，如此热闹的场面里，基顿扮演的“Friendless”这时才终于感到自己的存在，他穿着红色连体衣在街上穿行，这样的喜悦、自豪真是无与伦比，它代表着对规训秩序的不屑，也是前半段角色几经周折、三步一倒的情感释放——这时又必须佩服基顿极其精准的表演，不论是面部表情还是肢体动作，都体现对人物的深刻洞察。27th SIFF",
"1934|神女": "揭露社会顽疾和民族群体性的命运循环悲剧，令人肝肠寸断的不在于她在狱中嘱咐别人照顾自己的孩子，而是让他从此失去母亲，如此才能顺利活下去——这一切都在配乐的烘托中达到顶峰，而阮玲玉的表演无疑登峰造极，这一角色眼神之中的悲凉、坚定甚至愤怒，都体现超越时代的深刻意义，那些压迫与封建性的残留至今也仍然存在，望向摄影机的阮玲玉是来自过去的神女，她的眼神冲破近百年的黑暗，仍然叩问着当下的不公与压迫。",
"1935|三十九级台阶": "技巧纯熟、视听俱佳的英式谍战主旋律，开场人群的俯拍镜头、火车追逐戏和最后的谜底揭晓都印象深刻。对话和景观让人回到1930年代的英国，也在影像的外部透露出两次世界大战期间紧张的时代气氛，这样的“全球阴谋”故事无疑具有十足的预见性，与此同时又是娱乐的。27th SIFF",
"1949|哀乐中年": "跨越近百年仍振聋发聩的精彩文本，折射出中国文化内部长久的矛盾与冲突，也让人不禁想问至今为止哪些东西变了，哪些东西还在。影像虽仍是早期电影的构建方式，但很多细节能看出从运动向时间转变的萌芽，悬念也不全靠对白营造和揭晓，让人看到中国电影最好的那一面。",
"1957|控方证人": "对话的锋芒，“她处决了他”； 法庭戏的元电影意识； 结尾反转是不是过于突然且刻意了？",
"1959|广岛之恋": "SIFF26：可能是文学与电影的最佳邂逅之一。",
"1961|去年在马里昂巴德": "用精妙的影像游戏和文本结构完成了对历史的回眸、对幽灵的凝视，不去追求所谓的真实，而是在如此华丽的梦魇之中宣告万物之虚假和幽浮，正如那些凝固的人像、消逝的爱情、失去倒影的植物和可怖的平面透视图。当钟声敲响十二下，一切似乎结束又重新开始，那些庄严腐朽之物继续在文明的废墟中耀武扬威。",
"1961|长别离": "SIFF26：导演不如雷乃有很强的左岸派印记，因此处理文本时更平易，也抹平了一些情感的沟壑。杜拉斯文本的局限性，也在影像的凝滞中得以体现：至少在一次次呼唤Albert的过程中，情感的指向可以是单向而自私的；男主角最后举起双手的情感震撼，又在一定程度上跨越了情思的窠臼。",
"1962|五至七时的克莱奥": "克莱奥在路人的目光下急促行走，影像序列的组织方式来自《穆府的歌剧》，但那种发自内心的焦虑感和影像的呼吸感，又由着松散有力的叙事迸发出极大的震撼。时间的流逝与空间的跳跃赋予纪实质感，而不拘一格的剪辑则让我们看到克莱奥最真实、最切身的模样。克莱奥从一处前往另一处，周围的景观变化与收音机的时事新闻让人相信这一切都曾发生过，不论是那些急促的情感、偶然的邂逅还是顿悟之后缺失的时间，瓦尔达用灵动的笔触轻轻勾勒，让人流连而不沉溺。",
"1962|祖与占": "所以说，一切乱搞男女关系的源泉都是历史巨变吗？被浓烈而交缠的情感不断调动，却也感到特吕弗在视听层面的力不从心。当然，它也是一部脱产的新浪潮电影。",
"1962|审判": "原著中大段的心理描写和对白被威尔斯重新诠释为极具表现主义特征的壮丽影像，极具冲击力和震撼力的特写、运镜可谓疯狂，无不透露出重塑经典的大师风范。当然，卡夫卡小说中独具一格的思辨和冰冷的勾勒，或许也失掉不少。",
"1963|宇宙终点之旅": "用材质、声音和身体体征进行科幻叙事非常超前，装修风格、人物设定和存在主义的哲思无疑也影响了此后大量的科幻电影。而单论影片本身其实较为寡淡，对2163年的想象囿于时代显得过时肤浅，情节也缺乏足够震撼的起承转合，结尾似乎还是没能在反思的基础上更进一步，反倒戛然而止了。27th SIFF",
"1964|法外之徒": "拍得很好，道理也都懂，但是戈达尔确实是有点厌女了。",
"1966|白色巨塔": "SIFF26：本届上影节看过的最佳，左翼导演应有的力度，应该是淋漓尽致，哪怕嬉笑怒骂都透露出血淋淋的真实。山本萨夫的技法与影片刻画的对象一样，像手术刀般精准无比，景别的切换和摄影机的运动都让人拍手叫好，情绪的铺陈也层层递进，最后达到顶峰：看着财前五郎带着一批医生在医院中迈出坚定步伐，一阵惊悚涌上心头，你会觉得这一切似乎从未变过，跨越时间和国界。",
"1967|玩乐时间": "塔蒂对战后法国现代化社会景观和历史的深刻洞察造就了这部伟大的电影，而最难得可贵的莫过于那些继承自默片传统的人物动作和情节，与影片文本结合得如此天衣无缝，让人完全沉浸在塔蒂创造的世界之中。",
"1967|毕业生": "可以想象到这个故事在当时对社会带来的冲击，从一开始的循规蹈矩到逐渐疯狂，时至今日再看不仅是对这种急剧转变的惊叹、对痴情妄想男主的叹息，更叠加一层关照自身的批判意味，多年过去似乎一切还倒退了。当然拍法还是很老套，中间一段配乐用四五次一度想差评了，结尾也像是为醋包饺子。",
"1969|水晶的结构": "你想活出怎样的人生？迥异的生活方式展现了不同人生观的碰撞，有能教授反复游说、嘲讽，甚至以他人的妻子相逼，但真的有谁对谁错，谁的生活更“上进”吗？夫妻二人坚定的眼神无疑说明了一切。由雪地而始又在大雪中作结，面对这样的冲突能够淡然处之，内心就像水晶一般澄澈。扎努西的影像在沉稳中变化多端，手持镜头的快速剪辑尤为过瘾。而拍两个男角色的亲密友谊，甚至在过度的男性气氛中产生了一丝同性情愫，倒是反映了意识形态之下的男性不可言说的脆弱倾向。",
"1971|内陆惊魂": "喝不完的酒、杀不尽的动物，“穷山恶土出刁民”的批判主题无疑是对澳大利亚“国民性”压抑的反思，也是对无尽纵欲和暴力最直接、最残暴的揭露和批判。在酒精和猎枪的循环往复之间，男主角像个异类，于是等待他的只有吞噬——那滴眼泪就是求生不得，求死不能的最好诠释，也是影片向本土观众开出的最震撼一枪。",
"1972|桑比赞加": "绝无奇观化呈现的革命影像以女性动人的寻夫故事展开，载歌载舞的结尾充满希望与力量，但也淹没了她的身影——只有那些同样来自女性、孩童和老人的注视以及可感的炎热，才让反殖民的斗争在她身上真正投下影子。15th BJIFF",
"1975|小河马雨果": "以儿童视角展开的动画作品，颜色鲜艳而想象力丰富，对视觉效果和音效的追求令人印象深刻；奇特的情节背后却承载了反殖民、动物保护甚至反抗霸权的议题，显得十分深刻，尽管有时代因素带来的角色刻板印象，但文本中最突出的莫过于一种天下大同的地球村概念，借由孩子的童真呼唤世界的美好，是那个年代对未来的纯洁期待——可惜如今真正剩下的只有片中那些邪恶的人和事，属实令人感到悲伤。27th SIFF",
"1975|大白鲨": "放在美国小镇疑案的序列里不算最好的，后半部分确实变成纯抓鱼了，缺乏前半段危机的线头不断扯出来的感觉，结尾也没有回到小镇，突然就结束了。但是作为惊悚片又太先进了，能理解为什么《密探》要致敬它，众声喧哗、危机四伏的不可预测性，以及超越常规的摄影机运动，今时今日都令人叹服。",
"1977|第三类接触": "差不多50年前，外星生物或许还处于有和无的争辩中，在那个童真与冲动仍被鼓励的年代，斯皮尔伯格用UFO动员起全人类的情感震荡，纯粹的感召让前赴后继成为一种朝圣，尽管语言混杂而难以沟通，但信念感及其所驱动的积极探索，都令人动容。剧作上完全围绕这种专注感展开，在不断的“揭秘”中我们能看到人类对自身渺小的认识，以及对潜在的美好未来的一种想象。",
"1977|我父我主": "SIFF26：追新现实主义传统，用极具张力的笔触勾勒反权威（不只是父权）的宣言。难得的地方是发现了军队统治与父权压迫的一致性，窒息感是类似的。囿于时代限制，女性角色存在感较弱，反父权的部分也不是由女性来主导，一番斗争之后加维诺获得了新生，但他的母亲和姐妹们呢？",
"1978|安娜的旅程": "对战后欧洲集体性疏离和虚无的精准描绘，每个镜头几乎都有准确的设计，颜色对比、光线的强弱、人物的动作，都如教科书一般诠释着电影影像的意义；相比之下大段的台词就容易引人睡眠，但其深度依旧难以望其项背。和发电站TEE专辑形成了某种互文，但在阿克曼这里，疏离的蓝色和机械的声响指向的却是个体最终极的隔阂和意义的不可到达，它可以是历史的，但更多是私人的。15th BJIFF",
"1979|异形": "标杆级的奠基之作，营造恐怖、刻画角色处境和最终决战的方式，至今都受用。借类型片的壳子描绘生育恐惧、公司剥削，足够前卫也足够震撼。与之相对，结尾的成功脱逃，在当代影迷几十年恐怖片观影经历的阈值不断升高的思维之下，却显得过于简单，但放在那个年代，含金量还是很高的。",
"1979|爵士春秋": "热烈而不泛滥，悲伤而不虚无，将一腔热血注入心爱之物，纵使壮志未尽也绝不遗憾，哪怕面对死亡也要纵情一曲，宣告虚无的溃败。",
"1979|现代启示录": "战争片拍到这份上其实也是一座难以逾越的大山了。制作之疯狂、文本之浩瀚，或许后无来者。",
"1979|影迷": "前半段可以看到这台摄影机给男主角带来的喜悦和满足感，能看到电影作为一种客观存在是如何搅动生活这一潭死水的生动过程；基耶铺陈了很多啼笑皆非的情节和动作，影像上也非常灵活，有许多致敬之处。但死水微澜之后，人生要走向何方？在工作与家庭的夹击之下，电影似乎退居末位，但也无力阻挡潮水般的变迁。愤怒摔掉胶片之后，他仍然拿起了摄影机，这刻骨铭心的和解，与扎努西的电影呈现完全不同的选择。",
"1979|爱情狂奔": "说是五部曲其实也是炒冷饭，穿插多部前作片段，试图构建安托万的完整人生，但也仅限于人物之间的情爱而已，其实是原地踏步的。反倒是闪回的特吕弗早期电影与本片形成的对比，让人感觉他已经变得温和无趣、四平八稳，只有浪漫能一以贯之。",
"1979|曼哈顿": "文本上除了伍迪·艾伦标志性的文青掉书袋，还有对群体生活状态描绘的暗线，这是超越小老头自言自语的一点。除此之外可能真的只剩下迷影台词、自我讽刺和男女情爱了。",
"1979|空山灵雨": "如诗画一般自然和谐的背景之下，却颠覆了古代寺庙中的规矩和秩序，投射现代剖析七情六欲之锋利眼光，最后以政治惊悚的动作片呈现出来，节奏错落有致，影像充满巧思，淡雅而有力；尽管故事框架不算复杂，但其中渗透的中式情思妙语、人物细节，也并非随处可见。",
"1979|玛丽娅·布劳恩的婚姻": "令人心碎的女性故事，她的一举一动，都显得时代给她带去的伤害始终无法弥合。一切都在“伯尔尼奇迹”的呐喊中灰飞烟灭了，她的悲剧却再一次臣服于这个国家的狂欢之下。",
"1979|疯劫": "剪辑跳跃而破碎，剧本也较为简陋，而作为许鞍华的第一部电影，仍然展现超越时代的影像力度：不论是对城市景观的黑暗刻画、恐怖元素的点缀和民间风俗元素的描绘，都令人惊叹；而摄影机的运动、变焦很有想法，是致敬也是新变。与同时代香港新浪潮的电影一样，悲剧的核心，永远是那一抹恐怖的“红”。",
"1979|铁皮鼓": "敬佩这种拒绝与历史和解的态度。影像的力度基本来自于原著文本，而导演在情节的选取和改编上无甚出彩之处，加长版更显冗长。",
"1979|复仇在我": "零度影像——犯罪被简化为结果，而人性之阴暗与变态，直接被外化为身体的侵犯、空间的窥视和语言的暴力。几乎没有夸张的渲染，但越到后面就越觉得寒气逼人，而结尾尸骨的悬空，更是让人感到巨大的虚无感，好像一切有意义的事情都在结尾崩塌了。故事似乎将儿时的遭遇视作一切的根源，但若是人人都有如此黑暗可怖面庞，又怎能不将矛头指向长久以来的压抑？",
"1980|第一类型危险": "一黑到底，徐克这部香港新浪潮电影到今天来看依旧极具争议。电影所勾勒的时代风貌无疑是阴暗扭曲的，平民百姓被罪犯袭击，而罪犯又因为几张支票，陷入外部势力的撕扯中。残暴与冷血的底色之下，是对绝对的“恶”的黑暗展示，更是对夹杂于各方势力之间的香港的血腥隐喻。结尾以六七暴动的黑白照片作结，无政府的暴力主义似乎毫无灭绝之意，而其背后压抑的社会现实才是其繁荣兴盛的始作俑者。",
"1982|长夜绵绵": "不同形态的门开了又关，女人被男人拽着走上街头，却独自面对天明——在影像的碎片中得以窥见阿克曼对恋爱关系中女性内心世界的深邃刻画；更为明确可感的，则是在冷峻街灯、人物运动和独属于夜晚的声音之中，来自未来不确定性的呼唤与情感在绵绵长夜中散发的温度。",
"1983|南方": "关于“南方”的赋型：不论是影像上，还是诠释文本内部的动人之处，都有超越个体经验的惊人时刻。敲拐杖一段和结尾演出段落，是能够屏息观看的震撼场面。",
"1983|城南旧事": "台词是写得不错，但在一众的捧读式表演中就显得极其诡异做作、不说人话，配上夸张的面部表情，让人感觉这部电影还没有从文革的样板戏中走出来，尤其是女孩的笑被赋予了过多的成人意味，实在让人不适；对童年往事的回忆之单调、人物刻画之扁平也是时代特征了，为主题而牺牲了很多情节人物上的连贯和逻辑，想表现纯洁无知就是“小孩子不懂”用以营造反差，但实际上大可不必如此。说到底原著怀念的童年是京城富家的童年，这或许可以解释贯穿全片的高干气味。",
"1983|细雪": "开头就营造出独特的古典气息，然而很快就被战争、社会制度和“新人”的举止所打破——刊登战事的报纸，似乎在勾勒时代的欣喜，但真正的裂痕却发生于传统的家族生活与现代化的社会制度之间，电影就从这样的家庭抓马入手，敏锐地捕捉到山雨欲来之际的人心震荡。雪与花、建筑的斑驳与服饰的雕花，市川昆放大了这些日本的文化符号，又让这些元素与情节剧完美地融合在一起。演员表演都相当出色，而几场群戏则更为精彩，妙语连珠热闹非凡，为略显冗长的电影增添了许多看点。27th SIFF",
"1983|提行李箱的人": "展现空间被不断侵蚀、缩小的过程，房间从整洁变为极度混乱，令人不安却又有喜剧的外观，其中声音叙事也做得非常有趣，还点了一下监视器，不过没有深入展开。比较不满的地方就是影片在剧作文本层面上的设计，充满浓浓小资文青味道，疑似被国内电影学院学生学去不少。",
"1984|雪花莲节": "对群像的刻画诙谐而温柔，却也不忘残酷底色和历史政治的伤疤，或许他们吸取了教训，才选择过上这样的生活；又或许他们知道，争斗与欢聚的起起落落，不过只是荒诞世界的一个脚注而已。历史在此处似乎失去光芒，取而代之的是人与自然、人与人的交往，它们构成了真正的历史；而电视画面和军官的形象却依旧提醒着另一种“历史”的侵入——狂欢成为了一种抵抗，摄影机成为了历史的见证者。15th BJIFF",
"1985|乱": "复杂的纷争被简化与颜色与数字的博弈，不知道是否是为了方便西方观众，看到最后却让人感到空虚和平静；影像风格肃穆庄严，但是否是黑泽明最好的作品，似乎也有争论。",
"1985|天涯沦落女": "绝无预设立场的道德评价，而是以公平和客观的姿态审视流浪之旅——最初对于“正常”的期待逐渐被其他角色的言行磨平，最终所有的自由、洒脱和毁灭都融入影像之中，也全然地被观众所吸纳、接受和共情；来自不同面孔的讲述则代表瓦尔达本人的态度，访谈勾勒出被规训的群像，或蔑视或同情，但始终不曾试图说服任何人，也无意批判他们的选择。这样的影像，属实难能可贵。27th SIFF",
"1986|天空之城": "宫崎骏的电影，先于画面的永远是文本。有着极为深刻的文本，但外表又是如此轻盈而感人，能让人忘掉略显单调的讲述。不朽的想象力凝结成的画面，为后来无数的作品提供了灵感，甚至是模仿和致敬。举例：《艾尔登法环》的永恒之城、天空城和圣树。",
"1986|金色80年代": "和《玩乐时间》连看就能勾勒出战后资本主义商品经济在欧洲的发展和式微给人们带来的深刻影响，表面上光鲜的橱窗与几十年前无异，但所处的地下空间已经揭示了时代的变迁；“一切坚固的东西都烟消云散了”，动感舞曲和花样歌舞背后蕴含的却是群体性的失落，而情感关系的混乱便是其戏剧性的外化——结尾终于走出地下室，美国男人又换了一个伴侣，无疑是对现实的讽刺和批判；而对那女孩的劝慰，似乎体现了阿克曼对欧洲未来的悲观态度，同时也是极其精准的预言。",
"1986|家书": "复声朗读层层叠叠，人物交汇又散开，在一个个虚拟的空间中读出那些信件，而真实与虚构之间的界限最令人着迷，却也难抵戏剧式的单调带来的乏味。",
"1986|恐怖分子": "不是每个地方都喜欢，但是必须承认没有哪个地方写得不好、拍得不好的。杨德昌的刀太锋利太冷峻了，从敬而远之到佩服不已，但也许始终不是心头好。",
"1987|倩女幽魂": "美学样式和影像思维有多新潮，文本的价值观和当代意义就有多落后，但话又说回来，如果把这些过时而供人凝视的桥段撇开，那本片当是一部激烈而震撼的奇幻电影，它构成了我们对聊斋式神鬼电影最基本的想象。",
"1987|孩子王": "真正见功力的改编，详略得当却无删减之感，原著小说语言富有特色，改编电影另辟蹊径，用音响、摄影与色彩运用衬托情感，镜头设计很惊艳。比起较为“油滑”的原著，陈凯歌的改编含蓄内敛，虽不能完整道出原著之所有意蕴，但自成一体，力度也足够。",
"1988|红高粱": "不太喜欢对女性角色烈女般的刻画，所谓的野性与自然主义现在看来也颇有猎奇之嫌，与大胆的色彩风格不是一个概念。",
"1989|美国故事：食物、家庭与哲学": "直面美国犹太人的流散状态，以非凝视的视角完成对犹太群体的刻画、生存困境的剖析，与此同时文本的语气又不是绝对的悲悯或批判，而是时而欢乐时而戏谑，但始终不离对“美国梦”的批判与反思——一切几乎都以人物面向摄影机的独白实现，它们与那些寂寥冷漠的美国夜景一道构成了极具启发性的影像空间，正如那场废墟中的宴会，起初让人感到奇怪，但很快就陷入深深的悲伤之中。",
"1990|特写": "对生之意义的叩问，却有着如此朴素动人的影像气质，摄影机是如此专注地对准那些面孔，而结构又如此迷人：一段看似作为开端的情节，此后却用绵延的独白让困境真正具有力度，非虚构的情节演出又将那些语言的碎片深深固定在影像中；阿巴斯的介入则在元电影的层面上与文本产生共振：拍电影究竟意味着什么？导演在这样的社会中承担什么责任？这些问题在阿巴斯与主人公的问答中逐渐明晰，无疑是阿巴斯深刻而伟大的沉思所在。",
"1990|天伦之旅": "剧作结构精巧而对梦境、幻觉的刻画又极其迷人，最终却仅仅做到了呼唤子女尽孝“常回家看看”的主题，以及老登迟来的愧疚和说教，有种亡羊补牢的美感。",
"1991|巴顿·芬克": "科恩兄弟很擅长调动观众的感官，方式不同寻常却又不至于离奇，比如片里的剥墙纸、拍蚊子、掰床架之类的，加上精细的音响效果以及纯熟的导演技法（比如各种视点的变换），想拍得不好看都难。对于这个精神分析爱好者狂喜的剧本，除了个别地方没头没尾（但仔细想好像也能和情节对应），仍是非常优秀的剧作。像这样好的电影到后面已经不是观众在看电影了，而是电影反过来“玩弄“观众。",
"1991|阮玲玉": "虚构与纪实穿插的形式太妙了，不仅让传记片叙事更灵活，还搭建了深入探讨人物心理、影片主题甚至戏外演员的框架，从阮玲玉的悲惨经历出发，我们得以一窥明星制与早期中国电影在历史发展中的影响、左翼电影的具体展现，而这一切又是超越的，在半世纪后的香港电影行业产生共振，具有十足的在地性；影像核心无疑是阮玲玉/张曼玉，“人戏合一”在这里已经不仅仅是一句评价——这是二人演艺生命的共振，她们的表演令人震颤，让人思考伟大的演员对电影、对这个民族和它的历史造成的影响。以一己之力让世人为她迷醉，但却在关键时刻保持微笑而不染一丝污秽，“我是好人吗？”——正直的灵魂莫不如是，而张曼玉肝肠寸断的演绎，让人相信这样的品格得以跨越历史的沟壑延续至今，令人难忘。",
"1991|方块皇后": "女性视角下的赌城日与夜，叙事性被蒙太奇切割激活，有写实的对白与人物，但总体仍然是疏离、怜悯的。十几分钟的赌场镜头精准而迷人，有着钻石一般的通透感。",
"1992|世界上的某个地方": "不喜欢。看的时候甚至能自动脑补角色说中文，这故事实在太“十七年文学”了。当然有现代语境之下乌托邦理想的特殊背景，但仍是一部立场先行的电影。人物是程序化的，资本家是丑恶的，结尾理想的覆灭倒是区别于纯粹的革命作品。尽管角色之间的妙语连珠写得很好，时有真情流露，然而总体还是很陈旧，夸张的配乐贯穿全片，有时情节还未发展，暗示情节走向的音乐就已响起。2023阿根廷影展",
"1993|魔鬼银爪": "道具和设定很炫酷，但是后续跟进的故事就很无聊了，魔鬼银爪这个可移动的便携受难器还是有更多的解读空间，争夺永生然后自毁还是太没趣了，美轮美奂的艺术设计可以弥补一下。15th BJIFF",
"1992|奥兰多": "似乎伍尔夫的小说根本无法改编（读原著的时候就有这感觉），肆意流动的叙述、敏锐的触觉以及独具特色的语言风格，改成电影无论如何都很难保留。莎莉·波特取其要切分为七章节，整体处理还是大气、细腻的，最后一部分“Birth”更是眼前一亮——然而伍尔夫的原著真是一座大山，写得太好了，电影逊色许多。",
"1993|学校": "在传统的剧作和视听中却也迸发出纯真而动人的情感，中国人的部分要是能展开就好了。",
"1993|完美的世界": "味大的白右电影，所有的“救赎”和“铁汉柔情”完全建立在剥削的剧作之上，凯文科斯特纳全程顶着个臭脸，中了枪还要来上一大段，简直够了。",
"1993|亚伯拉罕山谷": "瑰丽的影像与隽永的情感，凝聚在静水流深的讲述之间，没有满足任何观众的窥探欲，而是真切地用时间与空间证明了一切流逝的真实存在。声音不断指引着前进的方向，我们得以在这样的精致中不断流转，直至三个小时后震撼心灵的崩落。",
"1993|亚当斯一家的价值观": "有一种不顾死活也不想深挖故事而放任其野蛮生长的爽感。比起略显屎尿屁的喜剧桥段，段子明显写得更好，基本上是妙语连珠、讽刺不断，故事上的一点小温暖让人物更鲜活了。",
"1993|亚利桑那之梦": "最好的德普和最温柔的库斯图里卡，让这幅美国风情画兼具炽热和疯狂的质感，在不可预知的情节中拥抱生离死别，拥抱激情与颓废，再进入下一个梦中。",
"1993|蓝": "只有蓝色却拍尽满目疮痍，一字一句深沉冷静却具有雷霆万钧之力，尽管目之所及已被蓝色淹没，但只要一息尚存，外面进行着的一切就都与我有关，我要为他和远方的他们，送上饱含深情的一朵小花，期待着光明的到来——或许是最纯粹动人的骄傲所在。",
"1993|情枭的黎明": "撇开这个味大的男性故事，德·帕尔玛几乎是从头到尾完成了一场影像魔术，从那场台球室平地起惊雷所营造的紧张和冲突感开始，影像的坚决毋庸置疑，亦不盲目扩大表达的疆域（斯科塞斯的反面），这种专注赋予角色更多的生存空间，不断延长那些精妙的瞬间。",
"1993|亲爱的日记": "第一段是极佳的城市漫游与喃喃自语的迷人影像，第二段还cue了《火山边缘之恋》，可惜就感觉在不断的自指中丧失了向外延伸的力度，最终沦为舞台剧一般的顾影自怜。其实可以接受莫莱蒂把元影像作为和世界沟通、和自己沟通的方式，但精英主义的视角还是不可避免。",
"1993|咫尺天涯": "文德斯比较莫名其妙的一部，喜欢柏林的部分。",
"1993|来自东方": "在阿克曼的政治电影序列中属于实验性很强的那一类，让摄影机敞开于广袤的时空之下，接受凝视，同时亦传达出人们深邃的面容——无需任何外在言语和搬演的成分，用这种纯粹去暴露虚构难以达到的真实。",
"1993|因父之名": "只有前30分钟维持了非传统的强度。",
"1993|蝴蝶君": "故事本身就很一般吧，很有平行世界的感觉，一开始还好，随着时间空间的细化开始一路崩塌，最后一切都只能缩回单薄的爱情叙事之中。对东方女性形象的再诠释，则依旧难以逃脱西方视角——西方语境下的反思依旧是属于西方的东西，只是比绝对的刻板印象要好上一点点。",
"1993|搬家": "很欧洲电影的观感，后半段缺少前半段那种坚实的现实基础。",
"1993|赤裸裸": "绝望、痛苦和来自人类本能的暴力，弥漫于整个叙事空间中，远离戏剧化的虚构，让那种虚无感更为强烈。只是配乐太抢戏，并且也有点太厌女了。",
"1993|石雨": "中间一度有在看奥尔特曼的感觉，感觉肯洛奇终于没那么紧绷了，后半段还是回到了他传统的剧作结构和影像组织之上，有点鸡肋。",
"1993|银色·性·男女": "前信息时代的余晖，夹杂着对未来世界迷茫而混沌的感知，奥尔特曼借卡佛所作人物肆意挥洒，不像讽刺更像真正意义上的美国风情画，多线叙事眼花缭乱地铺陈交替，却又始终具有极其真实的触感，和以假乱真的可信度。最后的大地震就好像那次袭击，似乎人们找到了一个借口，让糟糕的生活就这样继续下去，仿佛一切从未发生过。",
"1993|吸烟/不吸烟": "雷乃老师教大家两个演员怎么拍出人山人海的感觉。",
"1993|奏鸣曲": "很装腔作势的一部北野武吧，闷骚的温柔也仅局限于男性对女性的“救赎”，以及一系列幻想出来的情感纽带。反奇观的黑帮内斗可能是唯一看点。",
"1993|站直啰，别趴下": "虽然实在受不了台词的腔调，但对当时社会矛盾和转型期心态变化的刻画，堪称入木三分。从流氓向民营企业家美美转型，最后被扫地出门的只有知识分子，何尝不是一种预言呢。故事写得很满，各种情节反转堪比法国室内电影的抓马，影像上也偶有创造性（几个外景有塔蒂似的不真实感），剩下大部分时就是电视电影质感。瞿颖好美，底子很好！",
"1993|纯真年代": "SIFF26：美国人既没历史也没皇帝，在文明发展的初级阶段，以欧洲人为效仿对象，所以满目皆是珠光宝气的俗；但真正触碰到欧洲文明中野蛮、虚伪的那一面时，也会望而却步，欧洲人却说我们已经习惯了。最终随着时代发展，奄奄一息的欧洲文明只等着一场战争来破碎一切，而美国人把那些老祖宗的智慧全部融入自己的现代化中，只剩下纽兰困在“无知年代”的泡沫中。斯科塞斯原来这么多年毫无进步，搁现在可能要拍五个小时，露出释怀笑容。",
"1993|蓝风筝": "结尾确实一浪接着一浪，摧毁了几代人的政治运动，最终在失去童年的小孩身上绽放出最可怕的恶之花，毛骨悚然之余亦觉悲凉。只是，拍得也太差了吧......剧作缺乏生活细节而沦为历史节点的点缀，东一句西一句完全丧失了重构历史真实的可能，视听也很电视剧，在同年的华语片中除了题材的稀缺和重要性，其他都比较老旧了。",
"1993|喜福会": "现在再看无疑是各方面全面过时的一部电影。",
"1993|钢琴课": "剧作上无疑是女性议题的典范之一，在隔绝的泥沼中追逐那一丝仅存的自由和渴望，让人想起呼啸山庄，决绝与坚毅交织的情感纽带越发悲凉，却也在结尾看到美好的可能。影像质素就一般般，同一空间内的叙事极其细腻，但融入更多视角后那种浓烈就被冲淡了。",
"1993|戏梦人生": "几乎是远观这段历史，就像一位孩童从远处看到熙熙攘攘，或是透过门扉捕捉人影的流动，一切似乎静止在时间里，直到画外音的出现，才意识到周围的世界有多么残酷。凝视的瞬间除了非虚构片段就是唱戏表演，那是唯一的来自过去和未来的目光同时交汇的聚集点所在。",
"1993|反叛": "比较无感的一部哈内克，只是较为忠实地用风格化的影像展现了一战后德语文学暗沉而喋喋不休的风貌。",
"1993|青木瓜之味": "惊艳的长片首作，基本全用人物动作与空间组织来构筑影像，剧作退居幕后却始终用声画元素进行持续的表达。如私影像弥散着的潮湿气氛，代表着一种对童年和故土五味杂陈的回望。",
"1993|不一样的天空": "同一年德普还演了库斯图里卡的《亚利桑那之梦》，同样的美国乡村故事和小镇青年，这部就没啥惊喜，但还是会被结尾震撼到。",
"1993|维特根斯坦": "感觉课堂部分被伊格尔顿夺舍了，满满的教科书风味。",
"1993|香魂女": "猜到故事走向后就失去悬念，但颇有一些跳出大陆乡土电影传统的美妙瞬间，在当年来看无疑是合乎世界电影议题和影像发展的电影。",
"1994|幽国车站": "反复使用快速剪辑堆叠悬念，故意掩盖事实，看到一半真的已经令人生厌，配乐甚至加剧了这种焦虑感，而最终仍是以某种反转作为结局，在这部电影里却毫无力度，淹没在角色的喋喋不休中，似乎无力再去关心所谓的深层议题。本片两个主演如今都因为丑闻被抵制，也是一大奇景。",
"1994|子弹横飞百老汇": "黑帮犯罪元素属于伍迪·艾伦玩票式的点缀，核心还是嬉笑怒骂之间的那些创作焦虑、喜悦和转瞬即逝的情愫，以及极具知识分子气味的讽刺，实在是直白、辛辣而精准，正如枪声被当做华彩乐章，或许误打误撞的草台班子才是世间万物的常态，而灵气总是消逝于望不到底的平庸之中。27th SIFF",
"1994|阳光灿烂的日子": "刺眼的阳光让人睁不开眼，既冲击了大脑，也使记忆变得扭曲模糊；具体的日期成为了宏大叙事的注脚，而记忆中的纯真似乎也不是任何一种情感的存在方式，它浓烈、炽热也一触即破，正如空中的那些赞歌，那些血的气息。多年后他试图重拾成长的碎片，却猛然发现记忆已经变成混杂着苦与恶的泥泞。他尚能拷问自己，但当汽车穿梭于车流与高楼，觥筹交错之间，又有多少记忆还能留存？",
"1994|小奥德萨": "布莱顿海滩的那种凛冽、肃杀的气氛，无形中呼应了远在异国他乡的俄罗斯人的矛盾处境，与母国产生了体感的连接，格雷在首作里就将这种愁苦的滋味展现得入木三分。相比之下故事就无甚新意，而有些段落也靠配乐煽得很夸张，恍惚之间不知道在看谁的电影。",
"1995|云上的日子": "Probably one of the most verbose, overrated, crappy master-piece-of-shit 'author' films in world cinema.",
"1995|赌城风云": "在老马的作品序列里边也属于比较平庸的那一派，虽然拍法、故事都是他擅长的东西，但三个小时过去总觉得少了些什么。全程画外音的讲述似乎没把握好分寸，给人一直在等画外音结束的念想。",
"1995|离魂异客": "充满诗意和神性的西部之旅。贾木许拍得太美、太好看了，可以原谅某些地方的不连贯。然而这些碎片又都是影像的一部分，配上销魂的音乐，最后德普饰演的威廉·布莱克躺在船上、凝视天空，所有一切营造的开阔、释然甚至某种“净化”，都一瞬间注入内心。",
"1995|攻壳机动队": "艺术设计近乎完美，影响后来一堆作品；故事却很大、很空洞，而偶尔从冷峻、悲怆之中叩击内心的存在之思才是这种未来故事真正的震撼之处。押井守对动画影像的掌控力是非凡的，他在尽力将后半部分的宏大叙事缩小到人类细微而冷静的哲思之地。",
"1995|冷酷祭典": "后半段纯恶心人，这故事要是拍成美式B级爆血浆恐怖片该多好看，现在是要啥没啥，上不去下不来，卡在这里了。",
"1995|怒火青春": "暴怒中的真实、混乱中的秩序，某种预言。",
"1995|人约巴黎": "有趣但看得很无聊，城市的厚度被消解在对话和运动之中。",
"1995|女人，四十": "one of the best HK cinema",
"1995|玩尽末世纪": "开头字幕“这是一部异性恋电影”，就显示赤裸裸的挑衅意味，将国家的血腥历史与雄性气质爆表的顺直合二为一，非顺性别的两男一女在世纪末的光怪陆离之中做爱、穿梭、躲藏，或青面獠牙或面目扭曲的反派是对影史cult片的致敬，也指向针对少数群体系统性的伤害。除去绚丽的光影设计，格雷格荒木对酷儿影像的开拓还在于解除了某些类型元素与影像风格的捆绑关系，发掘其内在含有的酷儿元素，摄影机位置与景别让人物张力得到最大化的呈现；情与欲的危险与迷人被置于世纪末语境之下，大胆炸裂的结尾无疑是以上所述的集中展现，完全看不够。",
"1995|尤里西斯的凝视": "安哲的影像，绷得太紧啦。在等一个释放的瞬间，结果最后直接把观众勒死了。",
"1995|地下": "“在隐忍和期待中坚强，在戏谑和歌唱中乐观，在乱世中身不由己和忘却道德”，虽然没有*那么*喜欢，但是依旧佩服并感到震撼。库斯图里卡真是奇才，不仅是一位杰出的导演，而且还是民族历史优秀的书写者。他实在是过于优秀以至于难以捉摸，因此偶尔把观众甩到天上去，倒也可以接受。",
"1996|瓶装火箭": "比起昆汀的话痨暴力黑色幽默，其实更喜欢这部。有趣的小细节、人物动作仿佛看到雅克·塔蒂，而整体的风格虽然粗糙，但已经隐约看得出视觉上的追求。情节上很“真实”，和其他夸张暴躁的犯罪片不同的是，韦斯·安德森的影像里总是流淌着温暖的底色、超现实的瞬间和真诚的怀念。当然，他后来是如何进化到《法兰西特派》的视觉小说作家，我就不知道了。",
"1996|末路狂奔": "用极具破坏性和动感的手持镜头取代了凝滞的正反打，佐以几乎自然的光线和声音设计，赋予犯罪故事生猛粗粝的质地，几乎为后续两杆大烟枪等电影树立了绝佳的样板；情节极尽疯狂，却与影像气质高度贴合，出人意料的结尾保证影片文本绝对的批判性。15th BJIFF",
"1997|妖夜慌踪": "监视器无疑是本片最精彩的设计，和躁狂的摇滚乐一起构建了扭曲暴力的精神世界，《内陆帝国》初见端倪；影像处于实与虚的过渡态，而最终还能与剧作浑然一体，自圆其说，体现了林奇操纵内心世界的强大手段。27th SIFF",
"1997|香港制造": "97回归之前的“新人”悲剧，以俗套的爱情故事承载。然而人物关系又处处是隐喻，呼应其悲剧命运的同时也弥漫着躁动不安的情绪，正如男主角脸上燥热的汗珠——旧社会把人变成鬼，那新社会呢？陈果的态度无疑是暧昧不决的，他必须时不时借助男性凝视和对女性的剥削来承载对时代的怀疑，最终这些“后生仔”都面临死亡，但在奄奄一息的“新人”身旁出现的竟是更年轻、更无知懵懂的小孩，而此时广播中传来的，是伟人“不合时宜”的语录，它看似是戏谑的、革命的，但又无比符合那一刻的情绪爆发：对即将到来的红色机器的矛盾心情。",
"1998|小武": "敏锐对准那些被抛下的个体，却又全然没有剥削的眼光。前半部分甚至有些诙谐幽默，但现实袭来，人物不断被抛起落下，因此结尾才如此悲伤和震撼：素昧平生的眼光，此刻竟像一把把尖刀，插进小武的内心，也反射出时代的底色。",
"1997|幽灵公主": "基本上与宫崎骏电影一贯的主题和设定相似，但人物的状态可能是最坚定、最有力量的一次，而之后又把这种决心全部推翻，以反思与批判映射纯真之美；与此同时也可能是宫崎骏在影像层面最恢宏震撼的一次，中国武侠电影中的那种影像张力和情感厚度，都被尽数吸纳其中，令人陶醉。",
"1997|探戈课": "话少的时候还是很好看的，到后面真吵起来了反倒流于俗套了。感觉是用复古的壳子拍了一部很当代的女性经历电影，倒是和片中好莱坞制片人的要求对上了，为什么不搬到纽约呢？因为这样只会带来平庸。",
"1998|罗拉快跑": "过于花哨的视听语言讲了一个过于离谱的故事，唯一的亮点可能是不同配角的闪回，但也并没有进一步展开，这个idea在提克威后续的神棍片中才成功实践。",
"1998|谋杀绿脚趾": "满分剧本，看的时候能感受到剧本写作的魅力，其中的技巧是值得所有写作者学习的。嬉笑怒骂之下是偶尔涌现的战后创伤，“非得什么都带上越战吗”，也许这就是答案。比起《巴顿·芬克》的镜头语言和调度，绿脚趾略逊一筹，属于和自己比有点差但随便吊打别人的程度。",
"1999|罗塞塔": "很明显受到瓦尔达《天涯沦落女》的影响，但更多展现不加修饰的真实，却缺乏对体制的反思。达内对空间和声音的刻画：罗塞塔跑上山丘试图躲避男人的追逐，随后又来到上端的公路旁，摩托引擎的轰鸣由近至远一直萦绕耳边，像是某种即时的、阴魂不散的恐惧和焦虑。",
"2000|花样年华": "喜欢那些敞开的瞬间、多义的文本和浓烈的情绪，但却对王家卫的广告美学颇有微词。",
"2000|记忆碎片": "虽然依旧是你诺土得掉渣的视听和怕观众看不懂的剪辑，但其实很适配这个心理惊悚的剧本，然而也没有任何深挖的打算，虽然还是有几个瞬间能感受到那种“每个人都有每个人不可信的叙事”的迷茫无力感，却也难逃爽文思路，看得很累！",
"2000|苏州河": "《小武》和《苏州河》就差两年，但看上去就是两个世界；同样的，《苏州河》里的城市景观，有时会令人眩晕，那是一种混杂着新旧交替事物的环境。苏州河上，船夫和桥梁似乎停滞在旧时代，但远处的东方明珠又在狠狠嵌入时代的底色。所以他们的爱情到底是什么？也许一个转身，就会消失在彼此的世界里。可惜，娄烨这个剧本实在是太不接地气了，只剩下抽象的人物和略显做作的台词和情节，那什么vodka咱现在都整不到吧，娄公子似乎还是太舒服了。难道，他也是“金句”型导演？",
"2000|拾穗者": "本届上影节最佳，从具体的拾穗到抽象的捡拾记忆、捡拾语言，瓦尔达从一个极小的切口展开，探讨一种独特的生活方式、一种用心体验世界的路径，而她本人的出境又为影片文本添加一层深度，心形土豆、没有指针的时钟、电视和猫咪，在DV的颗粒之下是具体可感的人和物，而最难得的便是从始至终绝对真诚的心灵和看似随意实则清晰的创作路线，因此无疑是非虚构“散文”电影的杰出之作。27th SIFF",
"2003|再见，长夜": "毛骨悚然的“革命理想”，笼罩在上空的红色梦魇。Pink Floyd的两首歌从未如此贴合这种悲怆的情感，每次音乐响起，贝洛基奥的影像爆发出巨大的情感震撼。故事很简单，但安娜在理想与现实之间产生矛盾的时刻，都具有扣人心弦的力量。影片一开始，邻居托她照看婴儿的那场戏就是其中代表，影像的表现力令人震颤。",
"2004|土地与尘埃": "虽是笨拙的创作，却有很多地方催人泪下，真挚情感的伟大力量。",
"2004|再见伊甸园": "每一分钟都如此摄人心弦。最好的电影之一。",
"2004|母亲，爱情的限度": "尺度代替深度的随意之作。",
"2004|面子": "相较同类题材出彩的是勾勒这群华人的群像很到位，所谓的“面子”其实是这一群人在转换文化背景之后不变的习惯残留。",
"2004|不再沉默": "为达成目的而不择手段的低劣创作，人物都扁平而令人生厌，不断反转的同时也完全置此前的塑造于不顾；台词如一潭死水，毫无深刻的可能。或许小K的表演是唯一亮点。",
"2004|摇摆少女": "完美的剧本，溢出的热情，恰到好处的视听语言——最后的演出场面真是全程笑着看完的！",
"2004|美丽家园": "虽然不免是白人视角之下的亚裔故事，但好在没有很虚假的地方，足够真实。女方对美国丈夫的爱以及由此产生的儿子急切找父亲的情节，其实不太能让人信服。这是一种隐性的文化殖民吗？待思考。导演拍的纯行活，没特色就算了配乐口味还烂到爆。",
"2004|水中生活": "既能看到后期WA装置艺术般的影像雏形（所谓风格），同时还有早期作品的活泼俏皮，也因此和其紧绷的近作比起来算是比较好看的。碎片化的散点叙事已初见端倪，但情感的碎片散落其中同样动人，这样的创作方法论在《小行星城》中被不断复现。人物故事和刻画略显老套，诺亚·鲍姆巴赫作为编剧之一，注入了较多家庭片的温和色彩，加上WA的父子主题，最终还是回到美国电影的柔软之中。话虽如此，鲨鱼终于出现的时刻，还是非常打动人。",
"2004|柔道龙虎榜": "起初似乎以动作片套路展开情节，之后却随着空间的营造进入发散的维度，人物依次登场却不依赖任何设定和套路化冲突，全凭动作和神态创造诗意的蒙太奇；不害怕风格的挪用、元素的重叠，反倒是为我所用，创造出独一无二的语气和景观。“打一场”的执念根植于具身性的渴望，回到肉体最原始的感知，与此同时在乱世中保持对某种信条的恪守，抵御黑暗的来临。散落的钱、掉落的鞋、悬挂的气球，他们感知自己与天和地的距离，在后现代的侵蚀中苦苦寻觅浪漫的理想，或许只是一瞬却也内心无憾。",
"2004|威士忌": "过分平淡的结果就是啥也记不住。",
"2005|浮城记": "“铁岛”上的乌托邦实验，船长形象的变化直白反映了阶级的产生与社会矛盾的根源。前半段有写实主义之风，但情节之间衔接较为突兀，重点也不够凸显；后半段转向伊朗式的道德困境，年轻人被船长反复溺于水中的段落，最令人揪心，也最具有现实批判力。最后登上陆地的长久空镜，无疑传达了阿巴斯式的平静与虚无。",
"2005|最好的时光": "据说是侯孝贤对此前作品的一次回顾，第三段略显迷乱，但恋爱梦的悸动和欢喜、自由梦的中式美学和饱含深意的文本，都让人领略这位大师的魅力，哪怕只是冰山一角。",
"2006|内陆帝国": "对人类精神世界迄今为止最震撼的银幕描绘。15th BJIFF",
"2006|穿越时空的少女": "很难想象这是一部来自2006年的长片首作，细田守确实爆发出了惊人的才能，对时间/空间的把握尤为出色，剧本本身已经有相当跳跃的设定，而在影像上也能更进一步。设定上似乎指向反乌托邦式的时间旅行，但出发点和最终落点又是极其私人化、生活化的，前半段校园喜剧元素与主线故事相得益彰，后半段则用一个个细节持续叩击生活的“真相”所在，似高高举起，最后却轻盈落下。",
"2008|二十四城记": "或许是科长形式与内容最融洽的一次创作，也是最不被理解的一次。“讲述”从来就不是客观的，如果说素人出镜提供的是真实，那么专业演员的”非专业“表演不仅在虚构层面扩宽了表达的维度，更代表着一种书写的自由、声音的自由，连同诗歌、歌曲和老电影一起构成了丰富的叙事空间，这些元素在贾樟柯其他电影中或许用得违和，但这一次在低清的纪实影像之下，一切都如此真实，让人相信它们真的存在；访谈之外的影像编排保持着贾樟柯电影的一贯风格，它们被赋予具体的时间和空间坐标，却并非简单的重现，工厂运转的slow cinema、人物在具体空间之内的美学设计、车载镜头拍下的街景、国际歌的蒙太奇，这不仅体现着贾樟柯电影谱系中思辨性达到前所未有的高峰，又将视角从420厂、24城之中解放出来，最终是献给成都这座城市以及所有为之所困的人，“仅你消逝的一面，已足以让我荣耀一生”，所有的真实与虚构，在历史的裂痕中清晰可见，而贾樟柯在此之上又生长出独属于他的影像——一种融合的、在场的真实。所以再回顾《风流一代》，或许是时过境迁，割裂与虚浮都处处可见。",
"2008|利物浦": "孤独、寂寥。大陆尽头的冰天雪地，来去无声的空虚灵魂。富有诗意而较为沉闷。",
"2008|步履不停": "应该是对东亚家庭关系最真实的剖析，借一次家庭聚会就拍出了家庭成员互相猜疑、欺骗甚至心怀鬼胎却仍然和和气气的样子，然而生活还要继续“still walking”，虽然他们说“和解总是迟来一步”，但残酷的真相更可能是容忍一辈子，亲情用谎言和逢场作戏来维系，一如那艘搁浅的船。所以那些舒缓的配乐、温馨的空镜，更像一种达不到的期望，或是是枝裕和语带深情的教诲，却也点到为止，哀而不伤。",
"2009|45365": "《汽油彩虹》导演二人组的长片首作，用电台和体育活动来串联这座邮编为45365的美国小镇众生相，在日常的对话和冲突中勾勒小镇迷人而疏离的现代面貌。非虚构影像的剪辑，使得部分段落有了剧情片之感，甚至在美式橄榄球的部分，还有了人物弧光，而对影像气质的拿捏又在青涩中透出一丝胸有成竹，在不同景别的切换中展现了创作的真正态度，而深邃的配乐无疑强化了这种表达，对这座美国城镇的观察与思考，都徐徐展开，回味无穷。",
"2010|潜水艇": "气质独特，影像气质是迷人的，但又有精心营造的疏离。尽管故事不算完美，但清晰可感的创作自觉让无数个影像瞬间有超常的力量，Alex Turner的歌曲更是锦上添花。",
"2011|小亚细亚往事": "标题很大，故事看上去却很小，然而内核又是无比巨大的。繁复的文本之下，寓于日常的时间、空间之中的悲剧性，与这片土地的历史和人相交织。所以这绝非情节可展现之物，略显沉闷的留白也就有了合理性。更何况那也不纯然是留白，水果顺流而下、塑料袋随风飘散，这种凝视恰恰就是文本无法展现，而需要影像呈现的要素。特写/全景运用得行云流水，外加几次推拉镜头所创造的cinema moment，以及精巧的声画关系，大师当之无愧。",
"2012|大都会|大卫·柯南伯格": "<b>Meaningless adaptation</b>: the dialogue is copied, and at best, it just figurativeizes those descriptions. However, film and television adaptation should expand the width of the text, instead of making it have only one style, especially this stream of consciousness novel, so it is better not to adapt it. The original work is quite impressive, but it is clumsy and funny at a glance. The praiseworthy part may be the soundtrack. Sincerely suggest that you read the original work directly. Brain supplements are better than this. (Machine translation from my Chinese review)",
"2012|舍间声响": "是那种真正拍出了时间/空间痕迹的电影，门多萨对周遭事物和社会问题的深刻体察几乎是决定性的，声音牵引出一系列主题，但又无需强情节驱动，反倒是出人意料的人物行踪与事件营造出复杂的观感。虽然确实有一些段落体现影评人做导演的匠气和刻意，但摄影机全程都是贴切的，在动静之间精确触及了预想中的真实。",
"2012|禁忌": "一部民俗的、历史的、以环境拓扑学为向度的爱情电影。影像介质与心灵活动的融合，难以匹敌。第一部分关于寻找和记忆，沉静深邃的语气让人留恋许久；第二部分则全由画外音驱动，记忆中的对话已经不清晰，但环境、人物、书信和音乐却能留存——这种遗忘是私人的，当然也是历史的，属于这片殖民地的共同记忆。期待《壮游》。",
"2013|索尔菲雷诺之战": "最后那场吵架戏简直就是《坠楼》吵架戏的初版，但处于风暴中心的女性，在这部首作中显得更加孤立无援，而男性角色冠冕堂皇，却始终走不出自己的一亩三分地，最后勉强抱团取暖，自我安慰。选举活动人潮汹涌，个个摩拳擦掌，但聚焦于个体的情感，又显得如此脆弱，因而情感的爆发与止息才会如暴风骤雨一般，平息之后是无奈的幽默给予一丝温存。",
"2013|博格曼": "尽管有凛冽的角色塑造与影像氛围，但看过《寄生虫》再看这部电影就索然无味了。情节之跳跃令人惊诧，甚至毫无停下来看看人物的想法。哈内克的人性实验根植于人内心的恶，奉俊昊的上流寓言指向社会的不公，哪怕是兰斯莫斯的《狗牙》，也有反父权制和极权的指涉，而这部电影的议题实在太过含混和疏离，很难看下去。",
"2013|男孩与世界": "对传统叙事的背离，转而采用大量具有象征和隐喻意义的符号来勾勒男孩眼中的世界，近乎二维的笔触之间是一个如万花筒般绚丽的世界；此后那些形象却越来越具体，真实的人类器官开始出现，世界变得越来越残酷可感，最终现实世界的影像也插入其中，巨大震撼的同时似乎主人公的位置也越来越模糊，直到最后他终于回到温暖的怀抱里。",
"2013|孩童姿势": "对“有幸者对不幸者的愧怍”背后隐藏的道德优越进行了揭露，最后镜头的运动很有想法，但总体过于平淡了。",
"2013|和谐课程": "装腔作势、故意隐藏的镜头实在太多，整体也没有形成从始至终的情感扩散路径，而是让观众猜谜。最讨厌的就是猜谜电影。镜头设计略有深度，但也不统一。",
"2013|爸妈不在家": "首部长片就有如此表现，可谓惊叹。好几处，光是通过摄影机的移动和人物的动作就表达出超越文本的东西。破碎的家庭、失序的时代以及残存的亲情透过以小见大的平静书写，既锋利又不失敏感的触角。影像的质感令人感到压抑、窒息，是深层文本在更宽广层面上给人的感性体验。",
"2013|英宫恨": "赋予历史故事现代的微光，用精妙的手持摄影和细致的人物刻画，勾勒出女性主体的羽化过程。爱情在其中有微妙和暧昧的内涵，而导演始终保留着女性主体面对这一切时的相对独立和抽离。这种独立最终演变为脆弱，终于在裹挟中崩塌。",
"2013|流浪诗行": "较为扁平的黑白影像，观感与n年后的《绿色边境》无异。",
"2013|寂静人生": "《伦敦生之欲》的煽情已让人有不适之感，而此片却更严重。除去甜腻的音乐，精心设计却虚浮的镜头语言和布景都很难让人信服，女性角色又再次成了工具，结局也以最戏剧性也最搞笑的方式收束整个故事。但就文本本身，在成日面对死亡的工作之外，生活中那些定格的瞬间，才是哀中之哀的展现。虽然难以与考里斯马基一较高下，但主人公孤身一人面对孤独和死亡的场景，依旧是触动的（然而贯穿全片的朦胧滤镜又偶尔破坏了这种氛围）。",
"2013|我的死亡纪事": "用极端自然的影像风格不露声色地展现了理性的流逝、浪潮的来临。",
"2013|金笼": "毫无反映与抬升的现实主义，外加影像上的单薄，便是这类走线题材的普遍样貌；主人公命运突转的到来并没有体现力度，与达内兄弟比照，才能发现后者在人物设定、社会议题与情感铺陈方面的独到之处。",
"2013|水印街": "绝对的老中惊悚片，庞大的体制怪兽将人卷入其中，撕裂情感，暴露人性中最黑暗的角落，几个地方的处理真是毛骨悚然，也似乎看到了“抓软肋”的恐怖场景。男主角最后重获自由，但招待所的门牌号又在提醒你：它们无处不在。来自路人的异样眼光，继承《小武》的批判视角，却又注入完全不同的当代内涵。对白的生涩和表演的稚嫩，是新导演很难避免也无伤大雅的小瑕疵。",
"2013|皮囊之下": "绝对的神作，套入任何类型片的框架都很难评价它，因为这部电影已经飞得太远了。看不到剧本、蒙太奇“无解”、甚至连所谓风格都飘忽不定……当一部电影不靠这些东西都如此出神入化，难道不正是cinema的魅力所在？乔纳森·格雷泽几乎是找准了每一个摄影机应该对准的点，配合苏格兰独特之氛围及诡异的音乐，每一场戏都有独一无二的影像气质，与此同时几乎不依赖任何风格化的尝试。所以这是一幅极尽细节的绘画作品，我们应该整体观望之——此时一定会感叹这一切都如此自然和完美。这个时候，电影“讲了什么”，还重要吗？",
"2013|午夜狂欢": "黑夜的静谧、肃杀、欲望涌动和望不到头的孤独，都在身体的接触中被高度提纯。",
"2014|未来海岸": "为爱情远走他乡，却找不到自己的位置。语言淡忘、水土消逝，幸而心底还留有一丝温存。两人的化学反应激发了动人的情感，细腻而不失冷静的表达挖掘出人物的深度。结尾三人骑着摩托隐入雾霭美丽至极，然而有时配乐也喧宾夺主。导演对于那些性感和色情的情节、事物的拿捏恰到好处，体现于两位主演的身体接触之中。",
"2014|一步之遥": "对于不同的故事，打开方式肯定也是不一样的，所以如果能接受《让子弹飞》的爽快，应该也能接受《一步之遥》的荒诞，不然就是双标。作为导演，姜文是很有才华的，节奏的把控、大场面的处理，就连枯燥感都是设计过的。而文本就比较弱，所谓的隐喻先不谈，这个剧本显然是不合格的，实在太奔放了。",
"2014|庆州": "是洪常秀的反面，方方面面都是设计好的，哪怕是看似自然的情感流露，也离不开背后的政治、文化差异，就连人物的身份，都是明晃晃的隐喻。张律的“作者性”很多时候讲的是他所写作出的文本，举重若轻而意味深长。有出色的剧本在，导演方面的闪光就是自然而然的事了。",
"2014|黄金时代": "想写好剧本太难，如此宏大的时代故事，最终呈现的是一个切面，而反常规的手法也只是在放大这一个切面的细节。前一个小时人物悉数登场，不了解文学史的话会让人很难进入故事，后两个小时的精彩也就无从领略。最后给萧红做出悼词式的评价是最大败笔，把整个故事限制在了那个时代，而失去了观众在当下欣赏之后迸发的力度。",
"2014|只在那里发光": "起初看到很多导演的影子，金基德、贾樟柯甚至是今村昌平；但最终意识到这种作者风格是全新的，它能直面黑暗却也不留恋光明的转瞬即逝，拍出洒脱，而更聚焦于收起这份洒脱之后的迷茫和孤独。也因此影片的风格时而宁静时而跳跃，但总是戛然而止，拒绝沉溺于暴力、欢愉、放纵之中，这样的影像气质和剧作的主题是高度相符的，因而导演对于文本的把握既精准又克制，令人难忘。",
"2014|那夜凌晨，我坐上了旺角开往大埔的红VAN": "可能是10年代最重要的香港电影之一，对港人心态的刻画、对香港未来寓言式的拷问，都在之后的事件中不断重演、应验。视听语言粗糙而狂野，同时能看到很雷人和很神奇的影像，就在这种大乱炖的气质中，也得以窥见末世下众生相围绕新香港产生的情感纽带。",
"2014|重赛的重读": "电影院放球赛还能入选柏林，影史估计前无古人；全片影像完全由足球比赛录像组成，配上导演和父亲交谈的“环境音”；而导演之父就是这场比赛的裁判，这场布加勒斯特“德比”发生于革命前夕，山雨欲来之际，球场上剑拔弩张的背后是政治势力的暗中争斗。然而二人的对谈很快失去焦点，导演试图揭露了足球比赛的矛盾之处：尽管比赛的结果被看重，但90分钟的比赛却很少有人能做到全神贯注，其中无意义的乏味之处只有观众“被迫”以电影形式全程观看的时候才能被发觉。",
"2015|山河故人": "可能是科长最细腻、对情感关注最多的一次，孤独感几乎贯穿全片，而其背后的隐喻恰恰不是山河故人而是“山河”巨变，无疑是一种超越国家和意识形态的未来疏离感——但矛盾的是科长又注入了太多奇观、符号和隐喻，有时候却过于直接，削弱了疏离和寂寞的连贯性，让人遗憾。",
"2015|橘色": "夺金棕榈之前看的，最朴素的器材却拍出了最真实的情感。多线交汇的撕逼戏份很吸睛，但喧嚣之后的平静，才是肖恩·贝克最厉害的地方，一如那场酒吧演出，深邃而难忘。",
"2015|从此以后": "过于单调无趣的现实展示，冷峻的摄影需要更深刻的文本注入。",
"2016|寒战2": "连着两部看完也是感官过载，感觉一直被推着走，第一部好歹还在表面上讲一讲他们为什么要争斗，第二部直接快进到任务驱动型叙事了，其实大家想看的明明就是背后的价值观和历史政治冲突吧，拍两拨人混战其实是有意掩盖了本可以大书特书的部分。",
"2016|含羞草": "《接近终点》的前奏，宗教意味浓厚而情节约等于无，但是影像表现力已经很惊人了。",
"2016|日常对话": "导演说，可能放眼望去找不到几个和她一样的家庭。这场对话是和解，更是发现，发现那些美好的事物，发现那些无奈背后的苦难和勇气——导演用她的真诚和博爱打动了所有人，而对话也从小屋子中飞出，朝着广阔的蓝天绽放，润泽所有追求平等、自由和爱的人。",
"2016|人类之巅": "青年的焦虑与躁动，用这种粗放而自然的影像展现，别有一番风味。全球化视角之下的不同国度的他们，都在自己的世界里登上了人类之巅：呼吸大自然的真味，拥抱自己和他人的身体，最后在虚无中放逐自己的灵魂。",
"2016|罗曼蒂克消亡史": "言有尽而意无穷，电影之所以为电影就是要把那讲不尽的意拍出来。无论是故事的完整、人物的圆满还是文本与影像之间的关系，这部电影都做得不错，但问题就在于电影不是书籍，观众不能停下来往前翻，在较为碎片化的叙事里就很难把握住前后呼应带来的震撼。视觉上是很考究的，但绝不“美”，精致的场景设计是为这个略显讽刺和荒诞的故事而准备的。战争与罗曼蒂克是一对反义词，浪漫在这里成为了欺骗、荒淫的象征，它的消亡不仅意味旧时代的结束，而更是“新时代”的降临。所以调度上慢悠悠的航拍视角、慢镜头，它们传达的是悲悯、唏嘘和讽刺。说到这里就必须提一句：程耳导演对大场面的调度或许还有进步的空间，至少这部电影呈现的是半死不活的影像状态。表现力不能仅来源于静态的设计之中。",
"2016|三人行": "拍的是警匪对决，但内核和《拆弹专家》一样言他物也，赵薇的特殊身份设定（大陆人赴港学医）、三个病人折射出香港人的三个角度、警与匪医与患的交织，这一切在短短92分钟里展开，丝毫不显拥挤。细节的描绘不必提，最后一幕的慢镜无疑是现实的折射，是未来的预演。",
"2017|待屠之颈": "形式感太强，谜语人太多；感叹拍得好的同时，又痛恨这稀烂虚浮的文本。",
"2017|童女贞德": "能get到《周六夜现场》的话应该也能get到这部杜蒙，反正没人能还原历史现场，索性往间离效果的最大化猛冲，刻意保持距离。这其实是一种最符合直觉的表达方式，尽管呈现出来的效果是反直觉的。哪怕有些地方令人摸不着头脑（比如不断强调的沙地、甩头），但总体依旧是非常有趣且有意义的的尝试。",
"2017|独自在夜晚的海边": "在貌似平淡的尬聊中迸发出惊人的情感震荡，某种不安全感始终盘旋，到最后也没法解决。反复被洪常秀写作的能力震惊，那些瞬间可以是一种群体的症候，但更多则是极其细腻私人的情感；对白从不是日常的堆砌，却比任何时候都贴近真实。虽然后期洪片影像质素全掉线的特点已经初现端倪，但在单一镜头之内的设计太令人痴迷，真的能把所有人物以一种最恰当的方式装在一起。",
"2017|方形": "This sarcasm does not seem to be very advanced. It is commendable to portray these people in modern society who are superficially calm and collapse at any time. I don't know how Ruben Östlund degenerated into the shit and piss of Triangle of Sadness. The Square seems to be a very flattering work from 2023. (Machine translation from my Chinese review)",
"2017|芳华": "网左对此片的招魂属实令人发笑，但那种一夜间改朝换代的巨大落差感以及附属的时代创伤也是暧昧的，或许是因为被装入俗套的爱情故事中，以至于真正的丑恶与黑暗只在几个瞬间显现出来；整体依旧是情节驱动，巧合和反转太多，前半小时对文工团生活的“搭建”还算是不错的，但或许去描绘疯狂岁月之内的日常生活，也是一种反动。",
"2018|梦的背后": "如何在一个极其困难复杂的环境下坚持自己的专业理想和艺术追求，看着真是额头冒汗，佩服这样的导演（在中国拍电影，似乎更像是没日没夜的产品经理）。作为幕后纪录片，能触及的其实不多，全片也略显流水账，脱离了原电影本身之后自我表达的生命力是有限的。",
"2018|你的鸟儿会唱歌": "我看到的是一群“爱无能”的年轻人在这个压抑、冷漠的世界里相遇、温暖然后分离的故事。举重若轻的影像，同样的场景，末尾第二次出现时却感物是人非之怆然，赞叹三宅唱导演处理故事的高超手法。最喜欢的是那场超市里三人穿行于货架之间的戏，流动的情感与影像一气呵成，如此自然、真实而动人。",
"2020|福冈": "很多地方都挺妙的，某种情感、某个瞬间，甚至诗歌流淌背后的情绪，大多都拿捏了。但并没有一个很舒适的文本，有些东西写得太实，而实的地方有时又太虚，要是只有文字或许可以接受，融入影像之后就有点难以进入。",
"2019|火腿黑面包": "是那种平地起惊雷的电影，温顺的白天和诡谲的黑夜，陶尔米纳捕捉到超现实要素，却又始终不离开人物三分。对环境的细致刻画跳脱出情节的窠臼，以一种更隐晦、更温柔、更优美的方式完成了文本的表达。最后烟花绽放，她从神游中醒来，眼前的一切似乎变得陌生，但却能清晰感知到转变的来临。",
"2019|贞德": "讽刺与凝视的那套对应关系在杜蒙的话语体系里是有效的，但故事的叙述方式非常无趣，情感的爆发全来自于贞德的故事本身，而不是影像的努力。不可否认有一些眼前一亮的地方，但我还是更喜欢极具创意的《童女贞德》。",
"2019|西比勒": "The flow of feelings",
"2019|国家葬礼": "素材本身就足够精彩了，郭沫若老先生突然出现在屏幕上，还是有点恍惚；更难得的是洛兹尼察足够强劲的表意脉络，用剪辑重现国葬的另一面，始终强调时间与空间的串联，西至立陶宛东至海参崴，宏大的仪式在同一时刻将所有正常生活纳入运转的轨道，压抑得令人窒息，结尾两行红字更是不寒而栗。摄影机不断聚焦于普通人的面庞，他们瞥见摄影机的那一刹那，是否有一丝抽离的可能？以及，葬礼本身的庄严肃穆依旧来自民族历史和传统，而这在东大类似的场合，却已经完全被程序和表演所取代，真正的悼念与哀鸣，是否只存在于某些“特殊”的场合？历史会给出答案。",
"2019|停止": "拉夫·迪亚兹仿佛开了天眼，2019年就准确拍出接下来三年的常态：病毒、极权以及个体的挣扎。也因此这部电影可以被编入后疫情时代作品序列之中，位置却是独一无二的：所有一切都像永不照亮的天空、一直下着的雨，事件发生又结束，人物出现又离开，人的异化——机器人一般永不停息的压抑生活，被操控的极端世界。迪亚兹的电影早已“臭名昭著”，但这部倒还行，比想象中的好看多了。",
"2019|罗小黑战记": "没有屎尿屁笑话就很难得了",
"2020|七人乐队": "遍地黄金＞别夜＞深度对话＞校长＞回归＞迷路＞练功，虽然有几部免不了命题作文“正”的倾向，但至少没有一部在抒发空气，这一点上比《我和我的祖国》好很多，更别提文本自身的复杂性，放在香港的文化语境下很自然就有了深度。一百多分钟的观影体验是舒适的，但又不缺回味，这就是七人乐队演奏的独一无二的香港乐章。",
"2020|汗流浃背": "表达太浅，人物也过于扁平，第一场戏的人物弧光基本上就是全部。手持摄影和人物状态的结合还算有效，因此不算是一部难看的电影。",
"2021|杨之后": "有动人的故事、深邃的文本，却因为过度雕琢形式而沉闷无比。据说致敬小津，然而那些刻意拖慢的调度、无聊的重复、乏味的美学设计，都给人故弄玄虚之感。故事中的陌生、疏离和文本的深刻、隽永，这些优点都没有体现在乏味的影像里。",
"2021|阿赫德的膝盖": "后半段收拢之后非常精彩，表达的深度和影像的密度兼具。独特的摄像机运动倒不觉得出彩，似乎沦为漫无目的的宣泄。",
"2021|另一个世界": "“今日全球化，明日自己过”，五条人一句歌词的情感深度都比这部电影强。结局看似happy ending，其实是有意为之，脱离常规的设计就是异化、孤独的表达，和睦幸福只是表面，从此只能活在“另一个世界”。",
"2021|亚瑟·兰博": "这些仇恨言论潜移默化影响街区的少年，在最后的争吵之中昭然若揭。然而这本应该是立意的起点，却成了影片的最高潮，未免有些泄气。",
"2021|登楼叹": "Exploitative as fuck",
"2021|辣妹刺客": "人家拍的商业动作喜剧片怎么就这么好看呢。基本没有硬伤，武戏足够，笑点不低级，人物设计也有趣，甚至剧情还经得起深挖。我建议开心麻花那帮人可以好好学一下。",
"2021|野蛮人入侵": "以一种天马行空、肆意妄为的姿态完成了看似平淡的创作，我觉得这才是最可贵的。武术作为身体的外延与人物的行为并置，而又指向深层次的命题，最终呈现为武侠电影的独特变奏，很有意思。然而迷影梗、科幻梗、元电影，又让电影本身变得不那么纯粹，影像本具有的流动性会在这些地方戛然而止，这也能解释为什么电影本身虽然好看，但偶有不畅之感。",
"2021|布莱顿4号": "这故事是很有意思的：不同文化的“外乡人”因为某种原因聚集在一起，却又处处隔阂。身份认同的问题被巧妙地包装在拳击手的身份和经历之下，而在公寓楼之内的叙事又能由小及大，进而推到更广泛的内涵。喜欢这部电影也许是因为它讲了一个在我们身边也存在的故事。",
"2021|沃尔科诺戈夫上尉逃亡记": "对于离经叛道者而言，最痛苦落寞的时刻不是失败，而是救赎的道路被完全堵死，可谓求死不得，只能堕入地狱；而这也是当权者最狠毒、决绝的招数。所以片中小朋友才问：西班牙法西斯都没让他招，你们能让他招了，你们比法西斯还厉害吗？也许蔓延全片的红色就是答案。",
"2021|角色": "最后菅田将晖举起刀露出微笑的时候确实出人意料，从这个角度挖掘人物内心一定很有意思，可惜全片完全不想做这件事情。编剧稀烂、配乐不搭、剪辑混乱，挺无聊的。",
"2021|奶牛": "从动物身上取得人类生活的共情可以理解，但认为这完全是一部以奶牛为主角的剧情片倒也不必——这还是在把它当人看。然而整个牧场的环境，奶牛、音乐、人类员工，这些元素一起构建的是一个现代性视角之下的权力体系，而未露面的人类到底处于怎样的位置之上？说它是动物视角的肯·洛奇，或许又略显言过其实。但可以肯定的是，安德莉亚·阿诺德对影像的掌控力极强，看似松动的手持摄影实际上牢牢掌握主导权，最后那一枪也因此迸发强大的力量。",
"2021|欺骗": "开头很惊艳，这股劲儿也一直延续到片尾，跳跃中流动的情感拍得很迷人。虽无法共情男主的故事，但能行云流水拍成这样也很佩服。英美之间的故事背景被弱化，以至于有时get不到营造男主角形象的点。",
"2021|食至灭绝": "论影像，基本就是科普短片+摆拍缝在一起；论观点，作为一部说服观众吃素的电影，看完只会让人更讨厌这群只会喊别人吃素的伪君子。啰啰嗦嗦一大段，却对素食潜在的影响、肉食替代物的局限性和发展避而不谈，而还是那一大堆话，配合偶尔闪现的人吃肉的摆拍镜头，似乎在说这一切都是罪过。说实话，这种propaganda只会让人更厌恶——片中“采访”了一个12年素食主义者，吃了一块鱼肉就汞中毒“快死了”......看表演得如此夸张，真是令人感到不适。",
"2021|音魂掠影": "莫里康内对电影音乐的独特理解成为了这部传统人物纪录片的亮点，可惜没有深入。即便如此也是流畅而好看的，哪怕只是平静地讲述自己的经历，配上他的音乐都显得澎湃动人，这不就是他的音乐所具有的强大力量吗？",
"2021|法比安": "前半部分恍惚穿越至《柏林，亚历山大广场》的柏林，一样的躁动不安，但《法比安》的主角是无所适从的年轻人。那种绝望感式贯穿始终的，因为在那个时候，时代的话事人都是一群老掉牙的人，然而中年人已经丢了魂魄，新生代空有理想却不似卡尔·李卜克内西那样有所作为，于是就难以避免逃脱迷失在纳粹扬起的旗帜下的命运。所以从这个意义上来讲，法比安最后纵身入水，反倒是完成了灵魂的解放，因为他从未如此义无反顾过。",
"2021|卡塔叶时光": "美丽的影像就像是真的把我们带到了那个烟雾缭绕的世界一样。虚构与真实的界限显得越来越模糊，这时一条明确的路径就显得尤为重要，此时纯粹的影像就会承载国家、历史以及青年的躁动。可惜这部影片并没有做到这一点。",
"2021|羽毛": "过分追求故事的寓言化，而丢掉了能把影像和观众连接起来的最重要的东西——情感，因此精心设计的各种元素无论怎么分析都只能引向一种现实，而不是真正的内心，书写出的阿拉伯女性生存困境最后也只是沦为影评里一遍又一遍味同嚼蜡的文本分析，累。虽然有很多不成熟的处理，使电影变得晦涩，但美学上的追求值得肯定，如果加上处女作的buff则更让人敬佩半分。",
"2021|法兰西": "真·华服之下爬满虱子，复杂的人物形象反映的是疯狂社会投射到个体身上的阴影，但她却又正好叫法兰西，所以她有异于常人的平静，只因她出淤泥而全染，却穿上丝绸，遮盖内心的污渍。社会议题、情节与人物错杂又互相影响，哪怕最后法兰西女士突然失去丈夫和女儿也不令人惊讶，这不是说她有多令人讨厌，她已经成为了最能代表“法兰西”的一个入口，当试图从良的主持人回归老本行，那华服的一角已经被掀开了，这是预言式的悲剧。",
"2021|怪人出街": "也就比纯超英电影好一点点，欧洲语境下的文化底蕴拯救了这部平庸之作。初看觉得很有意思，但一路泄气，避开要害，食之无味，弃之可惜。",
"2021|未来": "像一首澎湃而悲怆的散文诗。采访对象年龄和我差不多大，因此也就有非常强烈的共情，进而为所有这样的人感到悲伤。年轻人的焦虑、憧憬和迷茫老生常谈，但三位导演将其融入精致的视听语言中，让普通的采访有了历史的厚重感。 最令我感到悲伤的不是那些意大利的青年都陷入了迷茫和怀疑之中，而是比起他们，我们根本没有迷茫的权力。我们质疑的东西显得如此幼稚，而深层的猜疑却消散在人群中，我们也许在事情无法挽回的时候才能真正醒悟。本想着这样的调查在中国展开会更有力量，细想之后或许没人能给出有价值的回答。然而这并不是中国青年该承担的责任，但莫须有的指责却全来到了他们肩上。",
"2021|软禁": "现在看当然是意味深长了，男主角的母亲离世，他却因软禁不能参加她的葬礼；与盯着他的“大白”交谈，关于良心的拷问无疑振聋发聩。全片中这样的金句比比皆是，可惜在这片土地上连讨论的空间都没有，只有能和明白。结尾处，男主角获得不是因为他被证明了清白，而是惩罚他的市长被更上层的铁拳惩罚了——戏谑讽刺之余，无疑揭露了悲剧性的事实：我们都是困在庞大机器里的人，大家都一样逃不掉。",
"2021|洞": "洞与老人，或许有关联或许毫无关系，但就在那样的凝视关系里人与自然达到了一种静谧的、一体的境界。勘探队或许在破坏这一切，但放置于特定的历史语境中，两条故事线神奇地合二为一，那是跳跃的生命与自然的奇妙共振。观看过程中一直联想到《树王》。",
"2021|空白": "老给人物背上自我感动的道德负担干什么呢。故事还是挺好的，只不过越讲越拧巴，基本处于原地踏步，导致结局绵软无力。感觉这些都是像我这种菜鸟作者会犯的错误。",
"2021|犬王": "前半个小时昏昏欲睡，后一个小时完全被点燃了，歌舞本身的表现力和故事前后的勾连都在汤浅的影像里变得极为惊艳，令人难忘。冷静下来之后发现故事有诸多不足，然而似乎这样的不足在最后一个小时的狂野中也显得无足轻重了。挺喜欢的！",
"2021|宇宙探索编辑部": "作为走近科学的忠实观众，看到这种喜剧其实并没有多惊奇。独属于生活的荒诞与浪漫的一面拍得很好，然而后半段转为类型化的单一模式，反显得无聊。故事写得很有灵性，各种细节、对话也下了功夫，但最重要的人物之间的关系及情感，有所欠缺。伪纪录片形式，镜头成了角色自白的窗口，然而后半段突然消失，因此更像是找不到描绘人物的出路而选择的方式，用后即弃。刻意追求破碎的剪辑效果，然而节奏把握得很差，人物行动被剪得破碎，个人不太喜欢。手持摄影营造的自然、荒诞的感觉值得称赞，但就像人人能拍的vlog一样，真正击中内心的不是那些笑料，而是在某个瞬间，镜头停下来，聚焦于那些真实、巨大的情感迸发。这在电影里其实很少。",
"2021|稍微想起一些": "不断地从细微之处的巧思获得惊喜，然后被涌动的情感一直牵引",
"2021|智齿": "从未见过的香港，贯彻到底的痛苦，失语的“垃圾”与喜好砍手的恶魔，这是一个巨大的隐喻。女性角色在片中几乎被蹂躏，但却又不断决定男人们的命运，这种关系的指涉不言自明。拔不掉的智齿恰如无法除去的梦魇，笼罩在黑白交替的香港上空。",
"2021|少女索朗日": "刚看《洋子的困惑》就看这部，虽不能放在一起对比但有很多互通的地方。单说这部，喜欢它的态度——既然错误都是大人给的，又何必在他们身上流连？于是摄影机间或在情节剧与外部塑造之间流动，直至最后的“宣言”。影像的“位置”先于风格，是最好的地方，而音乐就有点过载。饰演索朗日的演员虽然很棒，但总让我感觉年龄太大，不符合12岁的设定。",
"2021|穿着鞋子的贝壳马塞尔": "当年有多喜欢《约翰·威尔逊的十万个怎么做》，现在就有多喜欢这部电影，专属于生活本身的浪漫和温暖色彩，通过伪纪录片的影像传达出来，而这又是每一个人都能拍的伟大的日常片段。极度真实的细节勾勒，恰恰是对日常生活、人际间情感之深刻体察的见证。捕捉到身边一切有趣的事物，再把它转化成精致、动人的小故事，这就是我们日常生活最本真、最美好的模样。而马塞尔就成为了理想化个体的化身，寄托着人们苦逼生活的美好理想。",
"2021|记忆": "Sure enough, watching art films on the big screen is the ultimate answer to cinema, not only not sleepy, but also completely immersed in it. As the film progressed, my heart rate was gradually rising. In the end, the two connected the memory scene, and the sound of the spacecraft exploded, my heart rate soared to 140. I opened my eyes and completely succumbed to the power of the movie. (Machine translation from my Chinese review)",
"2021|蒙娜丽莎与血月亮": "阿米普尔这部真不烂，哪怕有漏洞满天飞的故事和人物、不加节制的音乐和滑稽重复的特色摄影。影像奇特地保持顺畅的节奏，而对日常景观的既扭曲又富有活力的描绘，在自身内部消解掉所有的硬伤，完全进入了自己的世界。点缀其中的关于族裔、性别、家庭等议题的深层文本，无疑增添了其可有可无的深度。",
"2021|兰茨贝吉斯先生": "以采访独立运动领导人兰茨贝吉斯为线索，用珍贵的纪实影像再现了立陶宛恢复独立这一振奋人心的历史事件。四小时却结构清晰、几无赘笔，洛兹尼察对历史影像的“调度”是大师级别的，他让这些档案资料有了强烈的情感震撼（对中国观众而言）。",
"2021|我和我的兄弟们": "年度十佳，平静而动人，情感的宣泄恰到好处，人物的刻画也极其优秀。关于童年的消逝、亲情的强大力量以及更隐蔽的社会问题，都被巧妙地安置于轻盈的讲述中。极其惊艳的长片首作。",
"2021|海王星霜冻": "A perfect manifesto. 故事性稍弱，但这不是缺点。艺术表达之完整、意识形态构建之大胆，都让人印象深刻。各种象征、隐喻、借代融化在音乐、灯光和特效中，构建了完美的、属于他们的赛博宣言。这不比《黑豹》强几十个档次？",
"2021|一个和四个": "没有表达是很可怕的，哪怕这个悬疑故事拍出来足够吸引人。藏汉之间语言的隔阂、差异、冲突、入侵，以及蕴含于角色之内的身份叙事、环境与文本的互文，这一切都没有深入勾勒，而是明显感受到被有意略过，丢弃在悬疑叙事之后。一部藏地电影，一位藏族导演，这样做属实不应该——不过导演自己都说要拍“爽片”，那对于够不够“藏”的问题，还有什么好说的呢？何况前半段也没多爽，哪怕变着法子耍花枪还是昏昏欲睡。",
"2021|一杯上路": "非常无聊的故事，非常虚浮的情感，非常烦人的闪回，可以降低对《繁花》的期待了。",
"2021|小野田的丛林万夜": "经历太传奇，以至于稍微一努力就非常抓马动人，在这部电影里导演试图淡化这种力量，而是描绘这万夜里主人公缓慢的变化过程。还有就是诗意的表达，几个转场、雨夜的无线电都挺有感觉的，但如果赫尔佐格来拍肯定会更自然一些。最后一个镜头让我想起《再见列宁》，都是情感强烈迸发的电影时刻。其实并不能对这种坚持完全共情，就像没人会赞赏坚持防疫措施到2030年的小区门卫一样。如此坚定某种信念，到头来强调的是这种信仰本身巨大的吞噬性。所以这是法国人拍的一部讽刺电影吗？讽刺的对象仅仅是小野田宽郎的信仰吗？巨大意识形态阴影下的个体，终究是可悲的。",
"2021|奥林匹亚街区": "情绪拿捏极佳，人物刻画优秀，不是看菜下饭而是仔细雕琢，中文对白虽略显生硬但挡不住真实的气息。在我看来，这就是在任何地方能发生的、一个街区里人们的日常生活颂歌。生活本身在这里显得自然无比。",
"2021|彼得罗夫的流感": "电影改编舍弃了太多东西，那股疯狂也弱了不少。当代故事的古典气息，同时又有超现实点缀。比起《电子云层下》力度不足，但仍能从华丽影像中一瞥时代景观。结尾还是拖沓了一点。",
"2021|童一个世界": "全程以特写聚焦人物内心，却又在强烈的真实中触碰外在世界给儿童心灵带来的创伤。摄影机平视人物，几乎没有残留任何剥削的可能。对现实细致入微的观察融入剧本中，72分钟简练、高效，触目惊心。最后停留在兄妹二人和解，实则封闭了女孩角色上升的路径，略显遗憾。",
"2021|火之夜": "重压之下的日常生活描绘，叙事尚可但力量不足。",
"2021|回归故里": "深刻地向我们展示了政治（尤其是阶级叙事和光谱划分）对个体和家庭潜移默化的影响，这是在非民主国家很难感受到的。其中关于法国选举的纪录，到2024年仍然适用——多数法国人没有选择右翼政党，但这是否代表着更大的分裂呢？",
"2021|时代革命": "“有时很懊恼/有时也感到骄傲/有时不后悔/曾这样表达愤怒”——《今夜雪糕》 反送中运动已经过去五年，五年很长，能让这场运动的痕迹几乎完全被抹除，如今的香港已是一片“祥和”气氛；但五年又很短，短到这一切似乎才刚刚发生，而当局对参与者的打压和逮捕，又贯穿于这五年之间，从未停止。物是人非、红色蔓延，在2024年的今天，这部电影对那场运动的纪录，难得之外更让人感到悲壮，不管是片中人物的命运还是电影本身的命运，一切都走向了最坏的结局。 口号越喊越响、行动越来越有组织，而香港人也越来越团结。串联影片的最大暗线，便是香港人集体意识的苏醒与凝聚，这或许也是最令当局惧怕以至封禁影片的原因之一——他们并不害怕示威者的暴力，于他们而言镇压暴动几乎毫无压力；真正害怕的是反叛与复仇的火苗，点燃之后便难以熄灭，哪怕粉饰太平，也能藏匿于噤若寒蝉的人们心中。或者说，是极权的压迫亲手让他们点燃了这把革命之火。 当然，对于片中提到的口号与暴力革命的诸多做法，实际上也并不能完全同意，有时候甚至会觉得正是某些不理智的行为导致了最终中共要下狠手整治香港。但正如海报上所写的那样：是他们选择了时代，因此他们也势必成为这段历史最突出的当事人。是非功过，相信将来有一天自有答案；但如果没有他们的抗争，那一天也永远不会来临。 影片最后聚焦于台湾的选举，强调“华人之光”的典范与鼓舞作用。但个人觉得，大陆视角的缺席，是影片的一个小遗憾。台湾、香港与大陆之间的矛盾越来越尖锐，前者对后者提防、抵制甚至使用暴力，而后者以大家长的傲慢姿态粗暴地挥舞着极权的大棒。香港人的抗争最终目的是自由民主，毫无疑问这亦是两岸三地的共同愿景之一。那些对“讲普通话”的人的仇视与偏见，是否也偏离了抗争的初心呢？无论独立与否，这些运动最终都会落到个体之上，而两岸三地之间硕大的矛盾鸿沟，用仇恨恐无法弥补。 如果说对自己是否选择支持还有所顾虑，那看完这部电影，所有人都会被打动。极权统治是我们共同的敌人，尽管那一天可能会更晚到来，但这个时代中产生的抗争者、他们的运动所产生的巨大震动，却一直存在着。现实已经比影片还要残酷，那还有什么理由不支持他们的斗争呢？只是物是人非、强权执政，山呼海啸的呐喊化为散落人间的游丝，等待某一刻再次凝聚——而这部电影，保持着那股微弱的火光，照亮能看到它的每一个人。",
"2021|永安镇故事集": "之所以还能忍受前两个故事，靠的全是两个女角色，人物真实可感，演员的演绎也很出色。然而这种真实与剧作的结构没有关系——人物的真实只停留在了表面。尤其是第三部分女性角色完全缺位，这才发现前面所有都是为这一part的讽刺笑话段子合集做铺垫，于是就更令人恼火，不仅为这样的油腻感到恶心，还越发感到女角色再度成为工具人，对她们的刻画似乎也瞬间变得扁平。第三部分的“解构”和嘲弄太低级，哪怕充斥着各种吐槽，充其量不过是一集小品。中空的人物、全程端着的影像和文本，如果不是缺一个合适的角度，何必这样拍呢。《野马分鬃》的嘲弄带一点真诚和冷峻的思考，《永安镇故事集》却成了低级浅显的讽刺故事，就像片尾的说唱一样烦人。为什么大家都在笑？",
"2021|玫瑰男孩": "家庭的缺位、爱恋的错位。少有电影关注的题材，但这部略显平庸。印象最深的其实是欧洲教育体系下的那些细腻的老师，有时甚至在思考这样的教育带来的“副作用”是否真如片中描述的一样存在于欧洲的社会体系里。",
"2021|快停下，泽米莉亚": "较为流畅地勾勒出青年群像，对于类似性取向这样的特征处理得很自然，与摄影、配乐和俊男靓女相得益彰，是“好看”的电影。但对于情感的描摹、人物成长的勾勒则欠佳，没有坚实的情感基础，插入期间的伪纪录片式访谈只会是无用功。",
"2021|两位穿着同样内衣的女子": "从头到尾人物弧光基本隐形，故事沦为了警示片似的恶行铺陈。细枝末节太多而抓不住重点，两个多小时显得太冗长。",
"2021|一个不愿观看《泰坦尼克号》的盲人": "一场冒险，两个悬崖边的灵魂——保持尊严、渴望爱情，最终合二为一...极富哲思的故事，或许配乐有些多，但依旧动人。芬兰电影总是有个好结局，这部也不例外。他们或许都是外表冷淡但内心炙热的人吧。",
"2021|盒子": "前20分钟是惊艳的，然而没有情感铺垫，人物也没有说服力，遂逐渐滑向无趣，以至于第三幕的突转基本没有任何震撼。导演对影像、演员的控制力还是不错的，无奈剧作太平庸。",
"2021|大教堂": "时间跨度极大的家庭故事，当然不乏动人瞬间，但重点不在于故事的讲述，而是结合片段式的影像、持续的旁白和真实世界的重大事件来勾勒一段流动的成长经历，以及捕捉那些细小而持久铭记的瞬间。缺点不少，但已比前作好太多，进步明显。 文学性占上风的电影，阅读体验也许会很棒。",
"2021|穿越": "故事和《逃亡》撞车，但情感是真挚动人的，能盖过很多缺点。油画般的质感真是迷人，看到片尾的创作过程之后就很佩服了，非常不容易。",
"2021|破裂": "好疯好好笑，恍惚间嗅到香港疯癫喜剧的味道。这部片没有《雅典娜》那样的无脑暴力，甚至覆盖“光谱”的左中右，但基本立场总是可见。叙事涉及的面向足够丰富，整体却又是喜剧的呈现方式，也因此导向“破裂”愈合的可能，与此同时始终不忘个体关怀——此为无声的抗议。台词写得极好，喜剧情节也足够高级，护士不会操控拍片机器、吊顶脱落之类的情节要笑死人。Corsini的影像调度其实很有嚼头，几个切镜头的点都恰到好处，剪辑也是如此。Valeria大妈演的嘴炮角色也很到位，一开口就令人忍俊不禁！",
"2021|无辜者": "其实是很经典的“小朋友作恶”辩题，只不过套上了奇幻、恐怖的外衣，就好看了很多。故事之外的文本也值得深究，肤色混杂的社区、缺位的父亲等等，也许才是电影的现实意义所在，只不过写得有点模糊。",
"2021|喜剧天王": "影像上，像是美国人看完费里尼之后拍出来的仿品；剧作上，毫不认真、缺乏组织。总之是超越语言桎梏的难看。",
"2021|最后的告别": "监视器、工厂和摩托车构成了独特的当代中国异化景观，但除此之外文本略显匮乏。影像上有许多尝试因而不显得冗长，作为新导演而言值得鼓励。",
"2021|公开赛魅影": "轻松，温暖，鼓舞人心，人菜瘾大也能玩出属于自己的一片天地。更宏大的背景几乎不可见，而情感真挚动人，比《有史以来最棒的啤酒运送》更轻巧。",
"2021|月八日记": "没有什么特别的。轻盈的描绘背后是疫情的社会背景，但一切都显得平常，人与人之间的互动才是最有趣的，然而倒叙冲淡了这些，显得有点无趣。拍电影的电影，还能算是日常记录吗？我更喜欢那部《阳台电影》的多面性，毕竟“每个人都有他自己的电影”。",
"2021|雪豹女王": "做作、浅陋，有些地方甚至令人不适。没人想看镜头对准这两个人，配上自我感动的音乐，听他们叨叨一大堆东西。",
"2021|三层楼上": "三条线、不同时间内的交错，拍得可谓行云流水。“狗血”故事背后对应着生活中难以面对但又不断击中内心的瞬间。然而摄影风格很像电视剧，不太喜欢。",
"2021|塞壬拓扑学": "非常轻松有趣的声音考古学实践，质地清晰可感。",
"2021|我复仇，你付钱": "氛围足够，但影像似乎缺乏内在逻辑。故事、人物、女性主义，放在印度尼西亚的背景里，应该有更独特的表达。理应是一部更精彩、清晰的电影，而不是现在略显浮躁的样子。",
"2021|当我们仰望天空时看见什么？": "冒险的乐趣，生活的脉动，外加静止与流动的时间，这是一部很美的电影。过去、现在与未来在这里交汇，当《意大利之夏》响起，似乎一切都沐浴在舒缓的节奏里。结尾的自白略显多余，其他地方也常有赘笔，确实可以再短一点。",
"2021|安妮·弗兰克在哪里": "结尾白眼都翻到天上去了，非得扯上难民问题，圣母值爆表。从尊重个人表达的角度考虑，这也就算了，但毁了前面故事营造的氛围却是实实在在的问题。时空交错的设定很有意思，不纠结设定也让它区别于美式动画，有很独特的欧洲质感，但就是毁在结尾了。",
"2021|柳川": "故事很简单，算是导演的创作里最“大众”的一部了，但拍法还是像以前一样讲究，倒也没有水土不服，多种语言的交汇让这部电影难以被划分到特定的地域里。悲剧底色的人物，灰蒙蒙的柳川，精准营造的空间感与细腻的文本相得益彰，流淌在张律的影像里。",
"2021|活在当下": "阿黛尔细腻、灵动的表演离不开导演营造的松弛自然的氛围，对空乘工作环境的细致刻画让人立即产生信任，而接电话这样的场面则让人动容。也因此最后伴随女主角iPhone摄像响起的《Faded》，本身确实很土很难听，但在此刻却如此贴合情感氛围。影片正是精准抓住了现代社会背景下的一个个碎片：也许只能被迫活在当下，但总有些东西能抓住我们，哪怕是一瞬间呢。",
"2022|阿尔卡拉斯": "棒极了，人物都是鲜活的，构建出的世界也清晰可感，相信每一个有类似生活体验的观众都能获得共鸣，事件折射出的家庭关系、情感震动，都是极富有生命力的精神表达。这些都离不开优秀的文本，家庭群像的生动刻画之下是社会议题的点缀，更深层的则是人物面对这些冲突时所产生的变化，这些变化正如前文所述是鲜活的，人物与故事、与环境都完美融合在了一起。《哈桑的义务》，看看别人怎么拍的。",
"2022|西线无战事": "啊，母亲，母亲！对你来说，我还是个孩子——为什么我不能投入你怀中痛哭？为何我总要坚强而镇定？我确实比一个孩子大不了多少，柜中还挂着我儿时短小的裤子——那不过是不久以前，为何都成了过去？ 我根本不该回来休假。在前线，我麻木冷漠，时常绝望。现在我再也做不到了。我本是个士兵，现在却只是一个为自己、为母亲、为无休无止而不得安慰的一切感到痛苦的人。 我感到害怕，不敢继续想下去。这条思考的路通向深渊。现在还不是想这些的时候，但我不会放弃。我会守护它，保存它，直至战争结束。我的心在跳动：难道这就是我曾经在战壕中想过的唯一而伟大的目标，是人类经历了一切灾难后，为了生存而寻找的目标？难道这就是为了不辜负这段残酷的岁月，为战后生活找到的使命？ 我很年轻，才二十岁。我对生命的认识，唯有绝望、死亡、恐惧和联结着痛苦深渊的失控的浅薄。我看见民族间被迫为敌。人民沉默、无知、愚蠢、顺从，无辜地互相杀戮。我看见世界上最聪明的头脑在制造武器和言辞，好让这一切更精妙、更持久地延续下去。而在这里、那里，在全世界，我的同龄人都和我一样，看着这一切；我们这一代人都和我一样，经历着这一切。如果有一天我们站起来，走到父辈面前，要求清算，他们该怎么办？如果一个没有战争的年代来临，他们还对我们有什么指望？几年来，我们的工作是杀戮——这是我们人生的第一份职业。我们对生的认识局限于死。以后会发生什么？我们会变成什么样？ ——以上均节选自埃里希·玛丽亚·雷马克《西线无战事》，姜乙译，上海文艺出版社2021年版。  1  如果仔细琢磨，会发现比起雷马克的原著，2022年的这部《西线无战事》显然表现平庸。  首先，和战争的紧迫感恰恰相反的是，小说的叙述其实相对较为平和、冷静。这样的叙事节奏与方法反映了主人公保罗竭尽全力在正常的生活秩序与战场的残酷之间挣扎的情形，而这在他亲手杀死那位法国士兵（也是他第一位亲手杀死的敌人）之后开始失控：内心独白越来越多，沮丧、无力的气氛开始笼罩。  而电影从始至终都在营造战争的“恐怖”（这个词应该非常恰当）氛围，它确实为观看者带来无与伦比的沉浸感，然而丢失了原著小说中描写从冷静到失控、希望到绝望的变化过程。文字的力量显然更强。  其次，去掉保罗放假回乡的情节让人物变得不完整，同时损失了一部分主题的表达。如上文摘录，保罗曾有一段时间离开战场、返回家乡，而正是这一段看似美好的经历让他失去了得以支撑其正常活下去的根基。“休假只会让往后的日子更艰难”，他必须去看望永远失去儿子的同伴母亲，必须面对不久之后又要分别的、他自己的父母，必须亲眼目睹他的人生、他的世界离眼前熟悉的景象越来越远。以前，他不了解战争，并未察觉异样；战争不知不觉击垮了他，他已经完全无法融入眼前的世界，——他知道了战争的真相。他已经死了。  这些都没有在电影中体现出来。这些恰恰是原著小说最精华、最伟大的部分。而额外加入的高层谈判戏倒是为影片增添了一层意义的维度，使得观看者思考上层统治者与前线士兵之间的关系，是否前者的一个小决定就能导致后者的死亡？即使如此，这样的思考在战争片中并不罕见，加入这样的情节并非加分项，甚至有些时候还显得多余。  最后是一个非常隐蔽的问题：这样的反战主题电影真的能使人们热爱和平、反对战争吗？这部电影通过大量写实、直接的战争描绘，从感官上让观看者厌恶战争的存在。血肉横飞的场面背后，一定是一张张皱起眉头的面庞。然而，缺乏更深层次的挖掘，电影中的人物终究和战场上的士兵一样，成为了指挥家手下的棋子。看不到小说中充满深度的描绘，失去了充满哲思而令人悲伤的自白，战争电影真的能达到其预期的效果吗？看看漫威电影吧：哪一部电影不是在战争中开启高潮部分的演绎？不管承不承认，那就是战争，而战争似乎深深刻在了人类的DNA里。  2  坐在屏幕前的我，一定是在正确的时间、正确的地点观看了这部《西线无战事》。尽管它的改变比起雷马克的原著并不完美，但毫无疑问一流的制作水准依旧能让人体会到战争给年轻的士兵们带来的创伤。印象最深的莫过于战壕中的那一刻——和保罗一样，法国士兵也是年轻人，湛蓝色的眼眸在污泥中依旧闪闪发光。背后的枪声传来，他的生命结束了。  他也许和保罗一样，在法国读了书，后来上了前线；也许和保罗一样，有几个铁哥们，后来纷纷在战场失去生命。但有一点是可以肯定的：他们都在统治者的言语之下，投身于这场注定悲剧的战争。  而战争的残酷之处就在于，也许你意识到了战争的真相，却无法停止杀戮。战争的残酷一定会将士兵脑海中被植入的印记清洗干净，然后纷纷醒悟，真正知道到底什么才是值得自己投身奋斗的东西。然而战争已经开始，负罪、恐惧和迷茫会永远伴随着战场上的每一个人，即使战争结束，这一切都不能被消除，直到他们死去。  这才是战争最恐怖的一面。  3  我们身边会发生战争吗？答案是肯定的。任何有独立思考能力的人都能认识到，那场战争是不可避免的。号角还未吹响，但准备是实打实的。去年开始的战争则告诉我们，非正义的战争不仅国际上得不到支持，国内也难征兵。  那么问题就来了：谁来区分正义与非正义？在这片土地上，决定一切的是那只黑箱子中看不见的手。精心设计的话语会被强制刻进每一个人的脑海里，然后战争便开始了。什么是对，什么是错？到那个时候，不会有人关心对错，因为已经失去了意义。而战场上的每一个人，便要为认同或不认同的“共同目标”，献出自己的一切。",
"2022|所有的美丽与血泪": "对往事的描摹，图片竟比会动的影像更有力。那段疯狂的年代似乎就如花火一般瞬间迸发，然后一个接一个地消逝，令人叹息——这也许是南·戈尔丁选择与PAIN携手对抗大药厂的缘由之一吧。两条线的交织不够紧密，是一大遗憾。",
"2022|阿姆斯特丹": "Why can he stole 3 oscar nominations for best directing???",
"2022|阿波罗10½号：太空时代的童年": "和其他导演的怀旧完全不同，林克莱特的怀旧更像是在鼓励童真，找寻大与小、新与旧之间转瞬即逝的惘然若失。当大人们为“错误”之事感到而不满，儿童此时却在不和谐中找到了真正值得思考和纪念的东西。平克·弗洛伊德的<Astronomy Domine>是推动电影情绪的绝佳催化剂。",
"2022|阿根廷，1985": "剧本写得太正，人物很扁平，对事件本身的描摹也缺乏特色；朗读结案陈词的高潮被拍得如此无聊，靠音乐硬煽也没用，看看《刺杀肯尼迪》吧。这类题材的电影拍出来就注定难以收到差评，但也容易浪费题材。我不希望将来有一天我们也有了大量可以拍摄的题材，却拍成这样。",
"2022|世界末日": "动情处皆为真实流露，突兀则体现在创作上的过于自大。很难不被这样一个悲伤的故事所打动，它描绘了向内的似乎无解的困境，而又向外联系。然而种族议题与政治背景似乎被粗暴地置入，没有和深层文本融合，最终停留在表面。几次闪回、幻想实无必要，配乐也过满。但仍是一部好电影，就像是把罗大佑的《童年》表面的旋律外衣揭开，露出世界末日般的童年景象。",
"2022|雅典娜": "不知道在忙什么。开头的长镜头本来还算冷静，片名一出来绷不住了，真是土到爆炸。文本缺乏深度，情节之间缺乏推动力而非常无趣，摄影还不错，但也只能成为奇观展示的帮凶。",
"2022|欧若拉之晨": "动画与真实纪实影像结合，讲述堪称传奇的欧若拉的苦痛经历，可惜实在味同嚼蜡。哪怕最激昂处，也没法引起波澜。",
"2022|巴比伦": "是默片时代的挽歌，还是茨威格式的对人物和历史的怀念？查泽雷的野心无法支撑3小时，而结尾的走马灯更是令人大跌眼镜。虽然如此片子不算难看，剪短一点的话可能会成为一部商业佳作，而不是现在这样票房口碑双输。",
"2022|高墙之外": "用剪辑和音效讲了一个颇具陀氏小说风味的绝望故事，紧张情绪一直延续到影片结尾，高墙之外的枪声和呼喊终于被现实的黑暗所吞噬，那缕烟即是最后的印记。",
"2022|骨及所有": "受不了了，一拳把瓜导打飞！《本色》虽然难看，但好歹还有涌动的情绪、躁动的氛围，到这部电影里真是不知所云。三个人物的故事都足够精彩，足够单拎出来拍一部悬疑片，然而切入点之奇特、剧情处理之潦草，都让故事索然无味，因此最后强行制造的血腥奇观就更显得刻意。说实话，很难看到角色之间有真正的交流，也不理解一定要吃人的设定。总结一下就是瓜达尼诺连最基本的创作理念都丢失了，完全无法（也不想）知道他想干什么。马克·里朗斯的表演是唯一亮点，换个不认识的老白男来演早就出戏了，脸都记不得的。",
"2022|掮客": "如坐针毡，估计是腻歪的情感与强行设计的冲突之间产生的矛盾导致的。水土不服不至于，但并没有把握住日韩文化之间细微的差异。",
"2022|姐弟": "很喜欢《欺骗》，但不喜欢这部。不管怎样你都得承认戴普勒尚在这部电影里的叙事和人物塑造是失败的，难道要从模糊不清的话语里寻找所谓的“混乱”感吗？况且推动叙事的动力缺乏深层稳定的基础，因此最后的和解让整个故事更像是俩人做作了两个小时。结尾的非洲段落令人费解，若为讽刺情节则无法解释前部分的复杂情感，若为真情实感的设计则更令人厌烦。",
"2022|子弹列车": "看着挺爽，然而问题很多。歌曲滥用、蒙太奇闪回太多都是小事，难以忍受的是这个站不住脚的故事情节以及强行赋予的内涵。对东京的刻画也算是刻板印象了。",
"2022|恰恰丝滑": "Wrapping an older boy's coming of age story in a cosy shell, Cooper Raiff has a light in his eyes and shows a lot of moments that add to the slightly plodding drama, the expressions are spot on, I watched the corners of my mouth unconsciously lift and it's really cute.",
"2022|炭": "感觉像是输入“南美”“毒品”“同性”“家庭”“儿童”“犯罪”“奇观”等耸动词汇之后无脑生成的电影。",
"2022|智利，1976": "似乎是一部别具一格的历史“谍战”悬疑片，但视点始终聚焦于女性主角之上，独特摄影和出彩配乐搭建的女性视角框架成功地冲淡了历史叙事的宏大性，而更关心个体。挺不错的导演首作，值得一看。",
"2022|亲密": "很难不被打动，但也遗憾于有些时候没能更好地处理文本与影像之间的微妙关系，从而就不能持续给予情感的震颤。",
"2022|大陆向南漂移": "后全球化时代的荒诞种种，但空有碎片，连起来却绵软无力，可能还不如相似主题的短视频。",
"2022|束胸": "导演前作《脚下的土地》和这部《束胸》都在讲女性被束缚，后者借茜茜公主的前朝剑其实是在反映跨越时代的女性困境，这也可以解释影片中有悖时代特征的描绘。略显可惜的是，它只试图展现一个截面，她的困境过早被抛出，后续的冲突设定更像是原地打转，因此找不到可以收束的关键点，最后跳海草草了结。角色的多面性，更依赖于Vicky Krieps的出彩表演，文本上的体现不足。总结一下就是：文本太单薄，支撑不起一部电影。",
"2022|未来罪行": "喜欢柯南伯格的高概念、颠覆感官的体验，但是很讨厌他大段大段地往作品中塞入对白，影像本该是文本的补充和提升，在柯南伯格这里很割裂，大场面像是注解。所谓的new sex确实非常震撼，痛感也是影像的重要部分，但除此之外真的乏善可陈，最后还唐突结束，意犹未尽。给《赛博朋克2077》里面装义体的过场动画弄成VR可能更爽，《未来罪行》里面大部分的思考和体验游戏里都有。",
"2022|鸦雀皆白": "影片中呈现的非虚构写作路径无疑受到了约翰·威尔逊的影响，不管是议题选择还是摄影机的姿态，整体基本是松弛有趣的；而最后突如其来的情感爆炸时刻无疑是动人的，囿于宗教而陷入巨大价值冲突的主人公借助日本的宗教找到了价值的终点，与家人达成了和解——对我们这些东亚的人而言，这是多么容易共情、无比羡慕的结局呀！也因此片中的一些瑕疵容易被忽略了，例如摄影机对日本修道院的介入实在过于野蛮了，甚至有点冒犯；最结尾与父母的坦白本应该是自然的，却煞有介事摆出摄影机、打上场记板，虽能共情但也显得生硬。",
"2022|人体结构": "影像深入人体深处，超越理性的身体展示。影像掌控力独具一格，最后伴着New Order的音乐，人们肆意舞动，画面失去焦点、抽帧，随后聚焦于描绘身体器官的壁画之上——无疑是从愚昧虚伪之间夺回了身体的主权。关于人的本能的绝佳展示，无需任何美学理论就能直抵意识深处。",
"2022|分手的决心": "故事还是落入了过度解读的重灾区，电影真正的亮点在于细节的描摹，而不是故事本身，这也是我看《老男孩》时的感受，二十年了一点进步都没有。没有炫酷的场面调度只会让这部导演更难熬。能把iPhone 8/SE2/SE3三部手机长得一样这个槽点写进剧本，也挺有趣的。",
"2022|猫王": "就比《梅艳芳》稍微好一点，故事切入点不俗套，加上眼花缭乱的剪辑。选角比较失败，奥斯汀·巴特勒的表演是鸡肋，演不出猫王的气韵。其实这类音乐传记片无非就看两点，一是对showbiz的揭露，二是无法融入/自毁的悲剧，但要是真就这么老老实实拍出来，还不如去看维基百科。",
"2022|驴叫": "陷入精致的怪圈，影像毫无自我生长的活力，现实议题的点缀只显得有心无力。阿诺德的《奶牛》不论是文本还是影像意识都更胜一筹。",
"2022|瞬息全宇宙": "无趣的故事老套的内核，多元宇宙固然新奇，但沉浸其中只会让人厌烦。不注重情感的铺陈，最后局面实在无法控制便开始对着镜头讲道理，在不同宇宙之间穿来穿去也成了无聊的换装表演。导演技法随心所欲，剪辑让人脑壳疼。",
"2022|猎鹰湖": "没有沉浸在青春的糖水中，也没有让奇幻喧宾夺主——有的只是细腻的情感和怅然若失的激荡，几场戏拍得极好，小男演员咧嘴一笑全片最佳。",
"2022|火山挚恋": "一篇标准的《国家地理》人物小传，自摄影像比很多专业导演都要动人，剪辑上偶尔的调皮瞬间很讨喜。除此之外不管是火山还是挚恋，都没有深入触及。最后从两人的故事上升到人类探索自然的伟大，倒是令人恍惚：他们真是天生的一对。",
"2022|变通美食家": "柯南伯格的平庸模仿者，虽然甚至一度以为导演提前看过《未来罪行》并借鉴之，但胡言乱语阿巴阿巴的文本真是令人头疼，和这部电影比起来柯南伯格都变得亲近了很多。希腊语台词英文字幕里居然没有，最终解决这个问题的是一个荷兰语的字幕文件，你说搞不搞笑。",
"2022|有趣页面": "复古的、涉世不深的美。虽说是一个稍显混乱的成长故事，但展开的方式绝对是出人意料的。情节的串连、场面的调度，则让人想起很多美国年轻导演。有个好剧本可能就会起飞了。",
"2022|孤独地貌": "声音、物质和影像的有机组织令人眼前一亮，但随之而来的就是刻意拖慢的时间。感觉没必要拍得这么闷哇，明明可以更好看，那些斑斓的所见、动物的微声，绝不该淡然地隐没在ASMR式的影像之中。",
"2022|利刃出鞘2": "一切都低级、老土到令人发笑，最后真敢用虫团的歌当片尾曲，真是low到极点。",
"2022|神之造物": "A24认为这种故事就该这么拍？烂导演毁故事的典型作品，如果说故事有60分，那这部电影就只拍出了6分。很多时候无法揣摩影像的含义，更糟糕的是在这基础上还要凹摄影、怼配乐，简直是视听折磨、催眠盛宴。当然剧本也不见得有多好，结构失衡、人物稀烂。可怕的电影。",
"2022|祝你好运，里奥·格兰德": "看起来女主通过和鸭的交流找到了真正的自己，两人也达成了某种双向治愈的效果，但内核是根本站不住脚的，情感的支撑经不起深究。拍“大胆面对自己的欲望”这样的话题，本质上是非常安全而不是大胆的创作，更何况第四次见面时女主的自白说教性如此强，设计的主题在此时压倒了情感的真实本身。",
"2022|何处生长": "对独生子女政策的愤怒是一切的原点，但展开的情节实在太过平庸：无效的悬疑、脸谱化的人物和猜得到的走向，哪怕是为了醋包的饺子，也不至于如此刻意；对压抑和痛苦的归因尚且值得商榷，但结尾口号式的上扬着实让人皱眉——历史的伤疤、人性的阴暗，真的能一笔勾销吗？",
"2022|吉尔莫·德尔·托罗的匹诺曹": "《深海》那帮人应该跪下好好把这部电影看十遍，想想你们的故作高深会显得多么无趣。托罗最喜欢的童话故事，战争、暗黑元素都只是点缀，对死亡的描绘以及直面黑暗之后的强大精神力量才是最动人的地方。虽然没说自己是子供向动画，但时刻体现着创作者的自觉以及明晰的创作指向，比起混乱而幼稚的莫名其妙不知道高到哪里去了。电影化的调度反而成为了违和的地方，定格动画就应该化繁为简嘛，动画里又没有摄影机。",
"2022|空中花园": "绝对没想到是这样一个故事，中段展开的儿童视角既有趣又准确，将迫于宗教压迫而陷入性压抑的群体刻画得淋漓尽致，不失讽刺和幽默；但整个故事要处理的议题太多，社会问题、民主革命、被美国侵略的历史甚至对伊斯兰教义的反思，都如蜻蜓点水、浅尝辄止，儿童视角亦不真实，以开头和结尾的设计最为明显，为了完成主题表达人物显得过于成熟，小孩的成长不是一把火就能概括的。后段横插一笔犯罪片追逐戏，然后两个小孩就被送回家，一切回到原点，这处理未免也太突兀了。",
"2022|哈珀的彗星": "别的新导演可以学一下小成本怎么拍出引人入胜的氛围感。",
"2022|孵化": "故事的主题是值得思考的，但各种细节都不走心，无法支撑主题的表达。若以恐怖片的标准来评判也不合格，拿来吓人的东西要么没头没尾要么陈词滥调，无甚新意。",
"2022|圣蛛": "最令人毛骨悚然的可能不是目睹女性被勒死，而是以宗教为借口行杀戮之事对女主角的威胁，甚至要号召别的“弟兄”继续实施恶行，这无疑令人绝望。以宗教（或其类似物）作为统治合法性来源的政府，自然没有主观意愿抓凶手，反倒是自上而下因此带来的放纵让沟壑越来越难以弥合，女记者只能用如此冒险的方式抓凶手，到头来还是男人在邀功。电影难以避免成了对伊朗的理想化呈现，说到底这只是一部欧洲电影。阿里·阿巴斯有时显得太装外宾，有时又太沉浸于表现奇观，用力过猛。",
"2022|狩猎": "要是能写，我们估计也可以生产出对应历史事件的无数剧本，所以这个故事并无特殊之处，值得称道的是细节与现实的对应以及前后的对应，后期反转时带来爽感。作为处女作无功无过，不说还不知道这是新导演拍的，倒是凸显了韩国电影工业的强势。",
"2022|乐土": "震撼的女性故事，叹息之余更感悲哀。新导演首作沉稳大气，只是“旁视”过多，或许阻碍了情感进一步的迸发。",
"2022|KIMI": "原来是索德伯格的《黑镜》，刻画现代科技，内核却仍是复古的。街头手持摄影的处理、密闭空间的氛围营造则重回《失心病狂》。",
"2022|克朗代克": "长镜头+大全景，讲述的却是战争之下的“日常”生活，有时甚至拍出片刻轻松——一开始不免觉得有些突兀，但后半段风云突变，以这样的方式呈现的惨痛景象极具震撼力，也昭示战争对平民毁灭式的伤害。然而结尾意识形态挂帅，虽说是乌政府资助电影，但也未免太过刻奇，连那场分娩戏都在疼痛之中有了一丝剥削感。",
"2022|回家的最后一班飞机": "不管是家人的陪伴还是Eli本人的坚定，都传递着一个信息：死亡不是可怕的东西。然而当最后全家人围在床榻旁陪伴老爷子走完最后一段旅程，死亡本身的巨大震撼还是深深击中了我，不需要任何精美修饰的影像就能受到极大的震动。任何人都有失去至亲的那一天，如果能像影片中老爷子和他的家人那样平静而坚定地走完最后一段路，便不再畏惧离别的到来，因为爱早已像那缕细绳，连系每一个人，最后系在他的手腕上，他带着它离开。不太喜欢最后的配乐，这样的纪实或许不应该有任何配乐。",
"2022|莱奥诺拉的告别": "年度十佳，前后完全不割裂，反倒是一气呵成，文本的文学性带来了巨大的力量。围绕看不见的皮兰德娄展开的故事，恰恰就是老导演回望过去、把对亡兄的复杂情感寄托于那个黑白的时代所进行的二元化创造，由此引出后半部分，借描绘未尽之创作而为逝去之人的生涯画上完美的句号，交响乐、穹顶与孤独凭吊的老人在最后重叠在一起，这是最动人的一刻。",
"2019|尽管爱": "哭笑不得但又很真实的故事，传达的感性经验是足以连接观众的。今泉力哉的写作很流畅，然而城定秀夫导出来的电影似乎一股美国味，几个转折处的调度处理都被猜到了，节奏也把握得不是很好。",
"2022|交错卢森堡": "Not everyone can be Aki Kaurismäki",
"2022|火星一号": "对《加加林》的拙劣且不走心的戏仿。",
"2022|园艺大师": "文本内驱力与独特影像气质的完美呈现，情节乱写似乎都不重要了。比起前作，施拉德这次显然有所改变，类型化的尝试、点到为止的现实命题，感觉再憋几部大的就要来了。",
"2022|穆岑巴赫": "除了高概念以外平平无奇，那些男人的尴尬表现似乎都在意料之内，100分钟还是太长了。",
"2022|我的幻想国度": "访谈的部分很无聊，还不如从自己拍的电影部分切入呢。感觉整体还是略显松散，虽然强劲的表达依然存在。",
"2022|保姆": "类型化的尝试值得肯定，尽管故事、意象、隐喻、调度、情感表达都是一团糟。再怎么说也比那部《纽带》要好。",
"2022|纳瓦尔尼": "Liu",
"2022|下一个素熙": "出发点过于现实，以至于电影之外的文本介入实在太过频繁。不过整体还是保持了克制，尽管有些时候情节上的过火、人物的老套刻画也影响观感。",
"2022|关于我家的一切": "颠沛流离的家族史，处理方式却如此轻松简单。也许家族中充满爱的不变之物才是传承所在，但影片对此的刻画又太浅了，几处有趣的细节都戛然而止，没有建立起对家族情感的坚实纽带。",
"2022|跟我走吧": "笑嘻了，真正高级、在世的当代书写，有着绵密肌理的同时，影像气质又如此迷人，保持着自然的节奏。",
"2022|不": "就喜欢这种用顶级制作讲一个WTF故事的电影，故事的展开几乎完全猜不到，而内部文本富有深度，从各个角度来理解居然都与故事自洽，最表面的种族问题反倒成了障眼法，乔丹·皮尔的剧本写作是值得学习的。而在IMAX摄影机、优秀配乐和顶尖摄影师霍伊特·范·霍特玛的护航下，皮尔的导演能力终于释放出最大能量，初遇不明飞行物的那一场夜戏持续十几分钟的大场面，调度上难度很大，导演完美地完成了这场戏，牢牢地把观众按在椅子上。好莱坞呼唤多年的能驾驭商业片的大导演，这不就来了吗。",
"2022|乡愁": "Mr Martone, please stop.",
"2022|燃烧的巴黎圣母院": "感觉像是中国导演拍出来的主旋律电影（导演确实拍过《狼图腾》），配乐拉满，视听语言稀烂，穿插真实画面的剪辑不算新鲜，超越事实的一定的戏剧加工倒是值得学习，这让这部电影不至于太无聊。",
"2022|晨光正好": "用动作和地点的快速切换取代了情节的营造，却在剪辑中产生情感的强度。有点像侯麦，但如此现实的人物情节设定，又迥然不同。独属于女导演的洞察：女性的现实体验、未来恐惧和当下之爱。",
"2022|岛屿上的煎熬": "情节和人物都模糊的同时，塞拉纯粹用锐利而神秘的影像完成了诠释“政治”的抽象性表达，而漂浮在群体上方的某种症候，则无声地融于角色的动作中，甚至无需多言。《坚如磐石》堆砌霓虹灯和角色却达不到的目的，被塞拉轻松拿下：摄影机转向何处，何处就是政治的幽灵所在；而超越常规的驻留，则更像等待幽灵的出现。",
"2022|珀尔": "很完整的表达。虽然矛盾冲突的设计略显刻意，作为前传也不可避免因为一眼看到结局而导致情感营造的急促和浅薄，但对珀尔的人物刻画、社会环境与家庭环境对她的影响，这些方面都显示出超越恐怖片惯常经验的尝试。",
"2022|七五计划": "聚焦倍赏千惠子的那条故事线显然会更动人，估计导演是想勾勒一个全景，然而散点式的讲述并没有更多文本之外的亮点，剧作层面比较失败；配乐、摄影似乎用力过猛，很多时候导演试图拗情绪，然而都失败了，反倒是演员的表演能打动我。",
"2022|核磁共振": "碎片的交织逐渐指向清晰的线路，但结尾不免令人哑然。本以为能在诡谲的小镇氛围中持续产生更多对个体生命的描绘，但很快就拨云见日流向现实议题，也让人遗憾。由罗马尼亚折射出的现实之辩，那场超长集会戏已说明一切，看完很难不想到周遭的一切。",
"2022|隐入尘烟": "细节的呈现哪怕再真实也仍是一个理想化的故事，而情感的真实性在影像与文本的碰撞下打了折扣。大量中、远景，保持距离而不介入，给了观众大量的空白去思考，但深层的文本却因客观原因而不可见，最终只写下一个悲惨的故事“隐入尘烟”。虽然大部分时间导演都非常节制，但偶尔流露出的不克制，对观感确实略有影响。",
"2022|巴黎记忆": "寻找创伤记忆的流水账，文本上的可挖掘性与干涩的影像是不匹配的。如果是美剧，在“可看性”上一定会高出几个台阶。埃菲拉的表演几乎撑起了电影无趣的段落。",
"2022|莱茵金": "Fatih Scorsese",
"2022|米仔睡着了": "情节很套路，影像很做作。",
"2022|宝石长袍": "故意不说人话不讲故事反倒吸引我了，视听语言和影像逻辑都不错的。前提是能忍受故作深沉的外壳。",
"2022|摩托竞技会": "地下赛车题材常见于游戏，常常以美式陈词滥调点缀之——这部电影却全无那种油腻、做作之感，对地下赛车群体的刻画是真实可感的，也勾勒了他们的困境。然而镜头转向主角，就又落入俗套青春片之窠臼，摩托车作为某种隐喻，似乎没有很好表达出来。",
"2022|安全领域": "精致影像构造深邃留白，但迷失于模糊的对白之间，似乎也找不到方向。充沛的情感或许需要细腻的情节安排来承载。",
"2022|圣奥梅尔": "和爱丽丝·迪欧普的前作《我们》一起看的，比起说话的内容，表现言语的姿态才是正经事，所以才要不嫌烦地让角色面对镜头一字一句念出来，这在《圣奥梅尔》里更具破坏力，并且通过凝视、话语和对位书写延续了前作的主题。纪实式的超长庭审戏不觉厌烦，倒是强行cue美狄亚贞德令人尴尬。后半段的影像气质与前作一脉相承，某种松散但持续在场的组织逻辑。",
"2022|土星保龄球": "可以是一部单纯的叙事电影，但影像上的出其不意让人赞叹。",
"2022|她说": "很喜欢《欺骗》，但不喜欢这部。不管怎样你都得承认戴普勒尚在这部电影里的叙事和人物塑造是失败的，难道要从模糊不清的话语里寻找所谓的“混乱”感吗？况且推动叙事的动力缺乏深层稳定的基础，因此最后的和解让整个故事更像是俩人做作了两个小时。结尾的非洲段落令人费解，若为讽刺情节则无法解释前部分的复杂情感，若为真情实感的设计则更令人厌烦。",
"2022|受够了自己": "令人悲伤的事实：我们必须摧毁自身的某个部分才能融入这个扭曲的世界。这部电影很讽刺，但更重要的是挖掘出了每个人内心最“变态”的阴暗角落。片中对艺术、模特行业的讽刺，感觉比鲁本高级。配乐再平缓一些会更自然。",
"2022|尘默呼吸": "沉重的死亡纪实，本身力度已足够，但投射到孩童身上的眼光未免有些剥削。进而，纪录片的立场也值得怀疑。和王兵比，谁更在乎纪录的对象、谁更真切地将自己融入影像之中，高下立判。",
"2022|惠子，凝视": "从拳击中寻觅音乐节奏，在日常生活中找到生命的闪光。文本层面反而太完整了，以至于对应到影像层面就偶而显得闷。不过16mm胶片、音效设计创造的质感还是很迷人的，指向的依旧是三宅唱电影里的那种自然、真实的状态。",
"2022|吸烟致咳": "特摄片的特色与潜质发挥得不够尽兴，更像是戏谑和玩笑，而想一出是一出的情节组织方式，哪怕是77分钟的片长也会让人找不着北。",
"2022|巴黎之子": "尽管情节稀烂，但类型化特色清晰可感。最难得的是，在化繁为简的高效影像中，超现实元素的融入竟不显违和。若指向性更明确，或许能激活影像的潜力。",
"2022|保持清醒": "虽无影像上的突出追求，但剧作上仍足够吸引人；偶尔的陈词滥调并不影响人物与情感的表达，与此同时始终是淡淡的感觉，值得点赞。两兄弟关系的刻画和情感的碰撞是近年来看过很不错的。",
"2022|柴可夫斯基的妻子": "比《音乐大师》刺痛得多，但哪怕绝对主体是女性，这两部电影都还是要以男人为题。也因此，出色的人物刻画不等于深入了人物的内心。",
"2022|像这样的夏天": "开头全特写的勾勒，模糊空间感的同时就营造出暧昧、模糊的氛围，全片很多地方都颇有想法；然而颇具潜力的影像却迷失在缺乏深度的文本中，有虎头蛇尾之感，非常可惜。导演似乎不设立场，让角色讲述经历以避免剥削指控，然而在零星的碎片之间，依旧能看出与LVT的差距。",
"2022|泡泡剧组": "能让我笑出来的喜剧，是那种美国人最爱的pain jokes，冷静下来回想确实缺乏深度。不可忽视的一点就是拍出了疫情期间（尤其是隔离期间）人们被逼疯的现状，虽然很直接很粗暴。",
"2022|永恒的女儿": "虽说是个寡淡的家庭关系故事，但乔安娜·霍格也拍得足够扣人心弦。复古阴暗的色调，靠一些现代器具才不至于让人穿越——有几个瞬间印象深刻，体现了导演平地起惊雷的特色。",
"2022|流亡者": "很好的纪录片。没有想象中的沉重或是全程抨击，而是几乎一直聚焦于个体的叙事。而Choy，不仅是提供了影像资料这么简单，而是以一种不同的身份视角重新审视这些exiles，进而以小见大地重新审视历史、当下和未来，以及不同身份认同之下的生活。可贵的是纪录片的表层是老友重逢的温和故事，没有刻意批判与煽情，但这些exiles的生活状态就是最有力的情感炸弹。这部电影前所未有地展现了事件的多个维度，如此自然而有力，但也流露出悲凉和愤怒。",
"2022|造梦之家": "Bomb",
"2022|心火：写给火山夫妇的安魂曲": "Even like Herzog, such a maniac director, can be stunned to silence watching their original footage. That's the greatest power.",
"2022|灌篮高手": "没有情怀，因此观看时震撼全来自于体育比赛本身。一切都在为最后一秒的屏息做准备，那个时刻到来时反而没有很兴奋，不过还是产生了呐喊的冲动。",
"2022|五恶魔": "为爱情远走他乡，却找不到自己的位置。语言淡忘、水土消逝，幸而心底还留有一丝温存。两人的化学反应激发了动人的情感，细腻而不失冷静的表达挖掘出人物的深度。结尾三人骑着摩托隐入雾霭美丽至极，然而有时配乐也喧宾夺主。导演对于那些性感和色情的情节、事物的拿捏恰到好处，体现于两位主演的身体接触之中。",
"2022|有史以来最棒的啤酒运送": "剧本很扎实，其他方面很鸡肋，论反战的深刻程度比不上《西线无战事》，作为喜剧又不如《陆军野战医院》，甚至《第二十二条军规》那样无厘头。但有字面意义上的好看，以及常常流露出的真诚。非常适合在国内上映的“主旋律”，当然这个题材肯定是不能过审的。",
"2022|世界之王": "拍得很漂亮，但拉丁美洲的罪恶和黑暗并没有很好体现在影像的进行中，剧作方面不太成功，缺乏密度的文本使得其一路泄气，到最后本应高潮的部分随着反高潮处理隐入尘烟、无影无踪了。中间有一段简直是照着老塔《潜行者》拍的，然而只学到皮毛，内在的驱动因素一点都没有。",
"2022|菜单": "综艺级烂作，简直就是胡编，拍得cult点或许高看一眼。只有1%的时候能感觉这是《继承之战》的金牌导演马克·米罗拍的。",
"2022|中间时代": "可能是最有趣也最机智的描绘“居家”时期人类生活的作品。其中不少一本正经的搞笑段落让人想起John Wilson的纪实影像，但《中间时代》无疑模糊了虚构与真实的界限，在对身体、情感与人际关系俏皮的探讨中触及了深邃的存在命题。最令人欣喜的同样还有“潘佩罗小组”螺丝壳中做道场的强大能力，调动所有家庭成员完成的影像真实可感，激发了这种创作模式最大的感染力。",
"2022|北欧人": "灵气全无，导演应该去弄《刺客信条：英灵殿》，挽救一下育碧的艺术水准，做成电影就非常僵硬。故事很老套，看斯卡斯加德和妮可基德曼近战1v1真的很好笑。",
"2022|夏日细语": "看不到对人物真实而深入的体察，而影像又如此做作，总感觉目的不纯，很不自然。视听语言其实一点都不克制，几个慢镜头给我看吐了。这难道不算是一种剥削吗？",
"2022|沉默的双胞胎": "她们的身世、身份认同、遭霸凌的往事、写作的内容、恋爱中情感的矛盾以及周围人的阻力，这些点哪怕有一丝勾连都不至于这么无聊。取而代之的是动物园表演一样的凝视，看着角色在一个地方发疯，然后去下一个地方接着发疯：只注重形式上、自我陶醉式的“瞬间”捕捉而对人物、情节、文本毫无深挖的意欲，哪怕有不错的光影色彩以及选歌口味，整部电影仍然是一团乱麻，不知道在干什么。",
"2022|正义回廊": "表面讲杀人案和审判，实则是拍出了一场精彩而深邃的公共讨论，这也很好解释了影片中那么多的细枝末节。公义之外，又是什么在影响一切呢？香港的未来又在哪里？每个人看完都有自己的不同回答，这就是这部电影最大的魅力。",
"2022|领地": "一片雨林，就牵出族群之间、地区政治之间乃至国家与世界未来的矛盾。这片领地俨然成为了一个巨大的矛盾体，映射着国家正在发生和将要发生的一切。所以当博索纳罗的名字一次又一次被提及，他成为了一个邪恶的符号，而影片明显未深入探求之，其他方面亦如是。或许本片作为纪实作品最大的震撼，一是年轻的族群首领竟瞬间被夺去生命，二是仍有一群人拿着电锯穿梭于雨林中，争夺土地，而这两件事都发生在此时此刻，而不是文明尚未开化的时代。",
"2022|天才不能承受之重": "meta并没有使得故事更有趣。电影里拍电影的喜剧让我跳戏到《泡泡剧组》，主要是因为佩德罗·帕斯卡都在，不过《泡泡剧组》显然要有意思一点，这部快成凯奇洗白片了，然而不是每个人都关心电影里描绘的那些破事。",
"2022|鲸": "为什么总喜欢把尘封的伤疤暴力割开，再撒上几把盐呢？不是很喜欢这样的创作取向。剧作家改编的剧本无功无过，人物都只有一副面孔，帅哥传教士角色功能性有点强，好在有个信得过的结尾；女儿这个角色写得很糟糕，令人生厌的特质铺垫了大半篇，最后突然和解流泪令人疑惑。阿伦诺夫斯基赋予影片油腻、投机的气质，不管是摄影机的运动还是“适时”的配乐，都令人感到不适，有剥削之感。",
"2022|13条命": "剧本是真烂啊，唯一优点是没有过度美化白人的贡献，但除此之外一点亮点都无，援救过程倒展现得很流畅，但这是最基本的东西。如此复杂的文化语境和情感交融之下理应有更好的展开角度，最终却选了这种人畜无害的白开水方式，内核之单薄让人怀疑拍成剧情片的必要性。分离提纯一下，这部电影和《中国医生》之流没什么区别，都是在歌颂一个寡淡的情感主题，只不过用国外先进的电影技术包装之后，它比国内的屎好吃一点。如果不说这是朗·霍华德导演的电影，反而在片尾贴上刘伟强的名字，或许都没有违和感。",
"2022|三千年的渴望": "拍得特无聊，米高梅没人把关吗？怀疑原著要比电影好看很多，感觉不太适合拍成电影。",
"2022|致莱斯利": "后半段就有点搞笑了。女主演技是挺不错，但肯定没到提名的地步。",
"2022|壮志凌云：独行侠": "不是那种自我感动的怀旧，而是精心编排的英雄回归。几乎挑不出毛病，故事是有点老套，但剧本写得很好啊。像这样拍得非常优秀的商业大片，哪怕你对这个题材不感冒也会在音乐响起时起一身鸡皮疙瘩。",
"2022|迷雾中的她": "（上下合） 有拍得特别牛的地方，但整体看完还是神经衰弱、不得要领。",
"2022|悲情三角": "这还不够屎尿屁吗？讽刺得过于直白了，有时甚至低级。第二部分拍得还行，仅限于调度和剪辑。在如此无趣的讽刺文本的衬托下，Michel Franco都显得可爱了起来。",
"2022|青春变形记": "是一部惊悚片，令人窒息的母爱和家族关系，表面的春秋笔法其实挺成功的，但缺少内部的自反性，因而我并不想再次体验这种窒息的感觉，所谓的成长故事也变得无趣和令人生厌。对不了解东方文化的西方人来说，那场仪式简直像恐怖片，而导演恰恰就在进行这方面的努力。",
"2022|塔尔": "就是在讲超越性别的、基于某个领域和体系的人的恶行，剧本写得很好，但人物刻画上不可避免的俗套显现出导演兼编剧处理性别、身份认同等话题上的短板。当然可以如此刻画一位复杂而敏感的角色，但若显露刻板的描绘，就会影响表达的独立性和客观性。由此出发这部电影就变成了一部纯纯的揭露人性黑暗面的爽片，而精密的影像强化了这种震撼。大段对话却丝毫没有拖慢节奏，不仅是因为剧本写得好，而且剪辑也要立大功。导演倒是无功无过，可能是很久没拿起导筒了。",
"2022|独角兽战争": "过于粗浅的寓言，甚至能找出与现实的对应关系。画风确实出人意料，但也没有上下翻飞的程度。",
"2022|直到树枝弯曲": "不想拿来比，但确实有股《双峰》混搭欧式新农村题材的赶脚。。。几个“电影时刻”都足够精彩，相比之下人物刻画就比较一般了，并且没有和其他部分取得平衡。",
"2022|塔楼上": "就我看过的这几部洪片得到的经验：没有金敏喜，电影总体就会变得很悲观。空间变化、虚虚实实，在看似正常的对话里不断输出扎心的东西。权海骁的角色无疑是洪导一部分人格的化身，讲精神困境、讲自己的创作、探讨自己的弱点、人与人之间的关系，等等。你可以在洪尚秀的电影里看到很多东西，但呈现方式又是极简的。而简单不代表粗糙，“塔”的先行概念成为电影的主要结构，几场室内戏的简单调度就能看出对影像的掌控力。以及熟悉而神奇的“洪尚秀时刻”，权海骁对着过曝的窗户说风景真好，我却真的看到了窗外的风景似的。",
"2022|孩子们": "摄影机的姿态决定了影像的真实、关怀和动人，和《青春：春》一样，看到最后我们也能惊奇地发现片中人物竟然有如此巨大的成长变化。而关于印第安人与白人关系的刻画则更是举重若轻，轻轻松松就完成了《花月杀手》拧巴了三个半小时都说不清楚的东西。",
"2022|当浪潮已逝": "迪亚兹这部3小时应该算是比较容易入门的一部，但看下来感觉不如他的其他作品，一是口号喊话太多，二是符号和情节都太直白了，缺少《停止》里面丰富的政治惊悚元素和男女人物刻画，看着不过瘾。但单论影像层面，迪亚兹似乎又进一步，每个固定镜头的设计和其中人物的运动都非常准确，他成功把固定镜头的时间流逝转变为真实时空之下强权压抑的残酷症候，与阿彼察邦隔空对话；而突然出现的手持镜头又打破了这种秩序，将摄影机对准受难的个体，是其最具人道主义的悲怆意味所在。",
"2022|当你拯救完世界": "没有办法从任何人任何事身上获得满足的人是最孤独的，卷西唯一在拍的在写的就是这一点。所以摩尔那些真情流露的瞬间都很动人，精湛的表演是一方面，更重要的是内部的强烈情感震荡。",
"2022|风再起时": "倒也不完全就是一坨，许冠文最后和一群英国人对峙的那场戏还是很出色的，配乐与现实影像的蒙太奇叠加，让故事的表达还算有了收束的空间。然而除此之外翁子光这部电影可以说是彻彻底底的失败之作，它的烂不仅体现在文本上的力不从心、剪辑调度上的混乱不堪，而且从内到外都给人一种毫无逻辑、一通乱来的脏污感。这不叫个人风格，这也不叫“文艺”，这就是单纯的烂。",
"2022|X": "越来越觉得恐怖片里的故事是次要的，要让位于气氛的营造和恐怖桥段的设计，故事能看就行。退一步讲《X》的故事也并非如此臭不可闻，至少在关键情节上是反常规的。至少，你应该不会在一部俗套的恐怖片里看到女主成功逃脱后拿出毒品享受大肆吸食的快感。剧作层面绝对是精心雕琢过的。",
"2023|门前宝地": "徐导的摄影机就跟无头苍蝇似的到处飞，原来这角色个个都是无缝蛋啊。但是我相信，只要这种形式感再进一步，继续装逼，徐导就会迎来自己的John Wick。",
"2023|首尔之春": "开头和结尾的少数段落能体现出历史的荒诞和政治的虚伪，其余大部分段落只是历史同人文的类型化而已，缺乏神秘感。",
"2023|马里乌波尔20天": "几乎是一部纯粹的纪实影像，残酷的影像展示了未被惩罚的罪行，又以极其震撼的表现力不断地谴责它们。正义之船终会抵达彼岸，而这些出入于战场的新闻工作者就是照亮真相的灯塔。",
"2023|两万种蜜蜂": "不管是文本深度还是影像表达似乎都显得偷懒、无趣，感染力不足。最后众人高喊小孩“错误的”名字，是全片少有的深度时刻：呼喊名字对于孩童的身份建构，似乎有更深刻、更超越的影响。",
"2023|老枪": "所有人的困境都与背后看不见的黑暗有关，牵一发而动全身的复杂关系，本应该是剧作的重点所在，结尾却用一场较为寡淡且直抒胸臆的枪战展开，有点可惜了精心设计的时代背景和人物弧光。",
"2023|王子": "感觉男同性恋老了说梦话拍成电影，大概就是这部电影的样子。。。",
"2023|富都青年": "用最笨拙、无趣的方式展现移民议题，但价值观又较为陈腐，尤其是对女性和少数群体的刻画，表面无害而深度不足。暴力不是凭空而来，人也很难做到完美，但弟弟和哥哥，一人占了一样，让人很难信服角色的真实性。反父权和反建制是移民议程中的两个重要话题，但在这部电影里都找不到——逆来顺受的隐忍，是华人无法摆脱的底色...吗？因此甚至还不如《九龙城寨之围城》。",
"2023|枯草": "男性知识分子作为主体的挣扎、悲剧以及对他人有意或无意的伤害、说教，在文本中体现得淋漓尽致，从可怜到可恨最后到可悲，都在文本的铺排中走向无解的黑暗；对心理的深刻剖析，一方面是为了突出他的挣扎和可悲，但另一方面也有男性视角过度之嫌，结尾之独白配上女孩笑脸，讽刺和抨击过了头就容易让某些人产生了共鸣。与此同时，大量的对话铺排也实在是原地打转式的堆砌，油腻男性和知识分子叠加的酒桌说教，让人感到拖沓。波澜不惊的镜头语言之外，仅仅剩下几个瞬间能让人获得超验体验，例如男主性爱前服用壮阳药的长镜头（有手机拍摄之感），例如最后凝视荒原的一颤。",
"2023|涉过愤怒的海": "对家庭关系、亲子关系的刻画非常惊人，几乎压过影片其他部分，结尾爆发的那一刻无疑是本年度最震撼、最后劲十足的电影结局之一。几个人物哪怕稍显刻板，但放入寓言故事的框架，暴力和疯狂都有据可循。摇摆不定的警察、形同虚设的探案、疯狂的专车司机，这难道不是又一层触目惊心的刻画维度？大海、雨水、台风、鱼，豪宅、京都、派出所，这一切都如此恰当地融入文本之中，指向暴力——血泪之后，是刺骨的绝望。",
"2023|红色天空": "“元素精灵”什么的其实不太重要，Petzold的新作从一种舒适、自然的语调中迸发出强大力量。剧作上的巧思、视听语言的精致以及角色的刻画都指向最核心的“人”——生活的复杂性与内心的汹涌混乱附加在每个人身上，似乎需要一场大火，甚至他人的生命，才能让这种脆弱和敏感转化为熊熊燃烧之后的宁静。从这样的直观感受出发，再去审视片中的诸多设定，便能为Petzold的“疯狂元素城”拍手叫好——当然也更需要影像之外的头脑风暴。",
"2023|不虚此行": "写东西的人，看这部电影都会觉得很好吧，拍摄关于写作的电影不容易，打动人更难。想说的其实很多友邻都说了，于我而言印象最深的有三点：绵密的文本——好几处剧作上的细节都让人惊叹；独具一格的story-telling——主观与客观事物的展现几乎是浑然天成；大道至简的影像气质——它可以是各种类型的电影的各种变奏，然而气质始终维持着。",
"2023|坠落的审判": "对亲密关系的剖析和展现真是令人震撼，而对深层人性的拷问则伴随着视点的转换、情节的推进不断回响，最终呈现给观众的便是在不断的怀疑与翻转之后的的反思与顿悟，余音三日不绝。如果说《西比勒》是碎片，那《坠落的审判》无疑是一块块拼图，而特里耶最擅长的，可能就是对准这些零碎的瞬间，在最后拼合的时候狠狠击中你，让人不得不佩服整个剧作结构和深层意蕴的复杂和精巧。",
"2023|安塞姆·基弗：流年之声": "太寡淡太机械了，某种层面上也沦为了奇观制造机。",
"2023|艺术学院1994": "有通过塑造群像和日常叙事来刻画时代精神的野心，但也因此而已，过量的文青烂梗烂词让人感到不适，也很难从过去推敲出任何值得咀嚼的东西，内部梗电影确实了。",
"2023|小行星城": "十佳候选了，韦斯·安德森“去中心化”的创作，似乎情节不重要了，然而文本碎片与影像精心构建的世界是如此迷人，而随后的元叙事更是精妙，对现实的指涉则进一步坚实了文本的深度。唯一值得商榷的也许是过于戏剧化的处理了，但毕竟一切都是精心设计的，甚至包括“表演”——但这部电影依旧是好看的，不是吗？",
"2023|温柔壳": "有些瞬间是无论如何雕琢都很难达到的，而《温柔壳》满是这样的瞬间。它没有用现实作为肆意发挥的舞台，反倒是一心一意地用耐心挖掘出动人的碎片。因此即使有生涩有硬伤，情感却仍然自如流动，直到最后一刻。",
"2023|芭比": "这显然不是一把鞭辟入里的尖刀，但包裹着粉红泡泡的钝刀子切在父权社会身上可是相当疼的，看看那些破防的男人们。《芭比》很大胆也很前卫，葛韦格/鲍姆巴赫找到了最恰当的创作角度，所有这些话题、矛盾最终在欢乐与冒险中迸发——一股粉色火焰！",
"2023|博很恐惧": "阿里·艾斯特说：这部电影就是要让观众体验一下做loser是什么感觉...他确实做到了。这心理恐怖的题材想起《史丹利的寓言》，第一段故事捕捉日常生活中的恐怖，行云流水。然而后面就开始各种超现实，对设定有了强依赖——其实没有这些夸张的渲染，反倒会更有感染力吧，因为更真实。与之相对的文本层面的深度表达在我看来又太混杂：关于意识与主体的混沌关系值得深究，但各种装神弄鬼的细节映射所谓现代社会、家庭关系、恋母情结等等，其实绵软无力，也与影像的力度无关，纯粹是细节的堆砌，就比如开头在制片厂商后面出现的“MW”，何必呢？",
"2023|革命之间": "也许是一段传奇经历，背后也有足够深的历史内涵，情感纽带也存在，但口述+历史影像剪辑，似乎欠缺力度，对女性的关注也欠缺。这类结合历史的私影像并不难拍，但要传递足够的力度，就不能只靠脑补。",
"2023|黑莓": "有点标准的传记片三段式，然而第二幕与第三幕之间仓促、模糊，让后半段的影像失去了应有的驱动力。摄影和剪辑不错，导演有点想法但不多。狂暴拉扯的影像很容易就把观众带进商战的残酷和速度之中。",
"2023|人海同游": "粤语、荔枝、打口碟、雨林、海洋以及潮湿的氛围——电影中这些亮眼的元素，都与近年来方兴未艾的“新南方写作”形成共振，把目光投向鲜有人涉及的岭南。穿梭于南方的风土之间，“寻”的外壳，其实是为长久的驻留做铺垫，正如那些空镜头给人带来的感受一样。然而这类书写实质上是一种政治书写——南方作为一种经济和文化的象征长期的尴尬地位，使得对这一地区的关注本身就是政治性的，拥有对中央政权自生性的反叛。因此所有这些元素最终落点走向家庭，未免会感到失望，陆港关系的探讨，也似有似无；主人公与故人相见，寻找旧时记忆，水汽氤氲的氛围之下，情节却太“实”，对人物生活化动作姿态长时间的凝视似乎失去了焦点。日记独白和雨林探险两场戏是最喜欢的段落，可惜未能延展至全片——跳脱的、超越时空限制的漫游，才是南方的底色。",
"2023|菠萝，凤梨": "鲜有的从高考移民题材切入的母女故事，而借由道德困境的一再压迫暴露出整个系统以及其中的个体面临的群体性压抑与危机。母亲不断出卖自己的底线、堕落自己的道德，只为让女儿“有书可读“；而女儿着墨不多，却在有限的空间中展示出复杂的角色心理，她到底是抗拒还是沉默着接受母亲给予的这一切呢？对于母亲亦然，她对女儿的复杂态度，是纯然的爱抑或是自我的投射？这些矛盾都指向背后的系统性危机——是外在的”巨物“让她们无法真实面对对方，以一种纠结而矛盾的情感处理眼前的危机，似乎等这一切过去，重担便会落下。然而结尾向我们展示的是这种心理机制的崩塌：她的让步，也表明她终于无法以凡人之躯，对抗这荒谬而黑暗的系统，最终只能迷失在巨浪之中。电影成本不高，而导演利用长镜头和纯熟的剧本，构建了如惊悚片一般的剧情框架，为高考移民找关系而筹钱的过程犹如绑架电影的桥段，而在不同环境之下”伪装“自己以免暴露，则让人想起无数的二战电影——犹太人要防止纳粹认出他们，而这部电影中的角色，伪装的目的又是什么呢？",
"2023|长安三万里": "肯味十足的中国动画，“天下”“国家”就没停过，文字说明一段接一段，仿佛要把宏大叙事塞到每个人的脑子里。创作者们对历史和人物的想象和加工基本处于幼儿园水平，念了无数首诗歌，但根本就不懂诗歌，也无意触碰深层内涵；各式人物轮番出场，但对个体的关心又有多少？哪怕有一丝，也迅速淹没在现代人的无趣想象之中。符号化的人物（若不是文字说明，无法分清人物）和情节配上不文不白的普通话台词，写给谁看？把大唐之种种刻画成如此模样，真是可悲又可笑。明显需要更大胆的改编和更新鲜的视角，但有“历史虚无主义”之剑悬空，一切就又回到了荒谬的样子。动画本身也不值得称道，动画水平不算高，出现特写就露怯，不管是细节水平还是物体的动态都很一般，而整体的风格更是油腻至极，尽显中式审美。",
"2023|琳达想吃鸡肉！": "剧作上其实继承的是法国当代社会题材的面貌，但落点又是非常动人的家庭故事，而更厉害的是在喜剧的框架下，还有对现实的讽刺、对某种狂热的警惕——孩子们对抗警察和Astrid那场戏尤甚。贯穿全片的歌舞，则是对这种“土办法”的又一反叛和创新。",
"2023|中国女孩": "勾勒三类不同的在外国的中国人形象，不论是完全融入、无法融入还是部分融入，最后都还是陷入迷失之中。导演对这几类群体的观察基本准确，偶有不合理之处，但整体的生活状态描绘，是老中人才能感受到的精准。影片刻画生活中的涟漪，而平静之后，也没有给出答案。礼物也许拿到了，也许没有拿到，但至少从小女孩的喜悦之中，还是能感受到当下的幸福与生活的意义。",
"2023|闭上眼睛": "竭力抓住蜡烛的最后一丝火焰，在影像碎片中唤醒尘封记忆。画面之烈度不复艾里斯当年之勇，然而老而弥坚之际，注入的却更多是细腻的深情、告别的凝视。虚构与真实，由几乎贯穿始终的对白连接，而人物似乎真的渐渐流失在时间之外了。",
"2023|零度社团": "直白肤浅的白左讽刺寓言，但察觉不到一丝一毫的幽默和机智，而是在笨拙的钻牛角尖式的情节堆砌中吐出大家都知道的道理，佐以独特的美术和配乐风格，最终沦为故弄玄虚的虚伪反思，改变不了任何东西，影像的力度近乎于零。",
"2023|临界区域": "似乎看到迪亚兹、加斯帕·诺，但这里影像的烈度并非提前预设，而是随着人物时空的转变或动或静，花样百出。呻吟和嚎叫在午夜的罪恶中萌生出反抗的诗意，主角在黑夜中游荡，模糊善与恶的临界区域，在冰冷的科技背景下与不同人短暂相逢，然后再次回到孤身一人的世界——可以是一部救赎意味和反抗特征更浓厚也更粗粝的《完美的日子》。",
"2023|深海": "陪朋友看的，一点期待都无却仍然觉得很差。听说七年磨一剑，你这磨刀石也太垃圾了吧，不可否认视觉上的绚丽带来了此前很少有过的感官体验，但除此之外就是国产动画长片的老毛病，贫瘠的文本+蹩脚的情节处理+立不起来的人物，真要掰着手指头数短评都不够写的。角色很少说人话，对白本身因为写得太烂而几乎失去作用，LSD平替的绚烂景象也只是沦为了炫技的背景板。也许红色液体这个大能指有点意思，但呈现方式又与一堆作品撞车。最后credit之前那一行黑底白字真是让人无力吐槽，这种小聪明只会把创作者自己的局限性和创作上的幼稚暴露无遗。",
"2023|不要太期待世界末日": "Radu Jude无疑是当代最具想象力、最有趣的电影导演之一，内容和形式上的种种巧思单拎出来都足够水一部长片，他却选择融为一炉，最终烹制出这一锅荒诞不经的悲观宣言。影像上博采众家之长，素材的拼贴与结合令人称奇，画外音的设计也恰到好处；文本的强度令人震撼，披着嬉笑怒骂的外衣，在掉书袋与内部梗的点缀之下，难免会让人找不到方向——但这种创作上的坚守最终换来的是坚实得无懈可击的主题：当这个世界已经被异化成了如此荒诞疯癫的样子，有谁又会去探求虚伪背后的真实呢？一张脸可以被滤镜覆盖，可以被AI换脸，也可以被绿幕遮住：最终是谁来决定这一切呢？赛博浪潮终究会席卷每个人，或许留给每个主体的生存时间只有一支短视频的时间——事已至此，期待世界末日当然是无用的，因为这是一种逃避，历史终究还会再来一次。",
"2023|狗神": "滑腻到吐，看似纯熟的类型片技法实则根本无法走入人物内心，而从根本上对人物的塑造也毫无水平，对少数群体的刻画和描绘停留在剥削层面。咱就是说，能不能不要为了所谓的表达把脑子都丢了？",
"2023|梦想情景": "讽刺和荒腔走板依旧在线，然而北欧风的平淡中透露深刻的高级喜剧在美国没有土壤，容易让影片变成轻浮糖水的《瞬息全宇宙》式喜剧（导演在尽力克制了）。",
"2023|草木人间": "大段的传销场面令人感到费解，在这个时候摄影机已经完全将个体情感抛诸脑后，因此再去谈母子关系以及后面儿子拯救母亲的情节，都显得没头没尾，情感本身就很难让人信服，何谈之后的共情？而对自然景象和南方风物的展示更像是旅游宣传片，不仅手法单一，而且只有表面，一如影片标题给人的虚浮感。我猜导演是想达到古文中“情景交融”的效果，但可惜：这样的景，根本没法让人沉浸；这样的情，也没有什么攀附的必要。",
"2023|诗": "导演和摄影机保持介入的姿态，使其与一般意义上的文献纪实类纪录片划清了界限。",
"2023|疯狂元素城": "为了“水火交融”这碟醋皮克斯包了一份诡异而索然无味的饺子，明显就是先有了设定然后再强行拗个故事。设定站不住脚，风、土元素沦为摆设不谈，如果这些元素都跟人一样生活、面对人也有的困难，那这个设定又为了什么呢？剧情的走向几乎全可以预测，而笑点又太刻意：这样的城市里怎么会有（所有元素都能随意穿过的）铁丝网呢？再说故事，所有角色都在跟着编剧的目的反复横跳，而主人公的故事显得太老套了，并且对人物的塑造、故事的结局都弥漫着恶臭：美好的未来居然是去为了水城市做玻璃，这也太黑色幽默了皮克斯。然后这还是个华裔导演拍的，只能说他的价值观真的有问题，他认为活出自己就是去给白人社会当耗材，并且感到很满意！",
"2023|无尽的边界": "揉杂现实议题的《唯一的家园》悬疑变奏，但剧作上的关键部分有点缺乏力度，影像表达上也没啥想法，也许换成拉索罗夫来拍，可看性会大增？",
"2023|邪恶不存在": "生活的自然之美，依旧是滨口龙介轻易抓住的对象，但配乐似乎喧宾夺主，部分段落也有强抻做作之感。结尾吓晕，无法融入全片搭建的知觉结构，若有寓言性，也不至于如此表达。",
"2023|公平竞争": "虽然不管是剧本、摄影还是剪辑都是非常抽象的美剧风格，但从现代职场的角度切入情侣之间的脆弱关系，还是很惊悚、很有效的。如果说现代人在逐渐变得异化、肮脏、丑恶，那么这部电影刻画得算是成功。",
"2023|枯叶": "也许是对阿基期待太高，或许又因为这个世界实在太烂，电影本身是四平八稳，无甚惊喜的；但这种稳定又非常难得，当收音机中传来俄乌战争的新闻，阿基电影中一以贯之的无产阶级属性，此刻达到前所未有的凝聚和统一；置于其中的爱情故事，也是如此淳朴动人。俄罗斯的阴霾再次笼罩在这片土地之上，而追求幸福之人所要做的，除了紧紧拥抱所爱之人，更要有壮士断腕、坚韧不拔的毅力，以此捍卫孤独的生活。",
"2024|家庭合影": "后疫情时代永远无法完成的家庭合影，在无序而机械的话语和景观中寻觅往昔的碎片。",
"2023|法拉利": "跃马的红，是鲜血的红吗？两条线（揭露法拉利赛车在上古年代的残酷本质和恩佐·法拉利复杂的人物刻画）单拎出来都很有力度，但结合在一起不知怎的就变成男性恶臭之自我反思，反倒是值得挖掘的地方被一笔带过。为戏剧冲突而不顾历史比赛结果先不谈，但全英语对白真是拧拧又巴巴啊。",
"2024|但愿人长久|祝紫嫣": "新移民的生存困境、陆港之间的关系变换，导演从私影像式的家庭故事出发极为敏锐地探讨家庭悲剧背后的社会变迁，但选取的角度太过于平淡无趣，纵然有一个三段式的剧作为框架，嵌于其中的人物却看不到多少弧光的转变，由废物吸毒爹到悔过自新爹似乎只需要时间就能改变，而主人公的社会经历和情感挣扎，在较为枯燥的影像中亦看不到变迁的缩影，看作生活流又缺乏足够的强度和真实性，还是有点可惜。",
"2023|奥勒法的女儿们": "在真实与虚构之间，迸发出惊人的情感。现实议题如此沉重，哈尼埃似乎用精致影像消解宏大的危机，转而关注细处，结尾凝视的那一击才会如此沉重。",
"2023|银河写手": "这么多抒情达意的方式，偏偏选择了最油腻最无语的那一种。那些困难的处境、人生的悲剧，电影结束了也没法让人有一丝怜悯，哪怕它们是真实的。花活玩了半天，最后潮水退去只好尴尬煽情，外加对女性角色令人反感的刻画，看完只会觉得这些影视圈（juàn）内的屁事真没啥好说的。",
"2023|哥斯拉-1.0": "尽管有着出色的灾难场景刻画以及怪兽特摄片复兴的努力，但精心包装却无法掩盖的是右翼保守，甚至让人想起军国主义的内核；女性角色的边缘化和功能化暂且不论，哪怕片中多次强调所谓的反战口号，然而最后的作战行动正是对Kamikaze的致敬和洗白，角色台词亦如是，有时前半句是普适的反战反权威，而后半句话锋一转，“我也曾为国家而战”，野心不言自明。结尾的集体军礼令人不适的程度堪比国产主旋律，而最后男主角“成功”回归家庭，最后承担痛苦的终究变成了躺在病床上的女性，简直腐朽至极。",
"2023|乘船而去": "把历史创伤的碎片轻轻揉捻，再用巧手拨弄生活的弦波，如果能不那么紧绷、更多轻松之处，或许又是一部《女人，四十》。但除去口音问题，这部电影现在的样子也令人陶醉：文本真实而厚重，人物也清晰可感——或许情节上的繁复和刻意削弱了情感表达的力度，但话语间、镜头之间富有节奏的留白，又让人感到欣慰。或许每一代人都有自己的苦与乐，但斯人乘船而去，生命之河会引导每一个人前行。",
"2023|再见，朱莉娅": "非常扎实的导演首作，反思民族的创伤过往（导演是北方阿拉伯人），女性在夹缝之间的生存无疑具有诸多解读空间，国族、种族、宗教、阶级、婚姻，这一切都指向结尾不可避免的分离：与其在谎言中维系虚假的和平，不如一刀两断？电影没有给出最终的答案，分离之后的痛楚仍然持续至今。",
"2023|GT赛车：极速狂飙": "车迷看着一本满足，拍得很真，除了几个不得不向情节妥协的bug之外是看过最真实的赛车电影。完全借鉴《一级方程式：疾速争胜》的剪辑手法，但又是一部反类型的类型片：一开始就确立自己的目的，并用一个灵巧而隐秘的三幕剧本完成最后的表达。尼尔·布洛姆坎普让这部电影变得完全不像是传统的美式运动片，那些看着不够类型化的段落反倒是跳出窠臼的巧思所在。",
"2023|伟大的缺席": "SIFF26：伟大的睡眠，哪怕第三幕的揭晓有情感强度，前面接近两个小时的铺陈可真是无聊至极，导演对影像完全缺乏掌控力。",
"2023|绿色边境": "主旋律电影，角色高呼“欧洲”的时候确实有点犯恶心。换着角度勾勒难民问题众生相，最后落点还是呼吁各国增加援助，有点难评。说是人性的揭露，不如说双方都被困在制度的牢笼之中——然而这一点根本没有提及。",
"2023|绿夜": "情节稀烂，但气氛到位，没有冰冰完全撑不起来。想起《蒙娜丽莎与血月亮》《赛博朋克2077》等作品，人物之间的碰撞大于一切。",
"2023|银河护卫队3": "看的漫威粉丝专场，全场不时欢呼雀跃，我都傻了：这么粗制滥造的小儿科电影值得这么激动吗？故事稀烂、特效瞎眼、音乐滥用，最后伪长镜头呈现的动作戏算是唯一能看的东西，其他时候就左耳进右耳出，眼睛一闭一睁，熬过两个半小时。",
"2023|小世界": "一草一木皆世界，只有真正触摸那份盎然，情感才得以存在。寻觅一丝平静，不必置身浩瀚宇宙，而是着眼于目之所及的“小世界”，这是人与人连接的唯一途径。因此当短暂的邂逅走到尽头，开阔的顿悟感宣泄而出，一切也变得寂静而温柔。",
"2023|如何做爱": "在雄性恶臭和性暴力的氛围之下，用风格化的影像刻画女孩性别意识的转变过程。想起安德莉亚·阿诺德，但无论是影像的纯度还是整体冷峻气质的把握仍显生涩，前半段好于后半段。前半段真的是阿诺德式的，仅仅用人物的动作和语言就完美铺垫情感，甚至不需要过多的补充，静之深邃寓于不断的运动之中。",
"2023|如果我能冬眠": "困在蒙古包里的小镇做题家，拍出了现象却无意继续深入。",
"2023|白日之下": "对体制的鞭笞和讨伐，构成了影片的底色。“金句”也好，“理想”也罢，都是真实存在的症结。似乎能拍出来让人看到，就有进步的可能。但似乎也有点目的先行，情节设计、人物动机都有不和谐之处。依主题需要，人物和情节似乎能肆意更改，表达也逐渐变成符号化的对立冲突，而抹掉了最深层次的原因，只剩口号；深究而言，甚至这样一个记者的形象都难以成立。整部片子很像韩国现实电影之流，片子之外的震撼力无疑大过电影本身。这是一种好的创作倾向吗？或许不是，但在此时此刻我们似乎也需要。",
"2023|熊熊燃烧": "剧情在哪里？恐怖在哪里？",
"2023|无边泳池": "Naive",
"2023|真主保佑，是个男孩": "法哈蒂收徒了？但是对女性心理和精神世界的刻画还是有可取之处的，人物面对的矛盾冲突也没有硬拗之感，倒是宗教指涉有点多余的感觉。",
"2023|金色茧房": "“文明之外”的自然主义书写这些年越来越多，而这部首作无疑技惊四座，在长镜头的运用上吸收大师精华，却又更进一步。然而形式感的堆砌始终没能让我感受到拍摄对象的内在肌理，如梦似幻的影像似乎失去焦点，在这一点上甚至形式感更强的《人类之巅3》都在松散中抓到了一丝脉络。人物对话太空洞虚浮了，潜在文本令人无法捉摸，而时有时无的人物特写又放大了这种迷惑——他的前辈塔可夫斯基、阿彼察邦从来都是形式与内容高度和谐的，顿悟之感无需过度雕饰就能传递，对于新导演而言的确是难以达到的境界。",
"2023|我是船长": "观察他们的穿着，欧洲足球俱乐部的球衣几乎贯穿始终——而这正与他们的处境相合：欧洲总是以一种矛盾的方式影响着非洲大地上的人民，过去如此，现在如此，将来亦是如此。只是在这些形形色色的球衣之下，对真实处境和内心境况的关注，又有几分？以虚假非洲的欧洲视角讲述的故事，配上各种航拍、煽情配乐，恍惚以为在看劣质好莱坞/国产片。",
"2023|珍妮特星球": "摄影很美，也有足够温暖动人的叙述方式。",
"2023|疾速追杀4": "电影院看真是享受。当代动作片标杆，电影游戏化的最佳范例。有一场室内俯视角的射击戏，不就是2D俯视角射击游戏吗？整体的编排就是为了三场大戏，而在表现力上都没让人失望。最重要的是：干净利落、爱护公物，体现了动作戏、枪战戏编排的复杂、认真程度，与之相对，《子弹列车》可荣膺“最罔顾人类财产”奖。美学风格依旧如前作，炫丽而不违和，加上坚实而简单的故事情节，差不多三个小时看下来也不觉得乏味。",
"2023|年会不能停！": "至少在“喜剧”层面它是非常成功的：具有传统讽刺喜剧的质感，而影像语言也极尽能事，持续制造压力。可惜第三幕坍塌至小人物英雄主义的闹剧，结尾甚至向体制低了头，倒也是和中式喜剧特有的主旋律一脉相承。不论如何这是一部很新的电影，用一个荒谬而粗粝的现代故事呼应了传统讽刺喜剧的肌理。",
"2023|绑架": "类型情节剧的外表，但随着历史切片的进入，就变成了一部全然的政治电影。切入点的选取让高潮部分足够动人，但《再见，长夜》里面用平克佛洛伊德的音乐侵略性地渲染紧张气氛的贝洛基奥似乎也消失了，只剩下略显铺张的豪华配乐。",
"2023|花月杀手": "原著写得很精彩，和《十二宫》有得一拼，贪婪之下催生的罪恶让人倒吸冷气；电影改编则彻底沦为白人忏悔录，原书中对印第安种族的平视与关怀也不知所终。最后10分钟是很精彩，但看到这里已经非常疲惫了，恐怖的片长反映出的是创作的重大失误。李大妈演得真是烂！看一部他主演的电影高低得申请工伤。",
"2023|尼特岛": "前半段感觉还是传统的纪录片思维，田野调查+莫名其妙的提问让人感觉太刻意，有另一个圈子硬融进来高高在上的感觉，也基本上没怎么发挥游戏影像的特点，探讨的问题也算是老生常谈。后半段融入游戏世界之后好看很多，但依然没找到一个合适的抓手去表现更大的命题，结尾也有一段狂欢，但和饱含情感的GTA哈姆雷特比起来就差得很远了，后者似乎更懂怎么拍游戏。",
"2023|拜访小屋": "从极为荒诞的设定切入，却逐渐迸发出情感表达的力度。虽然情节无力吐槽，但人与人之间真实可感的情感连结和普世价值之表达，仍是值得一看。沙马兰，都不知道该夸还是该骂！",
"2023|奇美拉": "兼收并蓄的罗尔瓦赫尔，一如既往地迷人。站在巨人的肩膀上，影像旋转变幻，古典气质浓厚；Kraftwerk的音乐不突兀，又把我们拉回现代。时间的流逝近乎无形，返乡母题之下的嬉笑怒骂，松散但不失焦，神秘却又真挚动人。或许让人不满足的，便是缺乏某种奇迹时刻，某个飞升的瞬间。",
"2023|去年夏天": "结尾很大胆，但前边又给人感觉过于收敛和顺拐，情欲的勾画也欠缺力度。",
"2023|忧郁小女孩": "用纯粹的搬演来再现母亲的生动形象，在闪回和声音之间跨越时间的女性光辉同时在两个时空闪耀，非常厉害的非虚构写作。除去部分过于违和的段落，其余都达到了内容与形式的统一，而玛丽昂·歌利亚也贡献了生涯又一精彩表演。",
"2023|命案": "命案之“命”，剥去超现实和意识之外的皮，剩下的只是世俗的碎片：混沌苍茫之中，命运让人无枝可依。后段情节上的突转较为密集强烈，观感不佳，幸而整体讲述的力度仍足够。只是，非得取无辜女子之性命吗？",
"2023|五月十二月": "好嗨，不管是故事还是人物状态都给人一种荒诞的真实感，很喜欢里面角色发疯的戏：剧作不断在进行自反。",
"2023|网络谜踪2": "缺乏新意的不断反转，有时感觉是不是编不下去了？",
"2023|怪物": "情节冲突驱动的影像，前两个视角有多难看，最后一部分小孩之间的互动就有多吸引人。似乎完全不想刻画角色所处环境的“真”，而是用一个个反转稀释可能存在的“假”。故事主题固然很动人，但是否需要置于这样的故事结构中，属实有待商榷。",
"2023|蠢货": "对T议题的展现和探讨基本停留在无趣刻板酷儿短片水平。",
"2023|拿破仑": "老雷自己都搞不清楚该塑造怎样一个拿破仑吧？结果就是情节安排和人物塑造都一团乱麻，冗长无趣。缺乏当代视角的引入而只剩下扭曲的历史，讽刺显得绵软无力，一段一段的战争叙事似无头苍蝇，只闻炮火不见批判。影像质感毫不讲究，干干净净的布景、枯燥的配乐和全员英语台词，说是劣质的迷你剧/电视电影都不为过。苹果出品，我不好说！",
"2023|夜幕将至": "批发式的无趣男性返乡叙事",
"2023|怪物少女妮莫娜": "是成人动画，不仅体现在酷儿和身份认同元素，还有极具悲剧色彩的未来政治故事：中段揭露妮莫娜之怪物往事有《哪吒》既视感，但东西方创作取向的天壤之别将母题指引到不同方向——怪物作为未来国度的假想敌被建构，它真正出现之后又将这种意识形态的牢笼击得粉碎，片中对民众恰如其分的刻画体现了这一点。酷儿元素如呼吸般自然融入，让身份认同的大命题——不仅是个体的还是集体的——得到有效的表达。全片影像节奏流畅，赛博朋克与传统建筑融合的艺术设计让人耳目一新，是2023被忽视的动画佳作之一。",
"2023|孤注一掷": "明明都是诈骗的受害者，故事的讲述却要为了电影之外的“目的”不断剥削、利用这些角色的故事，营造所谓奇观而不见丝毫怜悯。往小了说，这不人道；往大了说，这完全是一种逼迫观众接受的强权。",
"2023|被占城市": "4小时的阿姆斯特丹城市画像，是当下与历史的暧昧交融：精确到门牌号的建筑物，承载多少沦陷往事？而群情激愤的人们，是否意识到历史的幽灵持续盘旋在城市之上？麦奎因将摄影机指向不变之物，提醒观众某些事物的持续存在。选取的素材几乎涵盖方方面面，而视角的选取，从精妙的摄影和配乐中可见一斑，几处运动镜头和蒙太奇都有大师风范。作为archive，长度自然不是问题；但作为电影，4小时的城市漫游配上密度和深度都令人生畏的史料旁白，无疑削弱了议题表现的力度，也将真正值得铭记之物拦在了影像之外。",
"2023|世界的阿菊": "选择掏粪工这个题材并不只是图个新鲜和猎奇而已，一方面是日本封建时期底层人民的生存缩影，另一方面职业的特殊性使得他们穿梭于不同阶层之间，在嬉笑怒骂中蕴含着江户时代末期的社会危机——现代性的萌芽让女主角深陷阶级困境和身份认同危机，而在维护武士道的宗亲关系时“失声”，又代表着联系市民阶层失败的“失语”症候。此时的人类排泄物就变成了一种反抗手段、一种新时代的象征，它是“世界”中原处情感与认同的本真模样，一如电影平静的影像设计，呼唤自然性的美与丑、善于恶。",
"2023|老狐狸": "就连说教都是如此无聊和降智，口水话和口语风格的台词是两回事吧？人物塑造服务于情节的起承转合而写得稀烂，其中很难探测到时代的脉搏，而只能依赖服化道来脑补。",
"2023|坚毅之旅": "过于平淡的素材选取让影片整体变得枯燥，不过将观赏重心放置在导演的视角之上，也有一丝趣味。由此再看，摄影机和人物之间的位置关系就显得很突出，有时候人物偏居一隅，但身体和面部都有捕捉；有时候将客观物体置于中心，指引我们关注那些物体、画作。模糊精神障碍的界限之后，影片无疑显得清澈，可惜最后导演警示性的文字一打出来，似乎有失韵味。",
"2023|河边的错误": "很机械、做作的影像，既然根本无法提供一个情感的入口，那自然也不存在任何“解读”“隐喻”的可能。",
"2023|奥本海默": "诺兰的影像游戏——《信条》《奥本海默》皆在此列，用碎片、配乐、音效等元素的堆叠重构一段文本。因此情感被驱逐到次要地位，跟随其精心构建的，由复杂剧本驱动的视听迷宫才是最重要的事情。诺兰对奥本海默的理解与维基百科无异，只是用各种方式划线、加粗了人物的波折、事件的真相，“普罗米修斯”“殉道者”这样的词一次又一次出现，已经足够直白浅显，满足大部分观众的需要。政治惊悚片的框架下，第三幕的揭晓时刻足够震撼，然而不能忽视其他时候视听语言的重复、无聊，也不能忽视对其他角色，尤其是女性角色刻画的欠缺。是一部经典的诺兰电影。",
"2023|奥兰多：我的政治传记": "以一种纯粹酷儿影像的姿态重演《奥兰多》，形式与内容不断碰撞，最终达到鼓舞人心的和谐状态。但看着这些鲜活的个体最后都被冠以奥兰多之名，不免为这一名词所能涵盖的范围感到担心，所以某种程度上这“奥兰多”是否也是一种口号式的简化？似乎更应该强调的是对《奥兰多》的当代性重塑和解读，而这一点在影片中并不深刻。",
"2023|过往人生": "拍“过往”，氛围恰当，在美国电影里面属于耳目一新的类型；然而一见面立刻滑至俗气，除了见面时那几声“哇”非常惊艳之外，剩下就变成对什么因缘的无线纠缠，还把丈夫晾在一边。东西方文化与移民的话题常拍常新，然而都2023年了也应该进入新阶段了，即以逆全球化和意识形态的视角再次重新审视迁移的正当性——感性地对应到电影中，就是那些“凝视”的停滞时刻，比如结尾，本可以有更深刻的迸发空间。",
"2023|完美的日子": "以东京市政府的“外宣”项目为外壳，文德斯这次依旧注入了对冷静、孤独和内心深处静谧的凝视。摄影机镜头之下的东京显得极为克制，而人物的故事也在不疾不徐中缓缓展开；真正对于劳动的展现，又与高高在上的小资式虚伪拉开距离。若周围人物不那么功能性、情节再简练一些，观感会更好。",
"2023|幽灵肖像": "杰出的空间书写，尤其喜欢第一部分，现实与门多萨之虚构的结合。几处“奇幻”场面令人惊奇，恰如其分地揭露了电影的本质肌理。对创作者的启发：只要用心体验周围的世界，又怎么没有好电影可以拍呢（门多萨用手机都能拍出惊奇的影像）？",
"2023|可怜的东西": "肤浅而随意，概念交待之后便迫不及待地开始输出所谓的女性议题和性解放场面，与此同时罔顾最基本的发展逻辑和人物性格，看似大胆的影像背后，是非常保守取巧的创作思路；如果一切不合理之处都可以理解为创作者的讽刺，那么这种糖衣炮弹的迷惑性，似乎还隐藏得很好。兰斯莫斯穷尽调度之能却也是旧瓶装新酒，莫名其妙的广角、扭曲镜头除了炫技再无他用，只有最后一分钟他短暂地找回了以前的自己。",
"2023|普瑞希拉": "尽管改编剧本相当蹩脚，但影像气质很惊人。科波拉对于男性气质的“拥护”（姑且说之）其实很明显是一种创作上的取向，而不应指责为其削弱女性存在的媚男——事实上，女性角色恰恰是这部电影里最亮眼的。",
"2023|波纹": "小题大做，奇观过多",
"2023|机器人之梦": "沉淀几天之后再回味，其实两个“人物”之间的关系不算公平，对亲密关系的描绘其实也有简单化的处理，情节上也有一些硬拗之处。然而在简洁、美丽的画风之下，最为宝贵的其实是举重若轻的处理，许多细节虽小，却能带来极大的情感震撼。",
"2023|轮回": "很美但也稍显刻意，色彩斑斓的转生幻梦，在不同时空和文化中自如穿梭，文明的印迹层层叠叠，唯在冥想中感知灵魂的流动。",
"2023|火影": "起初还有残雪式的阴暗扭曲气质，然而随着情节展开影像完全垮塌，数字摄影出了屋子便失去暴戾的紧张感，最终取而代之的是过时无趣的主题表达，也是令人哑然失笑。刻画历史创伤有无数种方法，然而最终选择了最直接浅薄的那一种。",
"2023|雪豹": "比较“接地气”的剧作其实是经典现实主义文学样式的精神继承，民-官、保守-进步的对立模式，其实不新鲜。哪怕置于少数民族视域之下，囿于制度原因，也难以深入。这就是为什么，影片后半段似乎陷入原地转圈的尴尬之中，而最后警察的所作所为，也基本在意料之内。但这个故事在当下仍有积极意义，雪豹牵出的人物众生相，无形中成为当下的注脚，而几乎难解的矛盾，又与如今的种种问题何其相似。万玛才旦在这部电影中又有突破，几乎不再有干涩的段落，而是用一种更有效、更精准的方式操控影像，与此同时绝不被所谓的类型化蒙蔽双眼。有些段落，甚至初具大师风范——可惜斯人已逝，令人扼腕叹息。",
"2023|自由之声": "此片充分说明美式白人主旋律臭起来和我们的有的一拼！很恶心的电影，看了浪费时间。",
"2023|蜘蛛侠：纵横宇宙": "前半段有出乎意料的轻盈质感，情感的推进有别于漫威拍的那些超英电影，音乐强化了这一点。后半段剧情回归PG级剧情本色，外加些许俗套的“漫威Moment”，不免有些乏味。和明年上映的“超越宇宙”组成上下部，因此这一部的结尾让人意犹未尽，为了维持着悬念，总感觉有些地方故意捂着不说，不过比起第一部更炫目的画面以及不时让人眼前一亮的调度都让观感维持在高水准。大量彩蛋、梗算是锦上添花，有时也喧宾夺主。",
"2023|柔道场": "白左机械降神有点过于好笑了，事实上一个体育组织根本没有这么大的权力，而逃脱的后果也并非结尾刻画得如此美好。以体育项目切入政治事件不新鲜，这部电影贵在用黑白摄影、配乐和浅焦镜头捕捉政治漩涡中的恐怖之处，确实令人不寒而栗。期待这类电影有朝一日能对准中国的运动员。",
"2023|人间诗句": "视听太过贫瘠以至于很快就乏善可陈，近似短视频汇编了，而文本的厚度又不足够，阿巴斯电影中的一对一谈话展现出的强大道德震撼，这部则是摸不到边。能理解议题的紧要性，但拍成这样其实更像爽文，撕剧本的那一段尤其如此。",
"2023|成年人们": "人物的状态拿捏得很准确，在特定的情节设计中爆发，有如平地起惊雷。受不了的是有时突然开始尬舞尬叫，整体的影像气质也没有什么与文本产生勾连的异质性。",
"2023|你想活出怎样的人生": "那些细致入微的文本分析、符号解析只能算作锦上添花，而影片真正要义都在标题里了，令人叹服的同时也感到惋惜。于我而言印象最深刻之处无疑是结尾：这位耄耋之年的老人决绝地抛下一切，让一切肆意崩塌......这其中有对后辈的期望，但更多的或许是“回首向来萧瑟处”的超脱和旷达。倾注在人物身上的心血不曾变过，但竟罕见迸发出叛逆和绝望，更是令人惊叹。这时我们才知道，片名的问句或许也送给自己，老而弥坚的强烈情感令人动容，也让人不舍。弱设定之下情节肆意挥洒，却在一个个真实可感的碎片中散发光辉，靠真情更靠实力，对画面的把控已臻于化境，调度如春雨般润物细无声，仔细琢磨却又发现几近完美，是为有所为也。如此动人的告别却又有着美丽的结尾，也许我们能够笑着和他说再见。",
"2023|燃冬": "看似遮遮掩掩实则内涵丰富，陈哲艺延续其在特定社会背景下对个体生存状态的关照，仅仅三两笔就轻松勾勒出三个角色的生存困境。尽管角色的前史种种原因之下难以完整刻画，取而代之的是暧昧、模糊的碎片，反倒给予华语电影罕见的质感。情节安排和人物刻画上当然有生涩之处，然而比较近几年的社会现实，便能明白陈哲艺绝不满足于仅仅描绘三人之间的情感纠葛，而是试图用一丝微光照亮人们脆弱、模糊的内心角落。然而本片的大部分观众似乎既缺乏同理心又极度傲慢，“燃冬”映照出的竟是无尽的冷漠。",
"2023|凯恩舰哗变": "足够传统也足够克制，然而在最后一场戏突然崩塌——如果没有如此直白的宣言，本可以成为《圣奥梅尔》式的顿悟：批判之物始终不在场。审判之外，关于军队之权力运作的反思贯穿始终，虽已不是初次改编但第一次看仍觉震撼。也许改编的变动不大，但能如此流畅而有效地组织起超高密度的台词，仍是不小挑战，而对弗莱德金而言可能就很简单了。",
"2023|诊所": "开头还以为是聚焦缅甸诊所的社会向纪录片，两场漫长的手术过后片名展开，才发现是一部元电影，其后不论是绘画、档案记录还是搬演都强调“学医救不了缅甸人”的困境，但拍电影就可以吗？在美国政府赞助的电影节上颗粒无收，主人公落寞的身影，恰好就是后殖民主义权力压迫的个体呈现。除此之外影片较为干瘪，体量太小而探讨的话题也不够深入，但影像中流淌的在地化氛围，却又显得敏锐而迷人。",
"2023|我的罪行": "很高级的喜剧，哪怕拍法单一、模式刻板，但最终呈现的女性主义表达还是值得肯定。性别世界的颠覆，老套却有效。",
"2023|罪犯们": "剧作上是萨特思想的绝佳体现，而论导演技法，则真可谓信手拈来、兼收并蓄，最终呈现的便是如此美好、本真、人道主义的动人影像——现代制度的勾勒与嘲讽、打乱字母而构成的人物以及一点点迷影情节（影迷诱捕器？）都让整体气质更上一层楼。",
"2023|永恒的记忆": "细腻的爱情故事与历史影像几乎完美融合，谱写令人动容的民族诗篇。",
"2023|羽量级拳手": "伪纪录影像，中年拳击版《宇宙探索编辑部》，可深入的切口太少，女性角色难得地保留了自己的视角，好在形式上很极致，不会难看。",
"2023|留校联盟": "这种老派放到2024年有何深意？好看但禁不起细嚼的糖水之作，但也比coda之流好上不少。",
"2023|人类之巅3": "SIFF26：前作讲“同频”，这部在持续的寻觅中追求“共振”——然而前半部分在缺乏铺陈的情况下便开始玩弄形式，略有瘸腿阿彼察邦之感；于是音效、摄影和剪辑越来越激烈，长镜头的开始和结束都出乎意料，文本也飘得找不着北。最后居然物理意义上登上了“人类之巅”，甚至让人物直接接管了摄影机的存在；全程化平为曲的VR摄影，最后终于让人物把地球踩在脚下，就像拨弄地球仪一般。",
"2023|杀手": "芬奇的杀手不再是传统意义上“悬空”的完美杀手形象——他没有什么高科技，也不是刀枪不入、身手过人的刺客，他和我们一样干活的时候会碎碎念、听The Smiths；但这部电影又拒绝将其降格为插科打诨的不正经杀手——那将是另一个极端的不真实。芬奇的杀手选择了字面意义的道路：一种专业技术之美。然而话还是有点多了，如果是一部欧洲电影可能会少90%的台词。",
"2023|填词L": "有曲方可填词，然而从最初的意气风发到最终理想幻灭、出走台湾，为理想付出一切的根基没有了，未来也就无从谈起。哪怕已经认清现实，做着毫无关系的工作，却也不能稳定下来，现实的重压之下，所有人都似浮萍一样起起落落。《填词L》如此轻盈地用这个填词人的追梦故事反映当下香港普通人的生存处境，而最后落点又是如此崇高：在台湾，她回归土地，因为这是唯一她亲手能掌控的东西，这片土地也不会亏待她的赤诚。",
"2023|主要音调": "在超现实的脉动中寻找一段记忆，重建一个宇宙，让自己与这个世界更加贴近。“解谜”的过程拍得很迷人，同样也不缺乏会心一笑的瞬间，只是不太中意松散的剧作。",
"2023|僧侣和枪": "有关选举的很多台词简直就是“装外宾”，就好像不丹人民真的如影片所呈现的那样愚昧无知。西方式选举民主的一体两面，电影强调的是它的好处，而对于后患无穷的危害，似乎用一个刻板的美国角色和一支枪就想糊弄过去。片尾戛然而止，紧接着是对这种民主制度的歌颂，实在是令人无语，先前对于本国风土人情的刻画全都变成向西方人汇报的材料了。",
"2023|红毯先生": "人物之扁平情节之可笑偶尔会让人魂穿我国古早年代的讽刺文学作品，现在看来真是过时至极、毫无意义；视听语言偷谁的名字不想打了，而且那位也没有多好吧。",
"2023|简如西尔万": "从《世糕》《跟我走吧》到这部，强大的感染力又再次证明了都市肉体爱情喜剧的创作路径的在世性和有效性。",
"2023|老橡树酒馆": "年近鲐背，却仍在影片中积极回应当代议题，以现代视角切入，肯·洛奇无疑是一位伟大的导演。男主角内心的挣扎，或许也是导演心声的体现：他左了一辈子，但到晚年，却眼睁睁看着这个世界向右转，自己却无能为力。就是这样一位导演，在豆瓣却已经不受待见，再次说明所谓“迷影”圈似乎也已经向更保守、更脱离现实、更孤高的方向发展了。",
"2023|周处除三害": "看完后几个小时静下来想想，其实没有讲什么值得琢磨的东西。类型片层面当然是不错了，但最后借人物之口表达，一则笨拙，二则浅薄。有几个片段想到的是北野武的电影，但他电影中的虚无浪漫的质感全靠人物的深度，而缓慢纯净的镜头语言其实都来自真实感受，黄精甫肯定只摸到了皮毛，于是有些段落就显得冗长无趣。对女角色的刻画也值得商榷，至少不是值得夸奖的。",
"2023|殖民者": "用西部片的影像手法和情节走向讲了一段“反”西部片的历史，殖民者的残暴和贪婪构成了血腥的权力结构，代表着资本主义早期积累的野蛮阶段，同时也是“文明”的形成过程；随后情节戛然而止，在雍容华贵的豪宅中，他们开始清算自己的所做所为，为更隐秘的“殖民”寻找另一套话语——这又是军事独裁的前奏。而兴亡皆苦的普通人，在面对权力的压迫时最大的反抗只能是：选择不端起那只茶杯。",
"2023|超级马力欧兄弟大电影": "优点就是片长控制得很好，看这个轻松俗套的故事不会觉得拖沓。这系列的游戏向来以玩法见长，改编成电影，哪怕表现出很多游戏特性，也会失去游玩时的惊喜感。布莱恩·泰勒居然在重复自己的配乐，似乎有点缺乏创造力了。感觉老任做这部电影就是为了在Switch的生命末期再多卖几份马车8和奥德赛……",
"2023|甜蜜的东方": "对美国当代文化碎片充满热情和体贴的一次拼贴和洞察，穿梭于搬演之间的奇异之旅，无疑是对一切“主义”极具厚度的深邃反思；摄像机对准她的逃离，坚定地拒绝外部文本的剥削，最终写就一曲纯粹、失焦、永不停息的Z世代圣歌。",
"2023|法式火锅": "本真的爱情想象与人际关系超越世俗的情爱，迈向精神的永恒；陈英雄用精准的影像调度拍食物、拍烹饪、拍感官，更加深了这种生发于人类劳作之中的本真情感，平等而自然。情感背后，情节显得单薄无趣，但全身心投入之后，倒也津津有味。",
"2023|教师休息室": "用持续的剧作强度拷打道貌岸然、金玉其外的欧洲教育制度，而个体的理想主义也在汹涌的潮水之下亦无法挺立。从一开始的平静到最后大厦崩塌、情绪崩溃，女教师的形象变化何不是现代人的挣扎写照呢？如果说剧作的强度保证了影片的高效运转，那么它的视听语言则只提供了框架，几处长镜头无疑增添紧张气息如惊悚片，结尾就略显掉价。",
"2023|利益区域": "这么多年就憋出个这，太失望啦！小学生都知道的落点：我们在教室里自习的时候，老师在办公室干什么呢？如果没有音乐，格雷泽似乎就完全无法营造恐惧不安的影像。不足以支撑起长片的文本，体现的是格雷泽的影像系统面对现实题材的束手无策：哪怕是使出浑身解数，电影还是缺乏力度，非常无聊。《皮囊之下》的好，就在于其虚无缥缈的神秘逻辑，正因此才能依据最本真原始的直觉路径来呈现影像。而在《利益区域》里，这种authenticity被替换为强制路径的装置艺术展示，人物都成了机械，从A到B点运转。所以它对我们进一步理解奥斯维辛，有什么帮助？我想仅仅局限于体验令人不安的氛围之内——不幸的是，我们还成了加害者。这种颠倒似乎毫无作用......",
"2023|还有明天": "用选票送走了意大利的君主制，实现了反男权和反专制的完美统一。选择投票而非盲目出走，是因为相信正义和光明的力量，是因为这张选票是在结构性压迫之下“出走”的唯一曙光。或许结尾不能令人满意，但是她们用自己的选择至少拥抱了可能的未来，告诉年轻的她们：你们还有明天，所以请不要被今天父权制的假象所迷惑。",
"2023|如此亲密": "基特·佐哈的影像，有令人惊奇的空间感与时间感揉碎重组的体验。在民宿这个密闭空间里，冲突被成倍放大，不断叩问人物内心最阴暗的角落，对亲密关系构成持续的挑战。那场吵架戏和影史上任何一场亲密男女的争执戏份相比都不落下风，而冷静之后没有哪一方获得了宣泄，而是在一片泥泞的心智中达成了和解——这是对自我充分认识之后做出的惊人选择。而不同族裔角色的设置，又通过精心设计的对白巧妙揭示了天堑般的差异与选择，一切都指向亲密关系中最可怕的那一面。",
"2023|虎纹少女": "高概念和猎奇情节明显看出借鉴对象（兰斯莫斯、豪斯娜），然而具体落实到文本上是一塌糊涂，对校园霸凌、发育羞耻、国族认同的展现浮于表面，不去深刻反思就展开想一出是一出的奇葩情节，大部分段落都让人摸不着头脑，也不想有思考的欲望；试图用手机摄影在媒介层面取得突破，然而既不能与剧作文本相得益彰，又常常在不该出现的地方突兀出现（例如结尾）。多处东南亚雨林景观让人想起阿彼察邦，可终究只是拙劣的模仿而不得要领，只是加深西方人对东方妖魔化的刻板想象罢了。",
"2023|年少日记": "叙事上的巧思以柔和的姿态不断反转，大部分时间，绝对可信的动人情感借助出色的表演迸发出万钧的张力。但越想越觉得不悦，结尾父子和解的突兀被稀释，母亲角色的单薄和缺位则更是遗憾。动人瞬间常有，但眼泪炸弹倒也不必如此频繁。",
"2023|恶世之子": "历史的伤痕，时代的症候——开头一段新闻剪辑的蒙太奇即确定基调，其后一路向毁灭的方向狂奔，如此阴暗、恐怖，看不到希望。可惜不够决绝，结尾有些泄气，不然这将是一部属于末日的电影。",
"2023|图腾": "和那种纯堆砌的大闷片真的不一样，这部片短短90分钟，情感却一直涌动；每场戏都不随意，其中更有惊人的迸发时刻。小女孩的表演出色，我们得以深入她的内心。",
"2023|白色塑料天空": "很杂乱，很无趣，强设定的题材，科幻背景有想法，却没传达出应有的艺术效果，有点浪费！",
"2023|之女": "用一个时间跨度极大的框架，却只探讨了跨性别者最基本的生存处境问题以及家庭关系的变迁，而对波兰社会制度的巨变、共产主义旗帜下的身份认同问题则着墨不足。《两生花》的巨幅海报出现在当时的波兰本就是一次震荡，然而也只是一笔带过，波兰天主教会的旗帜飘扬，也缺乏进一步的书写。不过幸运的是，这仍然是一部聚焦于跨性别者，而非将其符号化视为剥削对象而表达的电影（反例即《艾米莉亚·佩雷斯》）。",
"2023|洋子的困惑": "塑造一个这样的母亲形象是完全有必要的，人物本身真实可感，与此同时情感很能打动人。但在表现手法上会暴露导演第一部长片的青涩：要么向内，以客观、冷静的视角重新审视角色生活的方方面面，要么向外，用充沛的情感、饱满的弧光来填充人物。在本片中影像总是在二者之间摇摆，对所书写生活之真实的展现缺乏足够的思索，而为了刻画人物，特写、配乐、空镜又用得太多，有时切不中要害。话虽如此还是值得一看的，女性的书写总是不嫌多。",
"2023|青春：春": "充满怜悯和爱的影像，王兵真是太厉害了。",
"2023|墨西哥万岁！": "荒诞搞笑之后是无尽的绝望：富人高高在上，穷人好吃懒做；家庭虚情假意，有司毫无作为。“墨西哥真可怜，它离上帝这么远，却离美国这么近”，结尾既可笑又无奈。埃斯特拉达把对墨西哥复杂的情感融于火力全开的荒诞剧作之中，比伊纳里图的私人影像更直接更易懂，拉美文艺作品中的荒诞情节、梦幻氛围、死生交替，都有丰富展示——但192分钟的片长（2023第二长）也暴露导演在剧作节奏上整体把控的不完美。",
"2024|与马克·布朗的七次散步": "比《王子》好一点吧，喜欢这个结构，前半段在一种小宇宙中初探植物世界，后半段则在“报草名”的呓语中似乎寻找着一种逝去的诗意，在回溯之中触摸真实世界的痕迹。与这种震颤瞬间不匹配的是乏味的观看体验，感觉是击中了电影手册老白男赏草嗅花的爱好。",
"2024|凤凰山下·词": "如果说《世界日出时》的虚构还存在一定的可看性，那祝新本人出镜的这部“docudrama”则成了彻头彻尾的灾难。对宋词产生了兴趣，就肆意地将自己所了解的一切（但不多）的知识堆砌于表达之上——但他并没有选择抽丝剥茧、寻找意义，而是粗暴地刻画关于词的一切。不论是对词的理解、曲调的还原、对“江”“湖”的牛角尖分析都极其粗浅表面，哪怕自己多去看一看有关的书籍，都不会有如此表现；将香港填词人与苏轼并置是一个不错的想法，但完全没有深入探讨，来来回回就是粤语歌平仄那一套（且不说采访者的知识水平完全撑不起来，最后与那位女士的探讨就极其舒适），结尾还是得靠字幕完成这层批判；祝新与母亲的搬演场景则令人不知所云，最后的私影像也匪夷所思。想一出是一出的祝新，带着自己的团队上山下地，只为完成他自己都说不清楚的东西，如果要批判的是这种浮躁、无知，那他成功了。15th BJIFF",
"2024|旅行者的需求": "可能是最欢乐的一部洪片，但也是感到形式大于意义而无所适从的一部洪片，举重若轻的处理依旧在线，但真切的情感流动却被构建的形式框架切割了。",
"2024|雪水消融的季节": "非专业带来的生涩感到最后奇迹般地转化为真挚的力量，用真实的书信与照片衡量日与夜、天与地的距离，触感真实而动人，纵然有素材拼贴累赘、文本不加雕琢的弊端，而对逝者的思念在仪式般的回溯中从容展开，最后的异国段落魂牵梦绕如《壮游》，完成了与逝者的久别重逢，又借助这种异质性表达出对附加意义的抵抗——我选择了天地，则生与死都由我自己体验和承担。",
"2024|孤寂午后": "在场内，镜头几乎只对准罗卡——挑衅、闪躲然后击伤，这种勇毅赋予了影像纯洁的气质，反之亦然；而当牛被击杀，欢呼声与目之所及的惨状迅速扭转了崇高的航向，斗牛的古典气质在此终结。在车上，他们试图强调那种单纯以逃离残酷的现场，却陷入长久的孤寂之中。在某一个特定的层面，它共享了《岛屿上的煎熬》的主题，驯化与殖民的原始冲动借由斗牛在当代得以堂而皇之地被众人分享欢呼，而身处危险中心的斗牛士，不过只是这场仪式、这个系统运转中间的必要环节而已，正如一头头死去的公牛——他祷告上帝，问自己为何能逃过一劫，然而答案却早已揭露于斗牛之中：他的独舞模糊了时间，指向跨越千年的群体本能，他一次又一次完成这一切，体验一个个煎熬而孤寂的午后。27th SIFF",
"2024|异形：夺命舰": "除去偶有梗塞的剧情，就是一部标准的密闭科幻惊悚片——虽然，这个“标准”正是来自于《异形》系列本身。音效带来的惊吓效果超过了画面本身，但在反复的铺垫之后，最终的收束足够出人意料和震撼，结束得干净利落，一如电影本身的“克制”氛围。",
"2024|从今以后": "内核进步而剧作就简陋过时，本以为要从同性权益的缺失放大到这一系列人物的困难处境（例如找工作难、买房难），进而展开社会批判，结果还是以简单的社会问题剧展开，围绕着房子的归属这个开头就揭示出无法解决的问题盘旋，反而缺少了对核心人物的进一步塑造，那些本可以展开叙述的人物弧光，都消散在对话之中了。最后以一个不太令人信服的反转使女主角放下坚持，恰好说明以社会议题为导向的电影，在剧作上的薄弱之处。",
"2024|黎明的一切": "将疾病的隐喻放置在日常生活的种种不安中反复展现，既是后311治不好的伤，也是叠加于疫情之后的生活裂隙。时间被分割成一个个碎片，就似黑夜中的繁星点点，在一个个这样的片段中，人物逐渐圆融自身，而非将疾病看作生活中异质化的存在——或许不需要他人“拯救”，只需要人与人在黑暗中产生空间性的连接，长夜尽头的微光就能被点亮。也因此，直白的“疗伤”段落和指涉目的太强的配乐，就是瑕不掩瑜的一些遗憾吧。",
"2024|一部未完成的电影": "除去真实素材，或许是一部非常平庸的疫情电影，对疫情封锁的表现形式和内容并未有很大突破，伪纪录片也没有新的视角，而更像娄烨对自己创作生涯的一次怀旧式的回顾；后半段手机录屏视角的介入逐渐取代摄影机，依旧是剧组片的框架，那些痛苦和短暂的欢乐却有过重的表演痕迹。直到真实的短视频汇编如潮水般涌来，疫情三年的苦难记忆才从每一个人心底唤醒，让人回到那一个个群情激愤的时刻。可以说这是一部反面的疫情主旋律电影，那些混剪和字幕无不体现这一点，但无论如何还是必须感谢娄烨让观众回忆起那段历史、唤醒不同的个人记忆，并用影像固定住那些逐渐被审查侵蚀的瞬间，哪怕它们仅仅只是歌唱、跳舞和悼念。",
"2024|阿诺拉": "“集大成”的肖恩·贝克，不仅将前作的嘈杂、疯狂熔炼得更精致美丽，更将一以贯之的人文关怀向广度和深度扩展。与阿诺拉内心同频的影像，随着起伏而不断跳跃，将同温层之内的人连接在一起——这是情感的共振，更是同一阶级的合力，是超越地缘政治和具体人生的结构性的美德。结尾除去这层互相取暖，更令人感到心碎，是现实的巨大力量发威之后，她回顾自身，却发现自己一无所有的悲伤。",
"2024|四月": "大概能get到这么拍的目的，在一个近乎停滞的小镇人们过着行将就木般的生活，某种权力阻碍着它的发展，严禁堕胎就成为其中一种压抑的手段，严苛的戒律成为道德束缚每一个人，压得喘不过气——结果就到此为止，女主地下堕胎的行为逐渐变成符号和奇观，围绕她和其他角色安排的一系列情节都莫名其妙，不知道何意味。本片最令人不快之处，是强化了“穷山恶水长镜头”的刻板印象以及缺乏深度的影像表达，似乎有很多导演的影子，却差了个十万八千里。",
"2024|建筑元": "屏保级电影",
"2024|在长椅上": "刚开始对话的密度和深度让我想起一位故人，结果后面真的只有对话，也逐渐变得乏味了。五个故事拼盘感觉像看了五集日剧，它们之间的联系似乎更多依赖胶片影像的空间质感，文本上的勾连则有小品之感。小巧精致还不错看的习作。",
"2024|小心肝儿": "人物塑造的链路极其粗糙，呈现方式也毫无新意，从头到尾也没能成功反“女强人”的刻板形象，把欲望的满足与事业上的飞黄腾达联系在一起无疑是低级的，那段蒙太奇令人不适。权力关系的探讨浮于表层，而对D/S元素的使用也沦为噱头，不论是外在尺度还是内在表达都无法触及其中复杂的关系。",
"2024|小小的我": "除去残障这一层设定，男主角其实是一个典型的理想主义文艺男青年形象，而影片还是给他安排了最纯正的男性凝视、莫名其妙的男女恋情，哪怕出发点是为了刻画人物七情六欲之“平常”，也显得突兀。拍残疾人，却还是忍不住将他的肢体动作奇观化，而对于其内心挣扎的真正刻画，其实落在情节之上，奇观沦为了冲奖的moment大集合。影片最好的部分是那些生活化的描绘，是剥离了剧情设定的真正生活，但抓马的转折和结尾的演讲，又让这样的真实失去了应有的力度。",
"2024|鸟": "最后的和解当然是理想化的，也是不可接受的。阿诺德无意美化，也不想用这些人的生活处境来煽情或做出政治表达，而是捕捉人性五彩斑斓的底色。这样来看，“鸟”这个意象就太直接了，甚至还出现了真的鸟人，奇观化的营造适得其反。",
"2024|黑箱日记": "从一开始就确定“我”的叙述视角，私人化写作带来具身的痛苦、折磨与PTSD，让人想起此前的女性写作先驱，虽然有搬演成分，但出自真实感受的影像表现力又超越一板一眼的纪实片段。作为一部纪录真实事件的影片或许有所不足，然而那些碎片又无比接近真实，“日记”成为记录与幽灵对抗的绝佳武器。",
"2024|狗阵": "人不如狗，人狗同命，这还用多说吗？但影片还是这么拍了出来，清理__人口在这里面成了清理流浪狗，最后更是把整个动物园都放出来，老套至极，但也似乎改变不了什么。故事的现实批判性像是十年以前的电影，奥运会从头念到尾，最后看似批判然而结局还是如此正能量；女性角色几乎没有的失败刻画倒是符合刻板印象。一种关注大奖的含金量这么低吗？",
"2024|寄了一整个春天": "剧作上的瑕疵之处难掩整体文本的先进和灵动，与疫情叙事的联动增添现实意义，而影像层面没有陷入套路之中，依旧保持着青涩的活力。",
"2024|蓝色太阳宫": "人物和外界空间几乎没有互动和联系，根本抓不住任何表达。前20分钟还勉强靠着徐海鹏的表演勾勒出真实的轮廓，之后只剩下干瘪的人物、无趣的情节和缺乏想象力的影像表达，也几乎无法感知到美国法拉盛作为时空背景的一丁点作用，沦为议题的附庸。",
"2024|熊出没·逆转时空": "是什么世道让《熊出没》都变得这么苦大仇深了？",
"2024|在溪边": "反而呢是比较无感的一部洪，敏后就这样淡淡地站在人生交叉点的水流中，拉开了时空的尺度。",
"2024|风流一代": "贾樟柯这次的野心，直接体现在片名之上，而创作上的颠覆更是与之相对应。旧素材与新故事的碰撞，带来了前所未有的真实感和历史感，尤其体现在第一部分，对“那一代人”的前史之刻画，完全跳脱出个体塑造的传统视角，用身体姿态和氛围塑造无声地传达出一代之风流。随着人物逐渐聚焦于赵涛一点，贾樟柯电影的人物序列逐渐清晰，前作的影子也慢慢浮现，哪怕有物是人非之感，却难免有自我重复之嫌。而回到疫情之下的现实，就完全暴露了贾樟柯近年来的虚浮、远离现实的平庸创作，也暴露了他对于时代变迁背后种种因素的真实态度。你可以说他关心的是个体而不着墨于宏大叙事的拉扯，但当最后赵涛随着人群起跑，哪怕有悲伤与同情的思绪，但归根结底还是乐观积极的。可是，珠海事件就发生在电影上映的那几天，这种积极在个体面对时代难以避免的创伤之下，是不值一提的，甚至是逃避性的。",
"2024|焚城": "香港主旋律现在和大陆片一样恶臭。哎，资本！",
"2024|挑战者": "是对（直）男性气质的嘲讽，也是对下面决定上面而内心无比空虚的体育生的刻画。经过拆解再组装，体育比赛的色情本质或许得以揭露，最后的决胜盘其实是开头那场性爱的永恒延续。",
"2024|米勒角的圣诞夜": "用声音和物质性的传递构造一种回忆，可能是时过境迁之后的“年味”，由一个个瞬间组成，既让人怀念又有恍然大悟之感，人物群像的把握极其精准，氛围相当迷人；只是omnes的创作似乎撞梗太多，比起同年的《高弧慢球》少了点凝聚的力量，而更多是散落一地的群像拼贴了。",
"2024|内战": "可以接受不拍大场面、不拍战争片，但空有一个设定和公路片的情节框架，不管是人物还是主题都没有落到实处，无意义的美式文戏比比皆是，都内战了怎么还放不下老美那套陈词滥调呢。想了解当下有多割裂，看这部电影会毫无收获，不如去看前两年攻占国会大厦的footage。",
"2024|秘密会议": "美剧行活的僵硬观感，无非就是找个地方对话，然后拍大全景，再换个地方继续对话......这个故事最应该突出的就是教皇选举的当代性展现，那些有损教会高端形象的世俗之物，本应该给予更多笔墨。相比之下，结尾的神级反转反而是有趣的。",
"2024|告白": "再拍这种空洞无趣的小房间惊悚片真的要报警了，情节毫无新意全在意料之中，内核老旧过时，试听语言毫无新意（《闪灵》都要致敬不止一次），不知道娱乐性在哪里。",
"2024|懒猴从不哭泣": "不知道吞下多少迪亚兹阿彼察邦杨德昌侯孝贤毕赣，才能在首作中表现出如此深邃的影像风格，穿梭于丛林的湿润与城市的遗迹之间，对巨物的凝视则直接指向某种苏联之后的叙事，大坝与胡志明雕像之下的Cu Li意味不言自明；除去后半部分老友重逢以及对历史伤痕的指涉，视角不断移动而喃喃自语，搬演痕迹太重使得很多时候都像在看木偶跳舞（舞厅戏尤甚），缺乏某种意义上的真实感，也有奇观化的趋势；猴的隐喻连同猴的实体贯穿始终，的确也显得很刻意。",
"2024|达荷美": "SIFF26：“文物回家”的书写之外，运输的过程、工人的努力、学生的辩论和最后摄影机在城镇中游荡，这一切才构成了这一后殖民议题的全景画面，比起来文物的主观视角倒显得有点画蛇添足；文物的回归绝不是仅仅只有左和右两种面向，导演不置褒贬，将辩论场面拍得入木三分，话语的交锋、眼神的凝视甚至是电台环境音，都在深化议题的内涵——可惜囿于片长，我们看不到更深刻、更震撼的影像与思考了，短小精但可能不够悍。",
"2024|女儿的女儿": "难得看到一部从视听、剧作、符号和议题都如此过时的女性电影了，然后还是官方文化机构力推的，笑死谁了呢。最搞笑的是有意无意透露的亲美倾向，咱就是说你不妨再直接一点。",
"2024|鬼才之道": "台湾再拍这种空有进步外壳而内核陈旧老套的类型电影，真的要报警了，明明要讲的是不要一味追求完美和自我内卷，结果到了阴间还得雌竞、完成KPI，这是要干什么？结尾还让角色给下一代小孩说教，能说服谁？开场有一小段模仿台湾上世纪电视节目的段落算是亮点，结果越拍越平庸，直播的阴间闹剧不如说是缺乏想象力的一顿胡编。",
"2024|死亡将至": "比行活美剧还精准冷峻的视听，搭配的却是谜语人一般的黑帮犯罪阴谋论大乱炖，但不得不说别有一番风味，既没有将犯罪降级为所谓的日常工作，也无浪漫化处理，有的只是冷漠如机器一般的犯罪动作，影像逻辑简介而高效，一切都指向那个神秘体制的运转——为了维持秩序，死亡必须如影随形。27th SIFF",
"2024|纳米比亚的沙漠": "SIFF26：别的电影可能还想在混乱中寻求一丝慰藉，但在这部电影里善恶渲染的绝望与悲伤是相当纯粹的。融入真实情感体验的独特女性影响，哪怕后半部分有大量“动作戏”，整体依旧相当平和，或许也是一种生死看淡的生活态度：当只能从纳米比亚沙漠的大象身上寻求一丝宁静的时候，又何必再高看这世俗之境一眼？",
"2024|性梦爱三部曲：梦": "比《性》更动人细腻，文本的细致肌理让人惊叹，不止对相思本身而且还有对如何处理情感的探讨、代际沟通的尝试，北欧人对精神世界的挖掘已经进入另一个level；旁白的真实意味在结尾得以揭露，又让人感到意犹未尽，时间的尺度被情感流动的波浪压缩，绵延不绝。27th SIFF",
"2024|沙丘2": "没有赞达亚这条线就真的变成精致的主题乐园cosplay了，虽然维伦牛蛙对画面的敏感度一如既往，但连在一起令人疲劳——你景别大、你音响震、你清高？",
"2024|死亡乐章": "SIFF26：父母皆祸害，子女也缺德，这一家子的故事实在是惊悚而真实，对冷漠的猎奇其实才反映了人间的常态。三小时篇幅过长，虽然剧作很精彩，但缺乏一个精巧的结构把它们搭在一起，叙述时间也有迷糊之处。",
"2024|吞噬暗夜": "苦命鸳鸯逃不出的小镇，在短暂的幸福之后便是持久的分离和痛楚，起初还觉得这样的剪辑碎片化，但却在不知不觉间也沉溺于影像的跃动中，有那么几个瞬间是真的能让人感到那种细腻而脆弱的情感流动。然而很快这种观感就被粗糙的犯罪片情节所切断，情节没有堆砌却越来越极端，为最后游戏关服的哀悼瞬间不断铺垫，但效果也欠佳。游戏作为重要元素用得比较差，依旧还是“映射”现实的思路，最后人物直接在游戏中呼喊，等于将这个媒介的特性又舍弃了，另外游戏如果关服也不可能突然弹出通知，深度玩家也不可能只玩游戏，线下更深层次的交流或许才是这一媒介能延续、渗透进玩家精神世界和日常生活的关键所在。",
"2024|高弧慢球": "刻画美国小镇难以言说的集体情感之杰作，或许可以将《高弧慢球》添入其中。但不同于奇观化、风俗化的展示，卡森·伦德在这里仅仅只是描绘了最普通、最平常的棒球赛情景，而最后一场球赛赋予集体的复杂情感，也几乎从未在言语和影像中直接呈现。有人离开而有人加入，时间在运动中流逝，又在广播和记分牌中停滞；最终这场对抗成为了维系小镇集体记忆的仪式，他们点亮自己的车灯，将这份记忆闪耀于黑暗之中。这样的表达和主题弥足珍贵，而跨越政治光谱、代际差异和性别立场的关怀，又立于众人之上。15th BJIFF",
"2024|艾米莉亚·佩雷斯": "投机分子与欧洲右翼一拍即合，炮制出这部名左实右的年度最大粪作。墨西哥是腐败的温床、罪恶的符号，简单粗暴拿来就用，丝毫不顾及真实性和在地性；跨性别成为空洞的议题，也是求而不得的赎罪券，但对于跨性别者的生存处境和困难0人在意，直到完全淹没于犯罪片的类型之中；歌舞段落突兀而嘈杂，完全为喊口号而服务，不仅是对女性和少数群体生存困难的美化，也是一种毫无意义的宣泄，本质上依旧是老白男固步自封、自我意淫包装出的“进步”产物。这部电影能从年初到年末一路横扫，恰恰是全球向右转的绝佳体现——《里根传》那样的电影当然不会重登舞台，但《艾米莉亚·佩雷斯》这样充满算计的作品，却能收获一波又一波的赞誉。",
"2024|艾曼纽": "有刻意为之的猎奇东方视角和语言迷雾，影片呈现的也正如其尴尬的情节一样，关于后资本主义语境之下的个体的存在危机。这种危机通过高档而空洞的酒店奇观传递出来，而最终落在对身体、对性爱的争夺之上。酒店质量检测这一职业本身就具有十足的异质性、奇观性，角色的空洞本身就是一种隐喻。然而影片本身的质感又是廉价的，对白之诡异、情节之不可预测和表达上的力不从心，都让人无法真正进入，但又想看看这朵奇葩到底能长成什么样子。",
"2024|破墓": "前面感觉调门儿起得特高，本以为能用惊悚片的框架串连起这个民族的过往和未来，结果全靠设定硬撑，北韩、日本、美国轮番上场，就差老中了，未免有点低级了。一开始破墓的华丽场面印象深刻，但到了最后就变成纯粹的奇观堆砌斩妖除魔，而缺少内部文本支撑了，后半段的商业类型转向也略显弱智。",
"2024|猫猫的奇幻漂流": "拟人化处理不是很喜欢，但最后还是适当地和人类划清了界限。导演对冒险场景的处理非常棒，开头的长“镜头”以为是又一部《1917》，要是能坚持下去就更厉害了。",
"2024|外语": "政治撕裂的大背景下，哪怕是家庭聚会也要查户口、划成分，同温层之外的沟通越来越狭窄，谎言与躯体化的创伤成为当代症候——语言与身份捆绑，每个人都掌握一门不愿说出口的“外语”，因此当无关政治与社会的情感冲动开始萌芽，小世界的温存，或许比以往更难以维系。Fanny和Lena在漩涡中跌跌撞撞，本应以青涩的赤诚燃起情感之火，却最终让位于狗血剧情的突转和符号化的人物处理，略显遗憾。",
"2024|我们在河畔希望被鱼怪吃掉": "First系批发的电影学院学生和小留啃老不上班的元电影吃喝玩乐乱搞男女关系矫情巨婴vlog，对现实世界几乎为零的关注和体察，但是自己身上那点破事除了你们文青影迷真的无人在意，更何况拍得也毫无灵气，对话人物和情节都非常僵硬，美学风格则复制粘贴《你的鸟儿会唱歌》，也是演都不演了。以后这种电影直接打电影学院巨婴标签就好，方便避雷。",
"2024|凝视者": "小空间内做到了一定的紧张感和悬疑气氛，只是这个虚空索敌的剧作有时候真的显得很滑稽。",
"2024|猫妖小杏": "SIFF26：某种程度上是反宫崎骏的奇幻书写，“地狱”有前台有电梯，甚至还有阶级成分和专制统治的氛围，戳穿了往生幸福的谎言；但是最后母亲还是离开了人间，即使被妖魔鬼怪追杀都还是要回去，这是何等的惊悚和悲壮。但全片卖萌的场面还是太多，拖慢了整体的叙事节奏，好在有一些黑色幽默的闲笔，为奇幻故事增添了不少现实性。",
"2024|侠盗猎车哈姆雷特": "英式幽默包裹着苦涩的沉思，而虚拟人物在一隅站立，在疫情背景下竟也呈现出独特的诗意。或许配乐的介入偶有多余之嫌，但眼看着他们一点一滴地在线上完成这场戏剧，也会不由自主为之激动，个体的连接迸发出的巨大能量，似乎在最后的“杀戮”中达到顶峰；游戏本身的暴力元素与戏剧文本产生奇异的连接，而对准NPC生活和都市风光的空镜头，又使得游戏文本、戏剧文本和现实世界产生了无穷无尽的关联，市民那些机械的台词也成为了世界的一部分，在这一刻虚拟与现实的界限模糊、消解，用以对抗现实的荒谬和痛楚。15th BJIFF",
"2024|壮游": "用当代东亚的不同景观搭配百年前的殖民地文本，在新世界的个体闪光中捕捉历史的幽灵——这样的古今交响并不新鲜，而戈麦斯的独到之处在于赋予当代景观的古典意义，并在语言的喧哗、叙事的驳杂之中寻找到欧洲主义在这片土地上瓦解的那一根稻草。但他终究是欧洲人，后半段的视角难脱奇观化的凝视之嫌，而在具体空间中对人物生存状态的具体刻画，也不如阿彼察邦的电影深刻而震撼，最终留在脑海中的超验影像并不多，对于这样的文本而言并非出色表现。",
"2024|圆满结局": "他们被塑造得无知而幼稚，而当变革的潮水汹涌袭来，无论逃避或是介入，最终都凝结为巨大的无力感。导演把近未来的日本社会刻画成一个人人键政的监控社会，但人们的生活方式却处于由自由向威权的过渡阶段，也因此年轻人的反抗有一种复古的未来感，换句话说这种集体意识和情感结构，在历史上曾无数次地发生过。但依赖于本就是工业产品的电子音乐作为反抗的武器，结合主角从头到尾一直戴着的耳机，反倒成为了一种讽刺。所以最终的分道扬镳，或许也只是导演一厢情愿的书写而已，现实中这样完满的离别，也许已经在政治话语的侵蚀之下消散殆尽了吧。",
"2024|爱与输": "很灵动自如的创作，这是真正不带价值判断去展示现实生活随机性和偶发情感的电影，虽然仍处于漫游电影的框架之下，但几乎能从头到尾保持住运动的张力，点缀其间的法式幽默，则比同类电影苦大仇深/居高临下的剧作要好看得多。整体的影像风格很塑料，却也不同于vlog式的生活录像，总能精准捕捉到瞬时的情绪和时空氛围，非常喜欢。",
"2024|好东西": "哪怕偶有段子堆砌、视听单一的感觉，但整体依旧是绝无仅有、扎根于本土的女性创作。所有的妙语连珠、情感流露都无比细腻、准确、落到实处，若有似无的情节，旋转缠绕着产生了迷人的节奏流动。后疫情时代的上海书写，则是这部生活电影的阴沉底色——新闻记者的理想破灭、残存的街道记忆和抵抗话语的尝试，都从影像中生长出来，时刻提醒时间的在场。所有这些碎片在最后汇聚的不是一种逃离现实的小资情调，而是用真正的人性将苦难化为蕴藉和动力。冲破黑暗可能还需要相当长的时间，需要无数人的努力，但贯穿影片始终的女性视野，必定是抵抗侵蚀、追求美好的不可或缺的力量。对此视而不见，何尝不是一种逃避和懦弱呢？",
"2024|姥姥的外孙": "避重就轻，用眼泪来掩盖真正的问题。",
"2024|雄狮少年2": "比第一部更具现实主义的深度，也更当代性，对当代中国舆论场的描绘胜过大多数真人电影，第二幕结束的巨大悲剧力量也让人动容；但这又是一部略显隔靴搔痒的理想化电影，“逆天改命”却寄希望于权贵自编自导自演的比赛、大老板的投资，或许是一种高级黑。动画形式的现实题材就像面和水的关系，现实的因素占据上风之后，也削弱了大部分时候动画作为特殊形式的表达力量，它不像《蜘蛛侠：平行宇宙》系列一样使用夸张的特效和漫画式的点缀来时刻宣布动画的在场，而是尽全力拟真——这个创作方向确实有待商榷。",
"2024|我仍在此": "国家机器一步步侵蚀私人生活的过程，在宏大的历史跨度中缓慢呈现，影像介质的变化也体现了变迁的印记；相比之下个体的刻画就略显扁平，情感的厚度在家庭生活的刻画之中建立得不够稳固，靠外界的重压才一步步将这种情感推向高潮，母亲的人生选择也缺乏足够的塑造，就感到意犹未尽。结尾飞速跨越三个时空，似乎有些拖沓，可能只是为了促成女主母亲的出镜吧。",
"2024|保持沉默的朱莉": "毫无力度的影像，是那种可以批量生产的欧洲电影节八股片。",
"2024|善良的种类": "只有少数的超现实时刻能看出对美国中产生活的讽刺和戏谑，或许也抓到了美国日常生活空间景观的诡异感，然而对所谓的“善意”之虚伪与道德崩塌的批判，建立在硬拗的反转、令人不适的奇观化受虐场面和空洞的工具人物之上，充斥着自以为是的精明与高高在上的剥削感；但或许这样的“洞察”恰恰是自我安慰的借口，不然无法解释这位导演为什么在西方世界如此受宠。他充其量只是一位平庸的微型小说创作者，靠耸动的情节和大尺度场面吸引眼球。",
"2024|厨房": "观感奇特的电影，一方面那段厨房“歌舞”长镜头非常惊艳，前半段几次都看到王家卫的影子，另一方面剧作上的随意、某些段落的冗长和突兀的影像设计又限制了它的高度。最大的问题是人物都成了工具人，以至于多人街巷交谈的段落完全变成了文本的堆砌，而镜头语言此时又贫瘠起来。最终表达的主题，确实很适合在大陆上映。",
"2024|出走的决心": "对于除了主角之外的角色基本都有刻板印象之嫌，但从主题表达上来说，甚至又显得不够，评论区的“本色出演”更是令人觉得影片的刻画还离现实中的暴力和压迫有距离；与此同时影片却并没有回避现实，疫情的指涉、时代背景的描摹以及生活气息浓厚的细节都提醒观众故事的现实性和迫切性。导演呈现的影像视角大多克制而平静，而出走之后的蒙太奇段落美丽而自由——这是女性之间互相劝慰、鼓励和帮助的动人影像。",
"2024|我生活的两个世界": "时间跨度有点大，但依旧有动人的瞬间、精致的细节；听障人士的community，亦有体现，这是区别于先前听障题材写作的最大特点。",
"2024|蓦然回首": "“元漫画”似乎就能天然地消解剧作中的不合理之处，所谓“燃漫”，真正本质即是用热烈的情感宣泄掩盖其现实质地的贫瘠；然而本片不是一部纯正的热血番，而是在人为搭建的困境之中，完成情感的“救赎”——表面上看，藤野和京本在短暂的相逢后便永远分开了，藤野怀抱着这种悲伤，化为动力，继续进行漫画创作；但不难发现的是，京本这一角色的情感刻画几乎是缺失的，其存在似乎只是为了完成藤野人物弧光的描绘，因此这个角色从始至终都只有一副呆傻的面庞，被藤野牵着走；离别固然令人伤感，但更使人揪心的，难道不是这一角色的悲剧命运吗？若试图深究京本这一角色究竟为何如此，很遗憾本片亦无交代，心理、家庭、社会，三者的缺失最终只为空洞的角色设定服务。藤野这一角色相对有厚度，但哪怕在“日漫跑”的催化之下，性格的转变也相当生硬，而最终达成的“救赎”，更像是早就画好的靶子，在一系列不合理和无法共情的情节之后，终于使得角色走向“圆满”——另一种形式的空洞。",
"2024|我谈的那场恋爱": "对被骗群体的刻画是带有同情和真心的，完全没有《孤注一掷》式的剥削目的；女主角从精明的试探到恋爱脑的全身投入，使整部电影又有着童话般的不真实。而对行骗一方的刻画始终不忘其邪恶本质，但在诈骗集团内部，也有超越日常想象的“秩序”存在。女主角的“自愿”受骗，折射出爱情的广域之下难以发声的群体，强势的外表之下是更加脆弱的一面；但如果要用行骗男主角的“救赎”来反映这一切，又在一定程度上破坏了女性叙事的力度。",
"2024|会见波尔布特": "微缩模型消解了极权暴力的剥削性，让影像始终与人物和历史处于平视之中；剧作由回忆录改编，冲突较少，细节亦着墨不多，立场神秘游移而最终难逃厄运的中年男性学者无疑是（东方）马克思主义在西方的具体体现，而这一人物所体现历史之“玩笑”，影片并未深入探讨，是为遗憾所在。潘礼德多拍纪录片，此部剧情片作品融入历史纪实影像，既出于成本考量，又为影片增加了丰富的外部视角和现实肌理，而将真实素材直接投射于人物背后则比《壮游》的搬演更进一步，以极度的陌生化手法展现了女记者所见所闻的荒谬与残酷。",
"2024|大都会|弗朗西斯·福特·科波拉": "可能只有如科波拉这种狂妄的电影皇帝才能拍出这种惊天地泣鬼神的史诗之作，从影像上可以瞥见一丝疯狂，然而剩下的全是老年人行将就木跟不上时代还要指点江山的无奈感，很恐怖的电影。",
"2024|蜗牛回忆录": "如果拍成真人电影，也许就会被某个平庸的导演赋予阴湿负面的气质，但做成动画，效果就完全不同。在亚当·艾略特这里美好的事物可以是黑暗的，邪恶的事物也可以有一副美好的面容。动画展现了那些或许无法被所有人接受的、独属于个人的印记，不为世俗所容的古怪和癖好恰恰是个体得以存在的精神支柱，这是导演大力讴歌的重点所在。澳洲广袤的沙漠为亲情分离的悲剧增添了一丝空间上的荒芜之感，而最后二十分钟突转的美好结局，又似阳光普照般的不真实。",
"2024|宽恕": "图卢兹魅魔其实是小镇集体意识的投射，欲望的万花筒与过去的阴影交织在一起，如秋日树林一般表面平静却暗流涌动，吉罗迪将个体与外部世界的这种“投射”具象于影像之中，你可以看到不同的人物的状态，而男主又是如何应对这一切的——情节跳脱但从始至终保持悬念和张力，在陷入死胡同的时刻甚至还很好笑，此即荒谬中的真实，警察半夜贴脸开大都在这里达成了某种和谐。",
"2024|白衣苍狗": "缺乏灵性的影像，纯粹是在拉长每个镜头的时间。但你又不是拉夫·迪亚兹，那些延长了的时间都沦为一个定点之后毫无意义的尾巴。内容无甚新意，可以说是对岸的主旋律。",
"2024|虎毒不": "真实得有点可怕，几乎是调查般地将香港普通母亲的压力、连同社会问题一并铺陈，达不到尖锐批判的层面，然而就是这样的展现，也一定会有人嫌太过头。印象最深的反倒是女主角和其他女性互动的场景，分享母职的压力、交换痛苦，这种连接虽暂时让人感到欣慰，随后却充满逃不出此时此地的悲凉。",
"2024|胡阿姨的花园": "起初是标准的人物传记片样式，但随着时间的流逝和外部力量的侵蚀，影像便开始不断绵延，在敏锐捕捉到外部环境巨变的同时，人物本身的坚忍亦不断在影像中生根发芽，血与肉都清晰可感。跨越近十年的素材最终并非想歌颂这种苦行僧般的生活，而是以平等的、对话的姿态记录那些日常而不为人知的瞬间，胡阿姨戴着圣诞帽在夜色中拾荒、母子二人的复杂关系，这些片段传递的复杂情感绝非虚构影像可比；关于重庆的纪实影像令人惊叹，江城在十年间飞速发展，那些杂乱的、无序的市井气息被整齐划一的城市规划所取代，然而人们过得更好了吗？导演用一整部电影给出了他的答案，我想这是令人信服的。",
"2024|我最喜欢的蛋糕": "舒缓的镜头语言、对白间的停顿都指向故事与人物情感的真实；但是在一个真实得不到自由抒发的土地上，这种纯粹也变成了罪恶。或许是有些许对旧王朝的招魂，但谁好谁坏，人们心中自有一杆秤，在人与人最真诚的交流之中，共识就能得到确立。",
"2024|我的阳光": "前半段有种《不散》的暧昧氛围，在溜冰场的单一空间中达到情感的释放，似乎那里就是所有美好回忆的栖身之所，而身体的运动又为这种纯粹增添肉身可感的进入途径；而随着情节与影像的关系调转，这种纯粹的魅力似乎逐渐消失了，没让男孩说出想说的话，已是仅存的克制。",
"2024|唯一的家园": "虽有搬演的成分，但真实影像的颗粒带来的强大震撼，给予这层现实更深的震撼。几乎是放下立场和国族的纯粹记录，那些冲突和暴力场面，就是战争之痛对基层个体的最直接体现，也是呼吁停火、捍卫人道主义的最迫切、最诚实的纪录。从房子到山洞，最终被驱逐出唯一的家园，他们被迫离开，但土地会记住一切的罪恶。",
"2024|噢，加拿大": "无意向后延展什么，也不打算给出总结性的陈述，只是淡淡地拍摄了老白男说梦话的过程。文本的张力肉眼可见，然而堆积对白却很难承载这些内涵，虽然有意创造复杂的影像组织，却难以复制前作中乖戾、悲悯的气质。PS：但其实比当年主竞赛某几部都好看，这是可以说的吗。",
"2024|人行道乐队": "海量素材和媒介形式的docufiction最后很难不变成失去焦点的大杂烩，但对于这样一支神经质的乐队来说，反倒达成了某种和谐，可以感受到乐队短暂重组的情感凝聚的力量，以及转瞬即逝的欢愉之后，一切落幕的平静。",
"2024|佩佩": "SIFF26：阿里亚斯和前作一样疯狂炫技，但这部有了一个相对有所指涉的文本，可看性也上了一个台阶。三种配音的河马佩佩，牵扯出殖民、独裁与动物保护的话题。影像焦点不断游移，但始终不忘河马的存在，就像在水中的浮浮沉沉，也像天空中的滚滚阴云。河马被杀，但河马背后的黑暗却不会消逝。",
"2024|临时劫案": "一开始还能看到表达上的些许追求，中段以后就开始乱来了。有银河式的情节设定，但核心之单薄禁不起推敲，娱乐性占了上风。影片的技术层面略显粗糙，几处声音处理都有重大失误，确实是草台班子。",
"2024|桑托什": "触及的印度社会问题和女性生存危机无疑触目惊心，女性警队的成立非但没能解决生存问题，反倒让身处其中的女性不断被异化；女主角和女警长之间不同的选择反映了现实的复杂与无奈——女警长甚至是种姓制度和不公正执法的帮凶，但当铁拳介入调查时，她又替主角扛下了惩罚措施。一命换一命真的能带来震慑吗？在男人们歌舞升平的定格中，我们却看不到这种希望，反而是毛骨悚然的真相令人倒吸一口凉气，也因此成为了主角离开职位前往大都市的最终动因。以上种种最终却包裹在一个不着地的西方化叙事框架之中，视听语言也基本与文本脱节，让人感到这电影依旧是外来视角的审视，非常遗憾。",
"2024|性梦爱三部曲：性": "一开始就探讨的困境事实上并不值得大篇幅讨论，而与人共享之后绵延的情感与事件才是真正的“北欧”风格——能平静和理性地探讨性、道德底线与亲密关系，但又从不将感受外化。于是大量的城市景观空镜头就成为了短暂的休憩、情感的出口，但很快又回到有序的无趣之中，就连生活中的波折和涟漪，都似投入湖中的小石子，轻轻扰动却很快无声无息。",
"2024|锔瓷": "固定长镜头，冷峻地目睹了这个家庭从摇摇欲坠到碎落一地的全过程。家庭成员之间看似正常的对话、动作，在一次次的刺痛之后，终于在饭桌上显露出阴暗的底色——疫情带来的封控，撕开了丑陋矛盾的最后遮羞布；除了视觉，还有听觉，电视背景音贯穿始终，粉饰太平的话语、歌功颂德的吹捧，无疑揭露了黑暗的又一层根源，而它又与最后的结局形成互文：锔钉无法维系虚假的稳定，“大白”也打碎了内心仅存的一点幻想。如果说在那个压抑的时代还有什么能做的，恐怕也只能像孩子一样，用手将破碎的生活捡起来。",
"2024|酱园弄：悬案": "搞笑电影",
"2024|苏莱曼的故事": "有后期达内不具备的影像力度但同时也避免情节剧的倾向，从而跳出社会问题剧的底层叙事，专注于动作本身与系统性压迫在日常中的印记。摄影、剪辑和主角的表演相得益彰也点到为止，拒绝了某种高高在上的姿态，事实上确立了一种调和而足够锋利的创作倾向。",
"2024|默视录": "拍出了窥视这一行为在特定时空中的张力（如新加坡的拥挤住宅、网络直播与现实的对应），然而表层的结构是家庭片肥皂剧的枯燥情节，对监控社会的反思与批判又几乎停留在原始时代，割裂的影像组织让人难以聚焦，于是只能用一些鬼畜的奇观和设定拖着这个千疮百孔的故事往前走。",
"2024|日落日出": "日式主旋律的欢乐变奏，用剧作的障眼法展开311、疫情、城乡差异等议题，但由于蕴含的情感不够坚定，使得谜底揭晓之后并未有意料中的震撼，探讨也是浅浅带过，流于爱情故事之上；本以为女性的选择会更为独立和自强，但不断的男性凝视和结局似乎又抹杀了这种进步可能。若是当作一部喜剧，倒是有足够的笑料。15th BJIFF",
"2024|永远超级幸福": "长于局部氛围与感伤的捕捉，整体则拼接感太重，没有新东西，但也不至于令人生厌。前30分钟的处理恍惚在看另一部电影...",
"2024|飞黄腾达": "“黑化”前的川普可以说是有血有肉的，可以看到他的谨小慎微、精明能干，甚至是面对家庭与事业的关系时的脆弱。然而当他的事业“飞黄腾达”，对他的刻画又流入俗套的厚黑学叙事，毫无新意的同时也抹去了人物的个性特征。作为一部川黑电影，他并没有更为新颖的观点、新鲜的批判，只是在既定的靶子之上，勾画了一圈又一圈的重点而已。",
"2024|宇航员恋人": "依旧是糖水版的视听技法配上两个小时的聊骚，这次聊天的题材更酷儿也更真实了，当然有尴尬到抠脚的台词，但大部分时候都能让人沉浸在流动的情愫中。",
"2024|粗野派": "华美的影像包装一个非常俗套且失真的犹太故事。开头段落很漂亮，在失焦的叙事中展现主人公刚踏上土地的生活，是日常化书写的变奏，然而被土豪收编之后故事迅速变得坍缩无力，直到结尾的软广双年展段落，彻底失去表达的锋利。幸亏，影像的强度贯穿始终，对人物状态的描摹结合多处蒙太奇和画面叠加，使影片没有落入奥八股的窠臼。",
"2024|你的颜色": "各种元素大杂糅，结果一个都抓不住，原来不是我看不懂而是根本就没写好，东一榔头西一棒槌的拧巴观感，本以为宗教学校设定有进一步探讨，最后差点没变成传教片，也是神了。内容与标题完全搭不上，偶尔闪出一两条颜色提醒标题，与人物形象和情感变迁完全扯不上关系，最后以典中典之日影吼收场，感觉已经编不下去了。卡在生活化与中二向之间的尴尬作品。",
"2024|恶魔之浴": "电影节特供命题作文，用夸张但死板的奇观化视听语言和遮遮掩掩的文本来讲述本应值得正确对待的苦难，结尾真·人血馒头拍出来却毫无实感，随后的文字令这种虚浮感进一步加深，也说明前两小时的影像几乎是无效的。当女性困境仍然需要以如此剥削、不适的方法展现，这或许不是一种真实，而是提线木偶般的笨拙。",
"2024|编辑部的故事": "过于松散随意的讽刺小品，也算是把所有人都黑了一遍，喜剧效果不错——战争阴霾下的苦中作乐以及历史轮回的无能为力。",
"2024|帝国": "查询腹黑杜蒙精神状态",
"2024|拿针的女孩": "少来点这种影展做题家电影对大家都好。感觉和《酱园弄》没有什么区别。",
"2024|玻璃工人": "画风上能看出受吉卜力影响极大，而剧情也以反战视角下的成长故事为主线，但不论是人物弧光的转变还是情感呈现的方式都较为死板，最后的断肢救赎让人不解；以玻璃为题，但似乎只作为背景，与主题之间尚有距离。",
"2024|椰子树的高度": "几乎看不出那些商业大片痕迹的一部首作，摄影技法极其精准而变化无穷，在有限的时空内很好把握住人物的状态，观感上已强过近年来大部分的新导演首作。导演也承认创作上没有很大的企图，更像是走一步算一步的顺其自然，剧作上的留白和断裂比想象中要多，对应在影像层面就是只有感觉，而缺乏连贯的组织思路。喜欢那些极具疏离感、漫无目的的段落，而许多符号的表达或许可以再进一步打磨。",
"2024|破·地狱": "后运动、后疫情时代的香港，毫无疑问需要新的生死观来看待这个逐渐破碎的世界。电影把目光直接聚焦到“死”的仪式之上，但核心依旧是对“生”的重新审视，对日渐疏离的人际关系的重新连接，这是电影的时代价值所在。而由大至小逐渐转向单一的家庭故事，却未能“破”传统的观念。女性角色的尴尬处境不是一场破地狱就能解决的，她们所遭受的苦难，也不是一封遗书可以掩盖的。黄子华的角色就像一位信使，勾连着普通人生存的世界和掌握话语的“长者”的世界，而最终的胜利是后者的胜利，“破”的旧观念，并未改变压迫的本质。整部电影就是在利用这种“破”为现存秩序的维持继续提供合法性，直到最后还要设计“前辈”因女性破地狱而愤然离席的情节。女性是可以上桌了，但是她们的处境真的改变了吗？创作者选择让女性角色失语，自己的态度也昭然若揭：破也是我们自己破，和你们没关系。",
"2024|紧急出口": "又名布加勒斯特的那一夜，人人都知道那一天会来，但真到了风暴前一晚，最普通的人们也只是坚持着一直在做的事情，火种从未熄灭，因此一颗鞭炮就能见证爆炸式的垮塌。导演的首作捕捉到那些平常又不平常的瞬间，没有神化某一类政治叙事，同时从始至终坚定着立场，注入肉眼可见的对于普通人的敬意。",
"2024|分手派对": "把电影的虚构变为真实的可能，派对的意义在日常的碎片和情感的流淌中缓缓揭示，因此结局似乎已经不再重要，它更像是一个标记或是一个起点，展开未来的无限可能，这种反高潮的创作恰恰是最自然、最高明的。",
"2024|隔壁房间": "对房间的两次凝视最为动人，第一次或是一种试探，焦灼不安之后回到现实，二人的关系进入超越现实的交流阶段；而最终的凝视除了带来解脱，更代表着继续前行的曙光——当人们不再能够用身体接触安抚心灵，当地球不断恶化，当肉体上的痛苦夹杂着过往的回忆敲击着当下脆弱的个体，那扇永远敞开的门就代表着一种希望和寄托，因为我们早已直面死亡，从而抵御虚无和分裂的到来；我们所爱之人，则正如结尾那样，以一种超越生死的方式永远存在于我们身边。",
"2024|叛影浪客": "打到后面都有点厌倦了，无限拉高阈值的结果就是最后一战又疲惫又乏味。视听语言受John Wick系列影响，但亦有本土特色，而剧情基本无法深究，但片子的女性角色，在欧美的电影中又找不到原型，观感非常奇特。",
"2024|裹尸布": "柯南伯格晚期佳作，好过《未来罪行》《大都会》，借助赛博朋克式的阴谋设定，展现对于科技社会的深刻洞察和恐惧，以及更重要的，如何在令人不安的社会演进中安放自己的位置。后半段并未如想象中有宏大的展开，却饱含对于逝去之人和腐烂之物的沉思，平静的影像之后是令人毛骨悚然的崩裂，是一种完整性被剥夺的具身的疼痛和恐惧——如慢性病一般侵蚀，直至这张网络吞噬每一个人。真正的身体恐怖。",
"2024|某种物质": "起初是欲望的一体两面，然后在欲望和厌恶之中扭曲、撕裂，最终一分为二，再度重塑畸形之身，真正的怪物产生了。她从始至终都是“被看”的对象，不管是金色的星星、男性的凝视抑或是镜子中那个被厌恶/喜爱的自己，无依无靠，似乎只为取悦之目的而存在。当她的胸部正如他们所愿，真正从头上长出，身体各处也充斥着奇观似的肌肉时，却被斥为怪物，因此最后的爆炸、自毁既是不可避免的，也是悲剧性的——她只有以这样的方式毁灭，才能以一种极具挑衅性的姿态宣布真正的罪恶之源，也只有这样她才终于成为“看”本身。然而现实终究是残酷的，当那摊血肉消失得无影无踪，一切就好像没发生过一样，所有那些权力的压迫以及由此产生的畸形怪物，依旧存在于这个世界上。如果说芭比粉代表着一种极具冲击力的宣言，那么《某种物质》的血腥红，便是压迫与扭曲之世的自我毁灭的怒吼。",
"2024|乔妍的心事": "看之前还以为是纯正的中国故事，期待赵德胤以第三者的视角切入，带来全新的关照中国社会和人际关系的角度，万万没想到还是缅甸、玉石......不是说他的这些元素不好，而是这些元素与大陆语境就是完全不搭调的。到底是要抨击娱乐圈乱象，还是讲姐妹之间的撕扯，含混不清，终究一地鸡毛。隐约可窥见的，依然是赵德胤的“身份”主题，虽然已经被浮夸的剧作撕扯得七零八落。",
"2024|看我今天怎么说": "在听障议题上比《无声挚爱》更先进，从如何融入过渡到拒绝融入，由此展开更大的香港的社会、政治与阶级问题，也是“后香港”时代社会共识解体、沟通失灵的展现，“怎么说”的选择不仅与个体的生命体验有关，更成为一种坚定的表态，孕育抵抗的可能。然而支撑议题的影像与文本难以具有对应的强度，这种单薄也让中后段淡而无味，音效设计是唯一让人感到惊喜的部分。",
"2024|九龙城寨：围城": "Kowloon 1987",
"2024|共同的语言": "在语言的转换和景观的生成中，寻找另一个波斯的踪迹。感觉颇受韦斯安德森、阿基等人的影响，比他们更自由的地方在于，各种地方风物以一种不猎奇的平等姿态徐徐呈现，虽牺牲了剧作的连贯性，却也将人物和他们的经历封印在如梦似幻的影像之中。",
"2024|山区新娘": "比《望向太阳》这种死人电影肯定要好一点，自然主义的摄影和叙事都是对过去的某种回望和致敬，这当然比装模作样的静态影像要好；但这种固执也会过了头，表现战争对大家族日常生活的侵蚀却将战争虚化、悬置，时间跨度极大，人物则如老中十七年文学似乎被划分成不同成分，三条线索没能形成合力，其实单拎出来都有核弹级的冲突点（如女性的觉醒、知识分子的幻灭等），最终两个小时过去像是什么都没讲，一切都淡淡的。",
"2024|越和南": "刚开始还以为要走向僵尸电影，随后徐徐展开，寻找那些离开的人、死去的灵魂和游荡的幽灵，过去与现实在潮湿脏污的矿洞中交汇，两个男人在奇似宇宙星河的无尽中走向百年孤独，一种跨越时空的隐喻。然而以上都被迫建立在极为刻意的影像设计之中，整体的写作也偏向碎片与符号的堆砌，掏耳朵冒火花真的很高级吗？",
"2024|魔法坏女巫": "神似乔治·华盛顿的画像，默默揭示了这个老牌IP的现实意味。绿色皮肤除了种族之表意，也是资本主义发展“非我族类”的表现；奥兹国的美好只是粉饰太平，而所谓“魔法秘典”本来只是合法性的象征，要是真的想拿来建设真正的“乌托邦”，肉食者怎能放过你？",
"2024|异国日记": "轻松舒适的全女电影，或许议题浅尝辄止但情感的连接已经足够动人，爱与恨之外的第三种纽带，在成长的苦涩中建立起来，也让“做自己”不再成为他人的枷锁，而是自身的坚定选择。有惯常的日剧喊和学校演出结尾，虽然因为铺垫不足缺乏情感的力度，却在人物的注视与关心之下亦增添温暖的底色。",
"2024|热辣滚烫": "添加太多情节剧的元素和人物设计让转变来得过于突兀，但文本底层的现实底色和生存困境却极其真实。体重的真实变化令人惊叹，但拳击影像却失去了对身体的持续关注，还是服从于更为套路的设计之中。",
"2025|初吻": "虽然穿越梗不新鲜但这次还是有被打动，说教味少了很多，取而代之的是轻喜剧的框架和出人意料的结尾，给现代人将死的爱情观打上了一剂还算清澈的良药，那些前后呼应的细节让人难忘。27th SIFF",
"2025|炸药屋": "为了追求超越一切的反核主题，甚至不惜往画面上打一大堆字，这种科普视频的尴尬感叠加美式亲情戏的陈词滥调，让紧张感大打折扣，三线叙事早早显出疲态，最后剩下的看点或许是在框定的时空内，某种熵增的快感，也就是“看看到底能乱成什么样”。",
"2025|诗人|西蒙·梅萨·索托": "失意中年男的故事看过太多，堕落或救赎都已成为陈词滥调，而《诗人》选择用温和的愤怒来控诉人生与社会的不公。诗歌艺术沦为伪君子的面具，灯红酒绿让人忘记真正的苦难，而逐渐崩塌的大厦让身处其间的所有人都难以抵挡世俗的诱惑——理想主义在尴尬与窘境中消磨殆尽，他拯救不了任何人，也只能接受所爱之物不可避免的消亡。那些喜剧桥段最终化为孤独者的呐喊，肉身被逐渐消磨，他接受沉默的结局，但或许可以不在沉默中灭亡，于是写下一首快乐的诗，珍惜仅剩的意义——这是诗歌的力量。16mm胶片营造绵密质感，情节与剪辑相得益彰让影片从始至终都保持着极好的节奏，人物刻画全面而立体，男演员更是迸发出惊人演技，让角色入木三分。",
"2025|燃比娃": "如此稀烂的文本还能分成八个章节，神话传说拍不出特色还不如别拍了，真的都一个样。唯一能看的可能就是画面了，依旧国产动画老难题。",
"2025|有用的鬼": "惊艳的长片首作，从恐怖片传统中汲取类型和本土元素，又在视听层面完美呼应了黑色幽默的讽刺属性，甚至比那些装模作样的欧洲电影观感都要好；文本内核直指社会现实和历史创伤，借“鬼”让历史洪流中的众生相活在真实的时空中，亦不回避那些带有民族性的情感锚点，呈现出可观的物质性——也同时体现在极繁的剧作结构中，因此缺乏更直接、简单粗暴的入口。",
"2025|极限竞技": "导演竟是普拉达的二公子，然而长片首作却出人意料地冷峻、精确，解剖了现代专业体育的残酷本质：所谓的运动精神被重新定义为数据、科学训练和专业医疗服务，以及一系列的专业流程，最终让运动员变成一台庞大机器运转的一部分，而观众也不再在场，由摄影机定义什么是体育，其后则是令人毛骨悚然的寂静。伪纪实风格的影像强化了这种观念，体现所谓“技术现实主义”之异化与隔绝，又避免了那种过度痴迷而导致的恋物癖倾向，几乎时刻保持冷静和头脑清醒。只是剧作本身太弱而没有说服力，有时也会显得难以推进。",
"2025|世界日出时": "肉眼能看出来祝新对于影像天然的想象力，镜头设计优美而不显雕琢，音效运用可谓浑然天成，这些都很难在国产电影中看到；但与此同时致命的是，祝新对于现实世界的理解基本上是悬空的，用所谓的语言学设定包了一盘奇幻的饺子，先不谈情节是否合理，光是最基本的通顺都做不到，台词基本处于人机水平，而最终却落到极其苍白凌乱的表达之上，是呼唤和解还是勾勒分裂，基本上混乱而不自知，纵使花里胡哨的设计再多，也难以掩盖内核的空洞、无趣、浅薄。15th BJIFF",
"2025|唯有追忆": "家族史诗言过其实，叙事很简单也没啥波折，但就是情真意切，让人感到去国离乡的悲痛，同一片土地，再回去甚至还要担心说的语言会不会产生危险——温和地讲述痛苦，反倒成为最有力的控诉。",
"2025|阿尔法": "在迪库诺的作品谱系里面肯定是最差的一部，针作为恐惧的符号串联起两段时空的PTSD，然而不论是通过颜色区分还是情节上的不可靠叙事，都始终无法建立起持续有效的机制，最终竟靠一个孱弱的揭秘环节达成了命题作文的主题表达，身体恐怖消失殆尽，海报上的刺青A以如此潦草的方式匆匆结束符号使命，也是令人咋舌。但跳出作品谱系，林奇式的梦境与飘忽不定的行踪、封闭空间营造出的如影随形的恐惧，又具有让人着迷的影像气质。",
"2025|核": "极其直接奔放的宣言式电影，但又不止于口号的宣泄，用DV影像记录搬演的瞬间，那是她们最接近自由的时刻，然而却被学校家庭社会这一庞大的名叫“新加坡”的机器无情灭杀，甚至连拥抱都成为罪过，反乌托邦的压抑现实就是这片土地的底色，而那些空镜头指向的就是萦绕上空的“幽灵”，空间叙事下的囚禁隐喻让人不寒而栗，正如少女只能在学校的工地游玩，公共空间的压缩、私人领域的剥夺都让正常的接触成为一种反抗，或是逆反。",
"2025|爱丽儿": "当那些经典戏剧在当下逐渐式微，路易斯·帕提诺从戏剧本身的张力出发，为莎翁改编注入全新的力量——“世界是个舞台，男男女女不过只是演员”，岛上的居民日复一日完成戏剧，或喜或悲，便是世间芸芸众生的写照，也是命运轮回的现实面貌；逃出戏剧看似大逆不道，但过程中爆发的喜悦与顿悟，又与莎士比亚戏剧的主题不谋而合，由此完成了更当代、更深刻的改编；而那些壮丽的自然风物又赋予戏剧罕见的现实触感，也昭示着人类与自然的联结：便是那些花草树木、山河湖海，才是抵抗一切的力量之源。27th SIFF",
"2025|阿特罗皮亚": "战争背景+黑镜式的讽刺喜剧+元电影切入在美离散群体叙事，设定上就已经赢了很多，印象最深的是那句“我们在这训练美国人，以一种更温和的方式继续入侵我们的祖国”，简直是年度台词级别，与当下美国现状对比则更显唏嘘，这远比那些口号式的呐喊更有意义。",
"2025|寻秦记": "除了情怀还剩下什么？给香港观众的一场春秋大梦，既不够搞怪混搭，也缺少深刻表达，剧作也如儿戏，更不必提廉价的布景和美术。在当下的价值，或许只剩下对历史真伪虚实的审视，以及对某类历史叙事的幻想。",
"2025|拯救地球": "将原作故事嫁接到美国的魔怔人、阴谋论与资本主义话语之中，终于让兰斯莫斯的电影迎来久违的当代性，然而仍是一部投机取巧之作，讽刺和批判一眼都看得到头，文本也被框限在一个极窄的自嗨区间，除去情节冲突剩下的真的只有干瘪的对话；影像层面的故弄玄虚倒是一脉相承，那些视听技法已经被用到没有意义，却敲骨吸髓还要榨取不存在的价值。",
"2025|137号案件": "有极其精准的对警民冲突的刻画，难怪香港无法放映，这当然是戳了肺管子了。抽丝剥茧的过程引人入胜，最显深度的则是多重身份叠加之下的价值观冲突，虽略显直白教条，但仍是创作者沉淀多年对于法国社会尖锐矛盾的洞察，无疑是为右转的世界敲响了警钟。",
"2025|危险动物": "土澳民粹红脖老白男毁灭记，摄像机拍下犯罪过程在当下对应的是短视频的剥削、社交网络的窥探，也让套路满满的大女主逃脱具有了一定的现实意义，然而人物本身又太单薄，结尾恋爱大结局也不能让人信服，前面还一口一个穷人富人呢，最后好像把这茬全忘了。27th SIFF",
"2025|无声挚爱": "有迄今为止对听障群体生存状态最准确的刻画，以及在女性议题、家庭矛盾的背景之下对主体孤独、困苦与欢乐最明确的展现。导演没有滥用听觉上的失聪，而是通过大量细节的铺陈让人体会到这种艰难，并最终用一段反高潮的设计让所有情感达到动人的顶峰。27th SIFF",
"2025|去死吧，我的爱": "有反类型反奇观的处理，也比前作有更精细的声画设计，但整体真是软弱无力，很难看到深度，更像文本的平铺，时空也被压缩到情节剧的层面。",
"2025|爱丁顿": "体感上应该是他最好的一部，前三部总是划定一个主题乐园似的小空间，这部终于让一切都发生在可信的大环境中，虽然地理空间仍框定在小镇，但互联网和各种话语的混杂，让一切荒诞都具有潜在的现实锚点。作为后疫情/后川普时代的美国电影，它不仅将几乎一切当代元素囊括其中，更试图探究这个社会从日常矛盾走向完全崩坏的过程，艾斯特不想给出任何解决方案，而是用一个极其讽刺的结局，暗示僵死的机器绝不可能重新焕发生机。全片像一部没有恐怖情节的恐怖片，艾斯特尽其影像风格之力，拍出疫情叠加剧烈冲突之下一触即发而瞬息万变的紧张氛围，当偏执和狂躁成为时代底色，或许只能目睹人类社会走向疯癫和自毁，迎来太平盛世。",
"2025|恩佐": "简单而美好的少年故事，同时又展现出现实的质地。仰望星空，在这种岁月静好的破灭中，他却能体验到逝去的悸动，以及与外面进行着的世界产生着千丝万缕的联系。",
"2025|F1": "一定要看特效厅的电影，不论从哪个层面看都树立了赛车电影的新标杆：剧作上的跌宕起伏全由F1本身的魅力所带来，在比赛的真实与虚构之间取得完美的平衡，几乎不再单纯渲染速度之快，而是转向F1最精彩的缠斗、策略和内部矛盾，以及围场之外的商业角力与形象运营，终于折射出F1的深刻内涵，不仅仅是肾上腺素和一腔热血，更是群策群力、团结一致的呐喊与激情；而视听语言又极其精彩，革新的技术与真实赛场的拍摄让影像高效而震撼，几乎看不出特效的痕迹，最后一小时更是在一轮又一轮的轰鸣中达到高潮，在感官和智识两个层面登峰造极，无疑是本年度最适合大银幕欣赏的电影之一。",
"2025|邓南遮占领阜姆自由邦": "找来当地素人搬演邓南遮革命史，起初显得滑稽，但很快就能明白导演的用意：当历史逐渐被人淡忘，只有那些生于斯长于斯的人才能用他们的语言重述历史、凝聚共识，抵抗某种既定事实的入侵——当身着历史服装的“演员”被这段历史的亲历者认出，历史真相得以真实地传递；而影片最后将目光投向那些残存的历史痕迹，无疑加强了重塑历史记忆的社群性：当那些搬演都回到了历史现场，那些痕迹也从未远去，我们又有什么理由忘记呢？连同最后狂欢节的歌舞，全片充满了导演对故土亲人的热爱，以及在右翼和民族主义叙事大行其道的当下对真正应该铭记的历史的强烈呼唤。27th SIFF",
"2025|女孩": "原地打转的情节和人物没能构建深入的情感共鸣，影像的回忆质感也因时代背景的彻底缺位而显得毫无空间感和纵深感，哪怕是痛苦的回忆，最终也变得乏味起来。酸楚的童年时光需要一些出口，似乎除了“美国女孩”有关的段落，那些苦涩始终没能排解，潮湿压抑的苦闷或许也是观感的一部分吧。",
"2025|想飞的女孩": "故事本身的写作已经足够刻板无聊，加上的笨贼追杀段落更是令人无语，堆砌到最后什么也不剩，一切设定和人物都来去如风毫无痕迹，确实是飞了。",
"2025|归途": "兄弟情浓度之高就差做一顿了，然后这个剧本像是把所有可能的社会矛盾简单套了一层冲突就疯狂堆砌，老中都不兴这么写了呀。",
"2025|笑刃荒途": "拍这么长可能有讨论的空间，但概念真的很绝，对新殖民主义的洞察没有滑向纯粹的键政大片，而是巧妙结合了个体经验，同时还涉及左派叙事内部的反思和嘲弄，以一种万花筒般的姿态将这些议题浸入绵密的讲述中。影像层面整体的组织无疑是松散的，但有着极为强壮的局部，拉长了的时间和空间比任何时候都接近真实。后1小时确实蛇尾了，但不妨碍它和《接近终点》似乎能一起成为某种末日寓言，在狂沙满天的分裂世界中自我放逐，或许才能求得平静。",
"2025|如果有腿，我会踢你": "以极度可感的影像大力渲染焦虑，借鉴身体恐怖片的构建模式展现日常生活血盆大口的一面，然而内核是一部（绵软无力的）讽刺喜剧，医者难自医和对中产生活的嘲讽都比较低级，逃离旅馆空间的部分是惊喜的，但来上那么七八次也会变得无效；此外便是对母职之折磨惊心动魄的展现，洞和管的隐喻无甚新意，而Rose Byrne极其精准和收放自如的表演撑起了这一切，更像是欧洲电影中才会出现的母亲形象。",
"2025|红玉米": "用碎片化的视角描绘肯尼亚岛民群像，信仰的对立、崩塌与经济的恶化映射现实，而女性处境的勾勒又足够克制，没有鱼的湖水、神秘的疾病和离群索居的老人，这些东西构成了另类的疫情叙事；导演让全素人演员无剧本出演，使得这些文本内生于当地的文化之中，然而视听语言太过寡淡，过于追求某种authenticity以至于观感过于扁平，就连旁白/屏幕特写这类必备的叙事要素也被舍弃，味同嚼蜡。15th BJIFF",
"2025|普通事故": "确实是此地必须要拍却可能永远也拍不出来的电影，起初历史的伤痕引出纯粹的恨，但到了最后才发现铁拳从未离开过半步，一如逼近的脚步声。最宝贵的可能是刻画出泥泞中的挣扎，恨与赦可能就在一念之间，这种道义矛盾带来的内心痛苦，或许只有相似境况的人们，才能互相验证。视听层面当然无法达到金棕榈的高度，但它又是今时今日不可或缺的电影，不可说的恐惧、底层互害的绝望和那个永远在震慑所有人的塔，正是这片土地数百年来历史的真实写照。",
"2025|二〇二五年的欧陆": "应该不是拉肚最好的创作，但确实很现实，直接而戏谑地直面当下欧洲最紧要的议题。漫长的忏悔和掉书袋对话，都指向危机之后的日常状态，犹如行走于薄冰之上的不安感，也有等待大厦将倾的迷茫。逐渐洪化的拉杜裘德，却凭借手机摄影展现某种太平盛世之下的压抑空间，亦是极其具体和可感知的创作，也比任何时候都贴近真实。",
"2025|奇遇": "有着特别棒的叙事结构，回忆或现实随思绪肆意流淌，不回避那些真实的瞬间，但又绝非家庭度假录像，以最简单、写意的创作拿捏住外界环境与人际关系的脉搏，看似普通的家长里短却也成为一场奇遇，电影的魔力又再一次展现在我们面前。",
"2025|左撇子女孩": "情节和人物都有点太肥皂剧和刻板了，用左撇子作成长线索顺拐且刻意，或许只有宜安这个角色有超出常规的弧光。但话又说回来，这样的台北风情似乎很难在当代台湾电影中见到，也能设想出同样的故事换成本土导演会有多俗套，因此确实还是一部难得的华语电影。",
"2025|射雕英雄传：侠之大者": "电影的外围规格几乎一眼能看到头，不论是演员表演、场景设计还是音响效果都是网大水准，项目定位如此；但在情感的捕捉和动作场面的调度上，又显得非常精准，郭靖黄蓉二人雨中重聚段落张弛有度，极其精彩。作为春节档唯一一部反战、反高潮的“非主流”电影，结尾处理可谓大胆，但纵观整个故事，不论情节还是对白又都欠缺打磨，反倒是无法判断语言地道性的蒙语段落还算舒适。",
"2024|太空百合战姬": "斑斓色彩和科幻元素注入千禧浮夸质感，勾勒出独属于酷儿空间的绚烂色彩，高饱和度画风恰如其分展现出种种天马行空，各种议题和符号交融，虽渐渐失去挖掘但依旧传达出骄傲的力量；结尾真是天下大同，普天同庆，众宾欢也！",
"2025|你好，爱美丽": "用瑰丽的画面包裹一个索然无味毫无新意的故事，似乎逐渐成为动画领域的一种趋势，实在是不知道意义何在。有太多太多动人心弦的女孩成长故事，这些故事可以不依靠美丽的画面、奇幻的设定，也可以让人难忘——这部电影显然不在此列。唯一值得书写的比-日跨国背景，最终竟沦为对日本的感情，历史的纵深被拍扁成为一种西方主义的符号，令人哑然失笑。",
"2025|女孩，你怎么了？": "各个层面都缺乏变化，淡而无味的作品，但其实挺适合国内翻拍一下，毕竟有无能丈夫、鸡娃母亲和性压抑的主人公。",
"2025|麦哲伦": "迪亚兹最有钱的一次，看到最后居然有不够看的感觉...",
"2025|至尊马蒂": "缺了一半的萨弗迪兄弟继承前作的混乱与癫狂，这次更野心勃勃，试图串起战后“新世界”的种种议题，冲突接踵而至，但似乎由于商业考量而失去深度——的确有不少精彩的段落，动作的叠加创造节奏，会让人觉得这是斯科塞斯更现代的变奏；然而又有太多的平庸段落，尤以结尾为甚；剧作上的一波三折当然过瘾，妙语连珠的台词不断扩宽它的边界，然而这一切又在这个单一偏执的男主角身上无限垮塌，也让结局变得令人发笑：同样是哭，CMBYN呈现的是深远的夏日感伤，而这里只剩下“出走半生归来仍想做个好丈夫/好父亲”的NPD醒悟环节，戏里戏外倒是形成了有趣的互文。至于那座小金人，衷心希望不要给到他。",
"2025|物质主义者": "感觉没有大家喷得那么差劲，虽然确实画面很美而影像毫无推进作用、几乎全靠对白，但还是喜欢这个旧瓶装新酒的情感故事，三人恋情是障眼法，当代人对亲密关系的不安全感和矛盾心理才是真正的众生相。故事设定真的很东亚，席琳·宋像是那种情感博主，一波三折结束之后，大家都能猜到要回归一个淡淡的结局，倒也释然了。",
"2025|编号17": "好莱坞白左吃拼好饭中毒之前的幻想，过于直球的黑川讽刺反倒显得无能狂怒，娱乐性最后也让位于无趣的左翼议题，前半部分的趣味荡然无存。",
"2025|镜的第三乐章": "有关记忆、创伤、和解甚至历史和政治的痕迹，佩措尔德却拍得不着痕迹、恰到好处，真正用影像捕捉到了难以言说的复杂情感以及极具空间性的生命跳动，生动鲜明又无赘笔，一笔带过的文本细节让故事有了更多值得回味的空间，结尾更是简洁有力而令人动容。也许真的不够有“野心”吧，但这样的细腻所抵达的真实，不就恰恰是我们正在经历的一切吗？",
"2025|睡觉的笨蛋": "虽然依旧是日影传统走向的一个故事，但内部肌理极其真实，连尴尬和沉默的瞬间都有得看；阪元裕吾成功放大了人物之间撞出的火花，生活化的对白、动作拍得极好，情感的把控不浓不淡，或许少即是多，一切都是刚刚好的感觉。",
"2025|尼诺": "几乎全部的表达都只依赖扁平的文本，而在影像层面收效甚微，如此突然的变故，五味杂陈的情感却难以在情节的延宕中凸显，幸好选对了演员，不然难以想象。至于是否在利用这个好好先生的角色来催生，就再说吧...",
"2025|无可奈何": "很欢乐的大商业片体验，比《寄生虫》多了那种实时的、抽象的情节设计，感觉朴赞郁拍得开心，演员也演得开心，只是不知道这个顺拐的剧本是要拍给谁看，中美大老板打个酱油就没有进一步的深挖了，开始进入套路化的开心麻花叙事。",
"2025|浪浪山小妖怪": "用世界顶级的美术水准包装了一个小品级的平庸文本，就像是各种带喜字的综艺拍了个电影版，小人物大梦想的主题可以很中二热血，但不应该是充满刻板符号和情节而迎合市场的陈词滥调。看似有所颠覆，然而很快就露馅，反《西游记》的程度可能还比不上黑神话？",
"2025|新浪潮": "以为是建潮大业，结果是戈达尔装X实录，没有一板一眼呈现拍片过程，更多的是一段时空的再现，一种创作观和思潮的感染，观感非常松弛愉悦，完全踩中了林克莱特的舒适区。",
"2025|痴迷": "拍法和idea都不新鲜吧，但好在最后高潮戏维持住了悬念和气氛，可能现在的电影做减法比加法更重要。最终似乎给出了一个模糊的答案，却正好合乎当下的情感价值和AI浪潮。",
"2025|加沙往事": "前后的割裂感太明显了，也几乎没有令人惊喜的局部，或许需要更大剂量的类型化调味。",
"2025|一战再战": "用精确而戏谑的笔触勾勒“全球第一政治撕裂国”的荒谬现实，或许被有心之人用作反美武器，抑或是被肤浅解读为左与右的游戏，但PTA绝无此意。一场又一场具体的战斗取代了简单的正邪对立，而转瞬即逝的闪光瞬间，例如动作、台词、符号乃至笑点，又与难以归纳的情节碰撞出具体、当代的火花。深刻的洞察寓于精准的类型化影像之中，喜或悲都难以言明，批判的期望最终走向略带嘲讽的和解，走向非暴力不合作的爱与和平——或许因商业属性的掣肘部分场景和情节仍值得讨论，但纵观全片PTA无疑接过了那些伟大作者的衣钵，是属于美国的当代电影大师。",
"2025|巴勒斯坦36": "议题的紧迫性显然压过了视听和剧作层面的打磨空间，视点漂移故事稀烂人物刻板，很不想给差评但是拍成这样真的不如我国的主旋律了。就是这种程度的自我反思，都进不去欧洲三大电影节，足以想象阻力有多大。",
"2025|便衣警察": "可以说这个故事其实很俗套吗，在同影的序列里都属于不新鲜的那一种。其实作为新导演首作还是有可取之处，除去影像层面对VHS质感的模拟，还拍出了绵延不断的感情线，用声画关系不断编织情感的厚度，虽然配乐有点过头，但至少不难看。",
"2025|众生相": "只有做爱时我们才真正聊天",
"2025|死钻倒影": "高速的无缝剪辑将特工电影的一切物质痕迹都卷入其中，肉眼所见皆被赋予浓浓仪式感与剥削痕迹，这种再创造几乎将时间肢解，面孔在不同时空中自由游弋，似乎永不停歇；走火入魔的过气特工对应三重身份，当全球化与计算机成为新时代的承诺，漩涡中心的秘密特工面临的危险与诱惑，正如皮革之下的蛇蝎女，而最后那张面具终于叠加于男性气概之上，精心设计的007媒介考古，也最终成为一曲暧昧的挽歌。",
"2025|狂野时代": "试图六感发达重拾电影魅力、抒发末日遗绪，却最终沦为影像游戏和奇观堆砌——影史经典一拍再拍，最终却仍依靠平庸的剧情元素完成命题作文，影像的诗意几乎在唬人的装置艺术和若有所思的文本碎片中消磨殆尽，沉重的虚无感最终是无病呻吟和自我重复；强调造梦机器的魔力，却像是梦到哪句说哪句，如果能从一部优秀的作品中看到灵魂和精神，那现在呈现在面前的大概只是一个空洞、浅薄、故弄玄虚的创作而已。不过还是要恭喜，艺术电影也有自己的姜文了，或许比起后者，毕赣甚至没有什么好说的，就像那场寺庙对话，绝没有想到会这么无趣和苍白。",
"2025|朝圣": "卡拉·西蒙延续流畅自然的风格，缓缓铺陈一段家族故事、私人历史，在画外音的讲述中，在低清的DV录像中，在小镇的阳光和海水中，女孩重建过往的时空轮廓，漫游天地间，从人与人的连接中找到自己的位置，在重塑往事的过程中不断吸取养分，走向不确定的未来。或许更吸引人的，是全片清新真挚的情感流动，以及从细小切口展现时代，却绝不成为议题附庸的坚定。",
"2025|情感价值": "小题大做。少拍点这种电影节做题家电影对大家都好。",
"2025|寂静的朋友": "确实是越回味越寡淡无味了，开头上课+面试感觉把话都已经说完，那种人类之外关系的刻画以及跨越时空的诗意，都拍得好像白开水，美则美矣，离僵尸电影只剩三厘米了。但是又觉得疏离、孤独的感觉与植物之间能达成某种和谐，即使万物有灵已经是一个说烂的东西，即使那些科学段落都像浪漫化的想象。",
"2025|罪人": "似乎只勉强能勾勒出宏大命题的轮廓，然后就用杂七杂八的元素和隐喻恨不得从头到尾塞满，却让人难以摸清脉络（因为他自己也没想写清楚），情节的曲折被简化为大逃杀，最后用没头没尾的假大空台词串联一切，你是罪人不是谜语人；世界人民大团结段落广受赞誉，但也只不过是众多无效奇观中的一部分，几乎完全依赖文戏的铺垫导致前半段又臭又长、有效信息极少，难以进行高效的叙事，看得很难受，被乔丹·皮尔秒得渣都不剩，更别说极其流水线、平庸而毫无质感的镜头语言了，这比漫威也没好到哪去。最反感的部分或许是这股子装腔作势、故弄玄虚的姿态，每场戏都极其虚伪，嘴上说着不是黑人vs白人，但最后不还是安排了一场屠杀白男的戏吗？用一个看似跨越历史、种族的宏大框架包裹一部爽片没有意义，更何况你的受众确实也爽到了。",
"2025|接近终点": "黄沙漫天的末日回响，震碎一切可能的信仰。不同于其他科幻作品的峰回路转，拉克谢用炸裂的肉身告诉你一切希望都是徒劳，最终和幸存者在开往无尽虚无的列车上艰难摸索重生的可能。最大败笔可能是结尾闯关式的“Sirat”全靠配乐支撑，而这种荒漠挣扎的具身书写也不够有力，至少这不是什么新的东西。",
"2025|对不起，宝贝": "非常强的写作，从真实的日常碎片、人情关系徐徐展开，不靠情节剧推进，亦警惕陷入纯粹日常的记录；制度性的元素又营造出极具社会批判性的背景，无时无刻不在提醒着这些痛楚绝非个体行为，而与崩塌的世界息息相关。当文学不再具有疗愈人心的力量，当痛苦逐渐无人理解，她反倒愈加淡然地面对这个世界，因为她没有错。",
"2025|望向太阳": "一开始的屋内长镜头就创造性地将同一空间不同时间的人物并置，摄影机如鬼魂一般穿梭于其间，串联起四代女性的悲剧命运；然而在此之后越来越多的影像碎片不断堆砌，死亡成为主线任务，人物在僵硬的动作中逐渐丧失主体性，音效也喧宾夺主，此时观感就变得无聊起来。哪怕费尽力气仔细分辨四个时代的区别、搜寻故意被隐藏的人物关系，到头来也会发现带来的震撼不比单纯的旁白来的多，也证明了影像本身的无力和垮塌：尽管细节上极其考究、女性视角与社会历史的结合也偶有亮点，但余下的大部分时间只有不知所云的场面调度和令人疲惫的叙事游戏。",
"2025|巴黎夏日": "哪怕有对于公权力、左翼反奥运人士和“城里人”有戏谑刻画，但核心仍是呼唤最真诚、最动人的热爱——这种纯粹在骚动的巴黎夏日之下更显可贵和迷人，一如结尾的碧海蓝天；这样的表达借由内省的角色塑造呈现，更为影片增添一层思辨的维度，用一次并不完美的旅途勾勒出她的经历和选择，其中所折射的那份坚定与赤忱闪耀着她的生活，就像缓缓流淌的钢琴旋律一般沁人心脾。15th BJIFF",
"2025|植物学家": "观感非常舒适的新导演首作，把北疆的风景和人都拍得清新自然，同时几乎没有外来者眼光的凝视；同样的特征也见于文本和人物写作，但这种略带感伤的假日时光故事，似乎难以看到深挖的痕迹：社会和民族议题语带暧昧，而主人公与哥哥（叔叔）相似的生活轨迹、非线性的梦幻碎片和民俗传说的剪影，都留下太多可供填补的空白了，如果最终理解为成年主人公对童年的一次重访，似乎也不新鲜。把草原拍成沙滩足够有趣，但那颗迪斯科灯球，似乎是毕赣病毒传播后的结果。",
"2025|水之年代": "以水为线索串联女性经历，全片亦氤氲湿润质感，好似模糊不清的回忆在痛楚和创伤中一遍遍被磨洗，无法被安放的不安全感贯穿始终。视听上都很有想法的导演首作，只是逐渐在纷繁复杂的蒙太奇中失去连贯的节奏和力度，碎片化的呈现也偶有忘乎所以的感觉，有时会觉得不应该拍得这么浪漫和洒脱。",
"2025|火遮眼": "动作设计无疑树立了新的标杆，在炫酷刺激和真实触感之间找到完美平衡，亦结合暗黑废墟霓虹灯美学设计，创造出独一无二的视觉奇观。尽管剧作和人物设定几无亮点，但好在目的明确，剪辑也让动作戏有了排山倒海的观感，让那些痛感都足够真实。",
"2025|罗小黑战记2": "可能是国产电影里类型化最成功的，也可能是国产动画里少数不靠低级趣味写作的，这两点已经非常难得了，它守住了基本的底线。",
"2025|光": "对白左家庭的嘲讽算是唯一亮点，此后观感基本上就是“我倒要看看你这烂摊子要怎么收场”，疯的傻的尬的都玩过一遍之后戛然而止，原来是叙利亚阿姨用白左当耗材超度自己人，导演你敢这么拍也是太吓人了，只好祝你们德国一切顺利了。",
"2025|主谋": "莱卡特几乎放弃前因后果的剧本写作，反倒赋予人物无限可能；爵士乐的摇摆之下，隐藏着《美国牧歌》式的虚无与迷茫，成为通缉犯和反战游行同构，撕裂了“斩杀线”之上看似平淡的生活，最终在自我放逐与流浪的旅途中重新体验美利坚的血肉。对生活日常和人物状态的描绘无疑是大师级，但比起《一战再战》的波澜壮阔，还是稍显平淡而缺乏现实的冲击力。",
"2025|弗拉明戈的神秘眼神": "如荒漠上盛开的迷离之花，将不堪的现实转化为浪漫的瞬间、痛楚的回忆，然而不论是酷儿议题还是影像技法都不新鲜，前后段仿佛判若两片。无法进入的最大阻碍，可能是始终无法寻找到这个1982年故事的真实性，或许更像一段寓言故事，归根到底还是顺直不得好死。",
"2025|腓尼基计划": "似乎是一个现代资本游戏的架空变奏情节，因此比前两部都”好看“，也维持了一定的当代性，然而迅速就转到舞台剧布景和人物游戏拼贴，缺少前作在时空层面给人具体可感的触觉，而结尾依旧落到家庭和解、父亲形象的变化，与故事主线产生的巨大落差透露出韦斯·安德森一丝丝的老保意味。",
"2025|密探": "重建历史而非刻画历史，太多类似的电影都让我们习惯了一种奇观式、叙事式的社会历史再现，但鲜有似《密探》这样，聚焦被独裁统治渗入的时间与空间之中。门多萨交出迄今为止的集大成之作，如此轻松地将各种议题、符号与影像风格熔于一炉，在累西腓这片土地上尽情施展影像的魔法，正如最后半小时随着桑巴音乐涌动而达到高潮的故事——但门多萨足够清醒，狂欢节是麻痹的、掩盖真相的，这段历史也不该被人沉溺。如今只能从碎片中拼凑历史的痕迹，巴西独裁统治如此，文化大革命也是如此，在遗忘的浪潮中有人还愿意追踪，然而利益相关的当事人或许早已忘却，我觉得这是对当下的一种警醒。",
"2025|日掛中天": "很难得的拍出时代下的绝望氛围，中近景下的人物如行尸走肉般穿行，在道德困境和外界压力下惶惶不可终日，狗血奇情实则折射出对“亏欠”的恐惧感和畸形扭曲的情感纠葛，结尾的处理举重若轻，毛骨悚然的心境变化伴随着辛芷蕾的痛哭，但最后却消散于人群中，暗示众生皆苦的悲剧命运——但这情债，是不是非得让女人来承担呢。情节上的几处突转让人摸不着头脑，全片几乎由对话推动，对动作和时间的忽视让它像八点档作品，而张颂文过于端着的表演又让人对这一角色的经历完全无法信服，大部分时候没有狠劲而只是让人厌烦。",
"2025|安·李的遗嘱": "和《粗野派》共享主题和优缺点，好的地方在于从一个异质与非野蛮化的视角探讨何为美国，以及刻画那些独特而超越历史语境的人物经历，当然是针对当下的表达；而共同的缺点就是空有一个卓越的美学外壳，却常常让人抓不住重点，与其雄心勃勃地展现人物一生的经历，倒不如放大一些切片，更令人印象深刻：很多瞬间本应拍得隽永而富有神性（例如游历新英格兰），完全可以放慢速度展现真实的流速，却被旁白和走马灯似的剧作不断干扰，最终也只是高级一点的百科式呈现。",
"2025|欣德·拉贾布之声": "几乎是为了那几段录音配戏，沦为一些简单粗暴的呼号和呐喊，但这样紧急且重要的题材，社会意义其实大于电影本身，依旧有强大的情感凝聚力，尤其是结尾。",
"2026|时间戳": "在空袭警报的日常中窥见战争的阴霾和疼痛，或许文献价值大过电影本身，但展现这种异常状态下的日常生活，亦是从另一维度刻画战争的方式。",
"2025|无双": "很抓马但又有很多真实的情感和表达，我们男同性恋的一生就是这么如履薄冰、撒谎成性，始终渴望那个得不到的crush，也会在一切搞砸之后重新思考和解的可能，虽然最后还是会陷入幻想之中，比如还是想做中产阶级岁月静好地过日子......",
"2025|街头顽童": "明显看出英国前辈导演的影子，没有那种坐立不安的锐利感，聚焦于人物而得以捕捉细微的情绪与肢体变化，亦能自信地将人物投入外部空间中。除去几个不明所以的段落，还算是一部耳目一新的导演首作。",
"2025|战·争": "不太明白这种虚伪的写实有什么意义，标题起得很大然而容量极小，若只是想反映“真实”战争场景，那结尾的真实人物对照又很难不让人去反思战争背后的意识形态冲突（而这正是它极力避免的，就像科技公司用以炫技的demo）；好在一切都足够简洁，加兰这一次不再装神弄鬼，极高的完成度与极专注简练的叙事或许能为类似不带脑子的影视/游戏作品树立标杆。",
"2025|大自然对你说了什么": "有点像农家乐，确实不适合敏后降临了。",
"2025|玛丽埃尔都知道": "一个设定玩到死的典范，感觉30分钟过后就没啥可拍的了，女孩的不可靠叙事也在最后如蜻蜓点水一般结束了，除了展现德国白左家庭的虚伪意外一无是处，女孩的人物弧光约等于零，主竞赛还不如选《光》有节目效果。",
"2025|风来之所": "仅限于有趣流畅的公路青春片，但既不够当代也不够批判，将逃离的希望寄托在“境外势力”的奖励之上，本身就是一种新型的殖民主义，影片缺少这方面的反思，反倒将其作为贯穿全片的线索，令人遗憾。女主角的人物刻画起初相当精彩，甚至呼应了宗教、女性和性少数议题，但到了影片后段也流于俗套，仿佛让她回归家庭就能抚平此前的种种苦难，而对出走之后的现实充耳不闻。27th SIFF",
"2025|狐步": "拍出了创伤后那种看不见的疼痛与恐惧，也展现出在一个有毒男性气质爆表的环境里“诛杀异类”的过程，所谓”看你不爽“的背后机制大概就是如此，对两性关系的刻画也在意料之外。剧作和人物设计略显随意，好在靠视听挽回一些。",
"2025|是的": "给权贵当舔狗最终只会一无所有，倒不是谁来变了天地，只是会在无尽的矛盾与折磨中亲眼看着自己的灵魂毁灭——但这种毁灭更是肉身的疼痛，拉皮德将这种感官折磨拉到最大，他用近乎疯狂的影响试图告诉所有人：生活在一个黑白颠倒的世界中、目击非人暴行，你选择顺从，信仰会逐渐崩塌，所爱之人会逐渐远离，而那具残破的肉身，将浸泡在暗无天日的恶心之中，直到被黑洞吞噬。",
"2025|你行！你上！": "阳灿的平行宇宙续集，即使人到中年却难忘红色革命热情，与老中丧偶式育儿和做题家思维糅合，最终竟产出音乐巨星，既传奇又荒谬——姜文用夸张的表演、疯狂的调度和近乎惊悚片的剪辑极尽渲染那种闷头的热情与疯狂，有时候这样的处理使反讽与解构接近感官层面的刺激，但有时候也迷失在他一贯的耍贫嘴、双关语的“隐喻”之中。",
"2025|年轻母亲之家": "走向短剧的达内：五段故事被分散开，人物失去连贯运动的可能，只剩下展现苦难的切片；现实主义的力度仍在，但也仅仅止步于此。",
"2026|后室": "其实很容易就能把这个题材拍成非常套路的逃脱类型片，后果就是让这个ip变成平庸无趣的流水线产品，幸好他们没有这样做。后室在这里已经变成一种社会文化的载体，一种历史空间和审美结构，在视觉上几乎是集此前所有类似元素于一炉，整体的美学风格极其精准统一，又不完全是此前A24的翻版；剧作其实很有必要，不论是心理惊悚还是社会历史点缀，都让这个ip有了具体的语境。毕竟，从后室这类美学风格中获取的恐怖感，本就内生于一系列具体的事物：那些标准化的装修、灯管的白噪音、微缩的中产景观，的确来自一个经济下行的时代，后室也因此成为一个容纳集体记忆的场域——被弃置的记忆碎片在此随意组合，潜伏于日常空间的角落，不时向人们发出警告。",
"2026|给阿嬷的情书": "价值观保守陈旧就不讲了，毕竟大家还是好这口，感觉最抽象的可能是地方历史丧事喜办的处理，最后还是要讲先苦后甜和情义，却从始至终没有扭转过任何叙事，明明从头到尾从未缺席的除了钱还是钱，不妨把事情讲得更清楚一点嘛。对金钱和事业的渴望与前现代的道德感化二者融为一体，配上Seedance同款廉价至极的影像风格，恍惚之间确实会疑问今夕是何年。",
"2026|揭秘日": "在50年后，对外星生物的热情被替换为惊恐，在这个信仰崩裂、世界动荡的年代，外星生物的价值不再被确认，而掌权者开始对反对者进行追捕，在这种背景下斯皮尔伯格拍出了他世界里的《一战再战》：在不断的逃亡中一次次确认共情与同理心的力量，直至这种力量强大到足以通过一个眼神、一段影片，就能让整个世界颤抖。尽管剧作细节偶尔跳出三界之外，但斯皮尔伯格仍用教科书般的影像组织不断叩击那扇终极的、代表某种崇高理想的信仰之门。从第一场戏开始，所有人就被拽进悬崖边缘的紧张气氛中，直至举重若轻的揭秘时刻的来临。",
"2026|一个部门的诞生": "虽然遗憾于港片现在也有故事发生时间限制了（2019之前），但仍是一部两岸三地都难得的在地性极强、反映时代气氛和情绪的电影，看的时候很难不去想象这些角色在故事之外都有怎样的经历——这些才是退订情绪高涨背后的症结所在。不能要求一部合拍片突破某些红线，但片中对警、民、劳、资几方关系的刻画，也算是难得一见。在这种嬉笑怒骂的大杂烩式电影中暗戳戳塞入一些创伤的脉络和批判的锋芒，可能是今后港产片的默契点。",
"2026|河狸变身计划": "开场十分钟，皮克斯就让社会议题、政治批判与讽刺介入叙事之中，足以可见在当下的社会环境，就连小孩也必须要承受左右叙事撕裂的冲击，情节和人物都具有现实的刻度，已经很难得。中段一度左右互搏，主人公的选择或许也不能让人满意，但结尾用大火与滔天洪水的隐喻呼唤弥合左右撕裂的可能，或许永远不会互相和解，但至少打开了沟通的窗口——皮克斯这种美好的寄托似乎只是一厢情愿，也许这个时代再也不会有达成共识的时刻。",
"2026|夜王": "没有想象中的笑翻天和高级笑料，但仍是春节档最佳，适合不想被北佬说教/喜剧片毒害的观众。对女性的刻画比起预料中的刻板和男本位的叙事要丰富许多，唯一女性编剧何妙祺一定发挥很大作用，尽力把物化的剥削的元素转化为在一定程度上有所自反的叙事，角色的情感表达也很细腻，已经很不容易；更大主题是香港电影有一部算一部的“悼明”精神，但这种怀念不令人感到说教，而是借助所谓“人情味”、“义气”，持续呼唤一个幻想中的团结、奋斗的香港社会——但最终的命运也或许和夜总会的消亡一样，只能“灿烂到此”。第三幕如谍战悬疑片一般的夜场局中局，我们或许能稍稍看到一点香港电影昔日的荣光，但也到此为止。",
"2026|挽救计划": "大失所望，美国人请停止把外星生命都想象成你们美国人的样子，真以为是养宠物呢？",
"2026|奥德赛": "离不及格只差两厘米的诺兰，对于荷马史诗的改编在文本和话语上都看不出什么新的东西，小心翼翼地在不逾越任何红线和颠覆性的情况下，把几个母题拉了一遍，仿佛外国文学教材；对IMAX的痴狂实实在在地影响到全片的观感，摄影混音都可能是生涯最差，沉迷于宏伟的大场面、真实感与沉浸感，反倒透露出另一种层面的胆怯（冗长的篇幅便是一证）。龙傲天叙事倒没什么问题，如果能放下一系列唬人的预先建构，或许更有说服力。",
"2026|呼啸山庄": "以一种过于现代的、媚俗的姿态强调病态的情欲，然而不管喊得有多大声、做得有多频繁，依旧像隔靴搔痒的过家家，一个用力过猛一个毫无演技，加上导演大幅退步的视听技法，猎奇变态的奇观难以掩盖人物之空洞、情节之老套，当然如果大家都很压抑那可能确实需要这样的电影获取一些勇气。"
};
